def safe_json(raw, fallback=None):
    """Parse JSON bytes/str safely, returning fallback on empty or invalid input."""
    if fallback is None:
        fallback = {}
    if not raw:
        return fallback
    text = raw.decode() if isinstance(raw, bytes) else raw
    if not text.strip():
        return fallback
    try:
        return json.loads(text)
    except Exception:
        return fallback
