def _onenote_parse_date_bound(value, end_of_day=False):
    """Return a UTC-ish ISO timestamp string for YYYY-MM-DD/date-like input."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})", raw)
    if not m:
        return ""
    suffix = "23:59:59Z" if end_of_day else "00:00:00Z"
    return "{}-{}-{}T{}".format(m.group(1), m.group(2), m.group(3), suffix)

def _onenote_page_in_date_range(item, date_from_iso="", date_to_iso="", date_mode="created"):
    """Filter OneNote pages by created/modified/either timestamp for section page scans."""
    if not date_from_iso and not date_to_iso:
        return True
    mode = _onenote_normalize_date_mode(date_mode)
    if mode == "modified":
        keys = ("lastModifiedDateTime",)
    elif mode == "either":
        keys = ("createdDateTime", "lastModifiedDateTime")
    else:
        keys = ("createdDateTime",)
    dates = []
    for k in keys:
        v = str((item or {}).get(k) or "").strip()
        if v:
            dates.append(v)
    if not dates:
        return False
    for v in dates:
        if date_from_iso and v < date_from_iso:
            continue
        if date_to_iso and v > date_to_iso:
            continue
        return True
    return False

@app.route("/onenote/import_recent", methods=["POST"])
def onenote_import_recent():
    data = request.get_json(silent=True) or {}
    try:
        top = max(1, min(int(data.get("top") or 10), 100))
    except Exception:
        top = 10
    search = str(data.get("search") or "").strip()
    date_from_iso = _onenote_parse_date_bound(data.get("date_from") or data.get("from"), end_of_day=False)
    date_to_iso = _onenote_parse_date_bound(data.get("date_to") or data.get("to"), end_of_day=True)
    date_mode = _onenote_normalize_date_mode(data.get("date_mode") or data.get("date_type") or "either")
    try:
        # v24.6.80: date/range scanning is intentionally filtered locally after
        # reading recent OneNote pages. This avoids relying on Microsoft Graph
        # OneNote $filter support, which can vary by tenant/client behavior.
        fetch_top = max(top, 50 if (date_from_iso or date_to_iso) else top)
        fetch_top = min(fetch_top, 100)
        params = {"$select":"id,title,createdDateTime,lastModifiedDateTime", "$orderby":"lastModifiedDateTime desc", "$top": str(fetch_top)}
        if search:
            params["search"] = search[:120]
        d = _ms_graph_json("me/onenote/pages", params=params, timeout=25)
        raw_items = (d.get("value") if isinstance(d, dict) else []) or []
        items = [it for it in raw_items if _onenote_page_in_date_range(it, date_from_iso, date_to_iso, date_mode)]
        items = items[:top]
        pages, combined = [], []
        for it in items:
            pid = str(it.get("id") or "")
            if not pid:
                continue
            try:
                raw = _ms_graph_bytes("me/onenote/pages/{}/content".format(urllib.parse.quote(pid, safe='')), timeout=25)[0]
                text = _onenote_html_to_text(raw)
            except Exception as inner:
                text = "[Could not read OneNote page content: {}]".format(str(inner)[:200])
            title = str(it.get("title") or "Untitled OneNote page")
            pages.append({
                "id": pid,
                "title": title,
                "lastModifiedDateTime": it.get("lastModifiedDateTime", ""),
                "createdDateTime": it.get("createdDateTime", ""),
                "text": text,
                "preview": text[:600],
            })
            if text:
                combined.append("--- OneNote Page: {} ---\n{}".format(title, text))
        return jsonify({
            "ok": True,
            "pages": pages,
            "combined_text": "\n\n".join(combined),
            "filters": {"search": search, "date_from": date_from_iso, "date_to": date_to_iso, "date_mode": date_mode, "requested_top": top, "scanned_pages": len(raw_items)},
        })
    except PermissionError as e:
        return jsonify({"error": str(e)}), 401
    except urllib.error.HTTPError as e:
        body = e.read().decode(errors="replace")
        return jsonify({"error":"Microsoft OneNote import failed", "status": e.code, "detail": body[:1000]}), e.code
    except Exception as e:
        return jsonify({"error": str(e)}), 500


# ── OneNote → JobAdder Screening Call Notes ─────────────────────────
def _ja_post_json(path, payload, timeout=15):
    """POST JSON to a JobAdder API path using the current server-side token."""
    return _JOBADDER_CLIENT.request_json(
        path,
        method="POST",
        body=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        timeout=timeout,
        raw_fallback=True,
        safe_to_retry=False,
        retries=0,
    )

def _ja_get_json(path, timeout=15):
    """GET JSON from a JobAdder API path using the current server-side token."""
    return _JOBADDER_CLIENT.request_json(
        path,
        method="GET",
        headers={"Accept": "application/json"},
        timeout=timeout,
        raw_fallback=True,
    )


def _ja_put_json(path, payload, timeout=20):
    """PUT JSON to a JobAdder API path using the current server-side token."""
    return _JOBADDER_CLIENT.request_json(
        path,
        method="PUT",
        body=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        timeout=timeout,
        raw_fallback=True,
        safe_to_retry=False,
        retries=0,
    )


def _ja_compact_error_body(body, max_len=1200):
    raw = str(body or "").strip()
    if not raw:
        return ""
    try:
        parsed = safe_json(raw, {})
        if isinstance(parsed, dict):
            for k in ("message", "error_description", "error", "detail", "title"):
                if parsed.get(k):
                    return str(parsed.get(k))[:max_len]
            return json.dumps(parsed, ensure_ascii=False)[:max_len]
    except Exception:
        pass
    return raw[:max_len]


def _ja_maybe_int(value):
    """Return an integer when JobAdder expects numeric IDs, otherwise a string."""
    text = str(value or "").strip()
    return int(text) if text.isdigit() else text


# v24.6.97-v24.6.116: user captured the real JobAdder web payload for the tenant's
# Activities > Screening > Candidate Screening Call form.  Prefer the exact
# activity setting/question-ID shape before generic API guesses.  Do not include
# the captured activityID (it looks like JobAdder creates that per activity).
#
# The live API diagnostic then confirmed the valid endpoint is
# candidates/{id}/activities, but JobAdder rejected answers[] because that API
# expects answers to be an object (ActivityAnswerListModel), unlike the web UI
# devtools payload.  Therefore transfer now tries object-wrapped answer shapes
# first and keeps the browser-like array shape only as late diagnostics.
_ONENOTE_JA_SCREENING_SETTING_ID = 8225
_ONENOTE_JA_PRESENTABILITY_QUESTION_IDS = [62988, 52988]
_ONENOTE_JA_SCREENING_QUESTIONS_BASE = [
    (41172, "Brief Overview of Experience", "brief_overview"),
    (41173, "Reason For Leaving", "reason_leaving"),
    (41174, "Looking For", "looking_for"),
    (41175, "Current Salary Breakdown", "current_salary_breakdown"),
    (41176, "Expected Salary", "expected_salary"),
    (41177, "Notice Period", "notice_period"),
    (35900, "Leads - Follow format: Active (Client - Role, Stage, Y/N)  Y denotes agency representation", "leads"),
    (41178, "Remarks and things to take note", "remarks"),
]


def _onenote_screening_remarks_value(fields, note_text=""):
    remarks = _onenote_clean_field_value(
        (fields or {}).get("remarks")
        or (fields or {}).get("red_flags")
        or (fields or {}).get("next_steps")
        or (fields or {}).get("raw_presentability")
        or ""
    )
    if remarks:
        return remarks
    # Keep remarks blank unless the note explicitly has a remarks-ish field.
    # Full raw note is not copied here to avoid dumping excessive text into a
    # tenant-specific field that is often meant for brief recruiter reminders.
    return ""


def _onenote_presentability_rating_int(fields):
    """Return a strict Presentability rating from 1 to 4, or ``None``.

    Accept the normal one-digit value, an explicit ``3/4`` / ``3 out of 4``
    score, or a labelled ``rating 3`` form.  Do not pull a stray 1-4 digit from
    values such as ``14``, ``40``, ``10/4`` or ``4 years``.
    """
    text = str((fields or {}).get("presentability_rating") or "").strip()
    if not text:
        return None
    m = re.fullmatch(
        r"(?:presentability|rating|score)?\s*[:=\-–—]?\s*([1-4])"
        r"(?:\s*(?:/\s*4|out\s+of\s+4))?"
        r"(?:\s*[-–—:]\s*[^\d].*)?",
        text,
        re.I,
    )
    if not m:
        m = re.fullmatch(r"\s*[^\d]{0,60}([1-4])\s*(?:/\s*4|out\s+of\s+4)\s*", text, re.I)
    return int(m.group(1)) if m else None


def _ja_presentability_answer(qid, qtext, rating, mode="rating_full"):
    rating = int(rating) if str(rating).strip().isdigit() else rating
    rating_text = str(rating) if str(rating).strip() else ""
    answer = {
        "questionID": qid,
        "questionId": qid,
        "question_id": qid,
        "activityQuestionID": qid,
        "activityQuestionId": qid,
        "ratingQuestionID": qid,
        "ratingQuestionId": qid,
        "questionText": qtext,
        "questionType": "Rating",
        "answerType": "Rating",
        "fieldType": "Rating",
        "controlType": "Rating",
        "dataType": "Rating",
        "type": "Rating",
        "textValue": "",
        "startDateValue": None,
        "endDateValue": None,
        "numberValue": None,
        "numericValue": None,
        "decimalValue": None,
        "booleanValue": None,
        "singleSelectValue": None,
        "multiSelectValue": [],
    }
    # v24.6.116: live JobAdder diagnostic accepted object-shaped answers but
    # still complained: "All rating mandatory questions are required." This
    # means the endpoint/answer object shape is close, but the rating field name
    # is not one of the normal text/numeric fields. JobAdder web renders
    # Presentability as a required 1/2/3/4 button, so the first payload now
    # includes common rating/select aliases in one object. Unknown fields are
    # ignored by the API deserializer, while the correct rating field can satisfy
    # the mandatory rating question.
    def add_rating_aliases(include_text=False, include_select=False):
        answer["ratingValue"] = rating
        answer["rating"] = rating
        answer["ratingScore"] = rating
        answer["score"] = rating
        answer["value"] = rating
        answer["answerValue"] = rating
        answer["selectedValue"] = rating
        answer["selectedRating"] = rating
        answer["selectedRatingValue"] = rating
        answer["optionValue"] = rating_text
        answer["selectedOptionValue"] = rating_text
        answer["answerOptionValue"] = rating_text
        answer["numberValue"] = rating
        answer["numericValue"] = rating
        if include_select:
            answer["singleSelectValue"] = rating
            answer["selectedOptionID"] = rating
            answer["optionID"] = rating
            answer["answerOptionID"] = rating
        if include_text:
            answer["textValue"] = rating_text

    if mode in ("rating_full", "rating_aliases"):
        add_rating_aliases(include_text=True, include_select=True)
    elif mode == "rating_value":
        answer["ratingValue"] = rating
        answer["rating"] = rating
    elif mode == "number":
        answer["numberValue"] = rating
        answer["numericValue"] = rating
    elif mode == "decimal":
        answer["decimalValue"] = float(rating)
        answer["numericValue"] = rating
    elif mode == "single_int":
        answer["singleSelectValue"] = rating
    elif mode == "single_text":
        answer["singleSelectValue"] = rating_text
    elif mode == "single_object":
        answer["singleSelectValue"] = {"id": rating, "value": rating, "text": rating_text, "name": rating_text}
    elif mode == "text":
        answer["textValue"] = rating_text
    else:
        add_rating_aliases(include_text=False, include_select=False)
    return answer


def _ja_screening_call_answers(fields, note_text="", presentability_question_id=None, presentability_mode="numeric"):
    fields = fields or {}
    rating = _onenote_presentability_rating_int(fields)
    values = {
        "brief_overview": _onenote_clean_field_value(fields.get("brief_overview", ""), max_len=8000),
        "reason_leaving": _onenote_clean_field_value(fields.get("reason_leaving", "")),
        "looking_for": _onenote_clean_field_value(fields.get("looking_for", "")),
        "current_salary_breakdown": _onenote_clean_field_value(fields.get("current_salary_breakdown", "")),
        "expected_salary": _onenote_clean_field_value(fields.get("expected_salary", "")),
        "notice_period": _onenote_clean_field_value(fields.get("notice_period", "")),
        "leads": _onenote_clean_field_value(fields.get("leads", "")),
        "remarks": _onenote_screening_remarks_value(fields, note_text),
    }
    answers = []
    for qid, qtext, key in _ONENOTE_JA_SCREENING_QUESTIONS_BASE:
        answers.append({
            "questionID": qid,
            "questionText": qtext,
            "textValue": values.get(key, ""),
            "startDateValue": None,
            "endDateValue": None,
            "numberValue": None,
            "numericValue": None,
            "decimalValue": None,
            "booleanValue": None,
            "singleSelectValue": None,
            "multiSelectValue": [],
        })
    answers.append(_ja_presentability_answer(
        presentability_question_id or _ONENOTE_JA_PRESENTABILITY_QUESTION_IDS[0],
        "Presentability (Confidence, Comms, Business Awareness)",
        rating or "",
        mode=presentability_mode,
    ))
    return answers


def _ja_answers_object_variants(answers):
    """Return ActivityAnswerListModel-compatible shapes to try before answers[]."""
    by_qid_full = {str(a.get("questionID")): dict(a) for a in answers}
    by_qid_text = {str(a.get("questionID")): (a.get("textValue") or "") for a in answers}
    return [
        {"items": answers},
        {"answers": answers},
        {"activityAnswers": answers},
        {"values": answers},
        {"questions": answers},
        by_qid_full,
        by_qid_text,
    ]


def _ja_answer_is_presentability(answer):
    return str(answer.get("questionID") or answer.get("questionId") or "") in {str(x) for x in _ONENOTE_JA_PRESENTABILITY_QUESTION_IDS}


def _ja_answer_model_bundle(answers, rating, bundle_mode="camel"):
    """Build richer ActivityAnswerListModel-style objects.

    Live diagnostics prove JobAdder's candidate activity endpoint accepts an
    object for `answers`, but the exact model properties for rating/button
    questions are tenant/API-version specific.  Keep this object entirely under
    `answers` and include common collection names for text/rating answers so the
    API can bind the required rating question without falling back to Candidate
    Notes.
    """
    text_answers = [dict(a) for a in answers if not _ja_answer_is_presentability(a)]
    rating_answers = [dict(a) for a in answers if _ja_answer_is_presentability(a)]
    enriched_ratings = []
    for a in rating_answers:
        qid = a.get("questionID") or a.get("questionId")
        qtext = a.get("questionText") or "Presentability (Confidence, Comms, Business Awareness)"
        rating_int = int(rating) if str(rating).strip().isdigit() else rating
        rating_text = str(rating_int) if str(rating_int).strip() else ""
        enriched = dict(a)
        # Leave every common text/rating/null field present, but add nested
        # aliases as several JobAdder UI payloads bind button/rating questions
        # through a nested answer/rating object rather than textValue.
        nested = {
            "id": rating_int,
            "value": rating_int,
            "text": rating_text,
            "name": rating_text,
            "label": rating_text,
            "rating": rating_int,
            "ratingValue": rating_int,
            "score": rating_int,
        }
        enriched.update({
            "questionID": qid,
            "questionId": qid,
            "question_id": qid,
            "questionText": qtext,
            "ratingValue": rating_int,
            "rating": rating_int,
            "ratingScore": rating_int,
            "ratingAnswer": nested,
            "ratingAnswerValue": rating_int,
            "answer": nested,
            "answerValue": rating_int,
            "value": rating_int,
            "score": rating_int,
            "selectedValue": rating_int,
            "selectedRating": rating_int,
            "selectedRatingValue": rating_int,
            "selectedOption": nested,
            "selectedOptionID": rating_int,
            "selectedOptionId": rating_int,
            "option": nested,
            "optionID": rating_int,
            "optionId": rating_int,
            "answerOptionID": rating_int,
            "answerOptionId": rating_int,
            "numberValue": rating_int,
            "numericValue": rating_int,
            "decimalValue": float(rating_int) if str(rating_int).strip().isdigit() else None,
            "textValue": rating_text,
            "singleSelectValue": nested if bundle_mode.endswith("object") else rating_int,
        })
        enriched_ratings.append(enriched)
    all_answers = text_answers + enriched_ratings
    by_qid = {str(a.get("questionID") or a.get("questionId")): dict(a) for a in all_answers}
    rating_by_qid = {str(a.get("questionID") or a.get("questionId")): dict(a) for a in enriched_ratings}
    text_by_qid = {str(a.get("questionID") or a.get("questionId")): dict(a) for a in text_answers}

    if bundle_mode == "dollar_values":
        return {"$values": all_answers}
    if bundle_mode == "pascal":
        return {
            "Items": all_answers,
            "Answers": all_answers,
            "ActivityAnswers": all_answers,
            "TextAnswers": text_answers,
            "RatingAnswers": enriched_ratings,
            "RatingQuestionAnswers": enriched_ratings,
            "QuestionAnswers": all_answers,
            "Values": all_answers,
        }
    if bundle_mode == "maps":
        return {
            "items": all_answers,
            "byQuestionID": by_qid,
            "answersByQuestionID": by_qid,
            "textAnswersByQuestionID": text_by_qid,
            "ratingAnswersByQuestionID": rating_by_qid,
            "ratingsByQuestionID": rating_by_qid,
        }
    return {
        "items": all_answers,
        "answers": all_answers,
        "activityAnswers": all_answers,
        "questionAnswers": all_answers,
        "activityQuestionAnswers": all_answers,
        "values": all_answers,
        "questions": all_answers,
        "textAnswers": text_answers,
        "textQuestionAnswers": text_answers,
        "ratingAnswers": enriched_ratings,
        "ratings": enriched_ratings,
        "ratingQuestionAnswers": enriched_ratings,
        "ratingValues": enriched_ratings,
    }




def _ja_split_text_rating_answers(answers, rating):
    """Return text-only answers plus top-level rating bundles for JobAdder.

    v24.6.116: live diagnostics reached candidates/{id}/activities but still
    returned "All rating mandatory questions are required."  Try keeping text
    answers inside ActivityAnswerListModel while also sending Presentability as
    separate top-level rating collections.
    """
    rating_int = int(rating) if str(rating).strip().isdigit() else rating
    rating_text = str(rating_int) if str(rating_int).strip() else ""
    text_answers = [dict(a) for a in answers if not _ja_answer_is_presentability(a)]
    rating_answers = []
    for a in answers:
        if not _ja_answer_is_presentability(a):
            continue
        qid = a.get("questionID") or a.get("questionId")
        qtext = a.get("questionText") or "Presentability (Confidence, Comms, Business Awareness)"
        rating_answers.append({
            "questionID": qid,
            "questionId": qid,
            "question_id": qid,
            "activityQuestionID": qid,
            "activityQuestionId": qid,
            "ratingQuestionID": qid,
            "ratingQuestionId": qid,
            "id": qid,
            "questionText": qtext,
            "questionType": "Rating",
            "answerType": "Rating",
            "fieldType": "Rating",
            "controlType": "Rating",
            "dataType": "Rating",
            "type": "Rating",
            "value": rating_int,
            "rating": rating_int,
            "ratingValue": rating_int,
            "rateValue": rating_int,
            "ratingScore": rating_int,
            "score": rating_int,
            "stars": rating_int,
            "numberValue": rating_int,
            "numericValue": rating_int,
            "decimalValue": float(rating_int) if str(rating_int).strip().isdigit() else None,
            "textValue": rating_text,
            "answerValue": rating_int,
            "selectedValue": rating_int,
            "selectedRating": rating_int,
            "selectedRatingValue": rating_int,
            "selectedOption": {"id": rating_int, "value": rating_int, "text": rating_text, "name": rating_text},
            "selectedOptionID": rating_int,
            "selectedOptionId": rating_int,
            "optionID": rating_int,
            "optionId": rating_int,
            "answerOptionID": rating_int,
            "answerOptionId": rating_int,
        })
    rating_by_qid = {str(x.get("questionID") or x.get("questionId")): dict(x) for x in rating_answers}
    return text_answers, rating_answers, rating_by_qid



def _ja_answer_model_qid_list_payloads(answers, rating):
    """ActivityAnswerListModel variants where question IDs map to lists.

    v24.6.116: JobAdder returned a very useful .NET binding error:
    answers.textAnswers.41172 expected IList[ActivityTextAnswerModel]. That means
    a likely public API shape is answers.textAnswers.{questionID}: [answerModel]
    and answers.ratingAnswers.{questionID}: [ratingAnswerModel]. Try those before
    the broader/older rating guesses.
    """
    rating_int = int(rating) if str(rating).strip().isdigit() else None
    if rating_int not in (1, 2, 3, 4):
        rating_int = None
    rating_text = str(rating_int or "")
    text_answers = []
    rating_answers = []
    for a in answers:
        qid = a.get("questionID") or a.get("questionId")
        if not qid:
            continue
        if _ja_answer_is_presentability(a):
            ra = {
                "questionID": _ja_maybe_int(qid),
                "questionId": _ja_maybe_int(qid),
                "questionText": a.get("questionText") or "Presentability (Confidence, Comms, Business Awareness)",
                "numericValue": rating_int,
                "numberValue": rating_int,
                "textValue": rating_text,
                "startDateValue": None,
                "endDateValue": None,
            }
            # Keep the exact browser-observed shape first, with a few harmless
            # aliases for tenants/API builds that name the rating property differently.
            ra.update({
                "ratingValue": rating_int,
                "rating": rating_int,
                "value": rating_int,
                "score": rating_int,
            })
            rating_answers.append(ra)
        else:
            text_answers.append({
                "questionID": _ja_maybe_int(qid),
                "questionId": _ja_maybe_int(qid),
                "questionText": a.get("questionText") or "",
                "textValue": a.get("textValue") or "",
                "startDateValue": None,
                "endDateValue": None,
            })
    text_map_list = {str(a["questionID"]): [a] for a in text_answers}
    rating_map_list = {str(a["questionID"]): [a] for a in rating_answers}
    # Also try dict values with explicit nested collection names because the
    # .NET error path can vary depending on the generated model binder.
    text_map_named_list = {k: {"textAnswers": v} for k, v in text_map_list.items()}
    rating_map_named_list = {k: {"ratingAnswers": v} for k, v in rating_map_list.items()}
    text_map_values = {str(a["questionID"]): (a.get("textValue") or "") for a in text_answers}
    rating_map_values = {str(a["questionID"]): rating_int for a in rating_answers if rating_int is not None}
    return [
        {"textAnswers": text_map_list, "ratingAnswers": rating_map_list},
        {"textAnswers": text_map_list, "ratingQuestionAnswers": rating_map_list},
        {"activityTextAnswers": text_map_list, "activityRatingAnswers": rating_map_list},
        {"textQuestionAnswers": text_map_list, "ratingQuestionAnswers": rating_map_list},
        {"textAnswers": text_answers, "ratingAnswers": rating_answers},
        {"textQuestionAnswers": text_answers, "ratingQuestionAnswers": rating_answers},
        {"items": text_answers + rating_answers, "textAnswers": text_map_list, "ratingAnswers": rating_map_list},
        {"textAnswers": text_map_named_list, "ratingAnswers": rating_map_named_list},
        {"textValues": text_map_values, "ratingValues": rating_map_values},
    ]

def _ja_rating_map_answer_payloads(answers, rating):
    """Extra ActivityAnswerListModel object shapes for rating/button fields.

    JobAdder's error now consistently says the activity endpoint and setting are
    accepted, but the mandatory rating question is not bound. These variants keep
    text answers separate and expose Presentability as explicit rating maps by
    question ID inside the answers object, with type metadata for rating controls.
    """
    rating_int = int(rating) if str(rating).strip().isdigit() else None
    if rating_int not in (1, 2, 3, 4):
        rating_int = None
    rating_text = str(rating_int or "")
    text_answers = [dict(a) for a in answers if not _ja_answer_is_presentability(a)]
    text_values = {str(a.get("questionID")): (a.get("textValue") or "") for a in text_answers}
    rating_qids = [str(a.get("questionID") or a.get("questionId")) for a in answers if _ja_answer_is_presentability(a)] or [str(_ONENOTE_JA_PRESENTABILITY_QUESTION_IDS[0])]
    rating_values = {qid: rating_int for qid in rating_qids if rating_int is not None}
    rating_objects = {qid: {
        "questionID": _ja_maybe_int(qid),
        "questionId": _ja_maybe_int(qid),
        "activityQuestionID": _ja_maybe_int(qid),
        "ratingQuestionID": _ja_maybe_int(qid),
        "questionText": "Presentability (Confidence, Comms, Business Awareness)",
        "questionType": "Rating",
        "answerType": "Rating",
        "fieldType": "Rating",
        "controlType": "Rating",
        "dataType": "Rating",
        "type": "Rating",
        "ratingValue": rating_int,
        "rateValue": rating_int,
        "rating": rating_int,
        "score": rating_int,
        "value": rating_int,
        "numericValue": rating_int,
        "numberValue": rating_int,
        "decimalValue": float(rating_int) if rating_int is not None else None,
        "textValue": rating_text,
    } for qid in rating_qids if rating_int is not None}
    qid_list_payloads = _ja_answer_model_qid_list_payloads(answers, rating)
    return qid_list_payloads + [
        {"items": text_answers, "textValues": text_values, "ratingValues": rating_values},
        {"items": text_answers, "textAnswers": text_values, "ratingAnswers": rating_values},
        {"items": text_answers, "textQuestionAnswers": text_values, "ratingQuestionAnswers": rating_values},
        {"items": text_answers, "textAnswersByQuestionID": text_values, "ratingAnswersByQuestionID": rating_objects},
        {"items": text_answers, "answersByQuestionID": {**{k: {"questionID": _ja_maybe_int(k), "textValue": v} for k, v in text_values.items()}, **rating_objects}},
        {"text": text_values, "ratings": rating_values},
        {"values": {**text_values, **{k: v for k, v in rating_values.items()}}, "types": {**{k: "Text" for k in text_values}, **{k: "Rating" for k in rating_values}}},
    ]



def _ja_candidate_screening_call_base_payload(candidate_id, reference=None, activity_id=None):
    """Base JobAdder Candidate Screening Call activity payload."""
    cid_value = _ja_maybe_int(candidate_id)
    payload = {
        "activitySettingID": _ONENOTE_JA_SCREENING_SETTING_ID,
        "actionName": "Candidate Screening Call",
        "activityType": "Screening",
        "attachments": [],
        "entity": {"entityID": cid_value},
        "entityID": cid_value,
        "mentionedUserIDs": [],
        "status": None,
        "task": None,
    }
    if reference:
        payload["reference"] = reference
    if activity_id:
        payload["activityID"] = _ja_maybe_int(activity_id)
    return payload


def _ja_answer_model_qid_list_payloads_v105(answers, rating):
    """Highest-priority ActivityAnswerListModel shapes.

    JobAdder's binder error says answers.textAnswers.<questionID> expects an
    IList[ActivityTextAnswerModel]. Put every field, including Presentability
    62988 with numericValue and textValue, under textAnswers.<qid> = [answer].
    """
    rating_int = int(rating) if str(rating).strip().isdigit() else None
    if rating_int not in (1, 2, 3, 4):
        rating_int = None
    rating_text = str(rating_int or "")
    text_only_map = {}
    rating_map = {}
    all_as_text_map = {}
    for a in answers:
        qid = a.get("questionID") or a.get("questionId")
        if not qid:
            continue
        key = str(qid)
        qid_value = _ja_maybe_int(key)
        qtext = a.get("questionText") or ""
        if _ja_answer_is_presentability(a):
            model = {
                "questionID": qid_value,
                "questionId": qid_value,
                "questionText": qtext or "Presentability (Confidence, Comms, Business Awareness)",
                "textValue": rating_text,
                "numericValue": rating_int,
                "numberValue": rating_int,
                "decimalValue": float(rating_int) if rating_int is not None else None,
                "startDateValue": None,
                "endDateValue": None,
            }
            rating_model = dict(model)
            rating_model.update({"ratingValue": rating_int, "rating": rating_int, "score": rating_int, "value": rating_int})
            rating_map[key] = [rating_model]
            all_as_text_map[key] = [model]
        else:
            model = {
                "questionID": qid_value,
                "questionId": qid_value,
                "questionText": qtext,
                "textValue": a.get("textValue") or "",
                "startDateValue": None,
                "endDateValue": None,
            }
            text_only_map[key] = [model]
            all_as_text_map[key] = [model]
    # v24.6.116: JobAdder diagnostic path says
    # answers.textAnswers.41172.textAnswers expected IList[ActivityTextAnswerModel].
    # That means each question-ID entry is likely a wrapper object with a
    # nested textAnswers/ratingAnswers list, not just qid -> [model]. Try the
    # nested wrapper first, then keep the direct qid -> list shapes as fallback.
    text_only_nested = {k: {"textAnswers": v} for k, v in text_only_map.items()}
    rating_nested = {k: {"ratingAnswers": v} for k, v in rating_map.items()}
    all_as_text_nested = {k: {"textAnswers": v} for k, v in all_as_text_map.items()}
    rating_nested_text_named = {k: {"textAnswers": v} for k, v in rating_map.items()}
    return [
        {"textAnswers": text_only_nested, "ratingAnswers": rating_nested},
        {"textAnswers": all_as_text_nested},
        {"textAnswers": text_only_nested, "ratingQuestionAnswers": rating_nested},
        {"textAnswers": text_only_nested, "ratings": rating_nested},
        {"textAnswers": {**text_only_nested, **rating_nested_text_named}},
        {"textAnswers": all_as_text_map},
        {"textAnswers": text_only_map, "ratingAnswers": rating_map},
        {"textAnswers": all_as_text_map, "ratingAnswers": rating_map},
        {"TextAnswers": all_as_text_nested},
        {"TextAnswers": all_as_text_map},
        {"textQuestionAnswers": all_as_text_nested},
        {"textQuestionAnswers": all_as_text_map},
        {"activityTextAnswers": all_as_text_nested},
        {"activityTextAnswers": all_as_text_map},
        {"textAnswers": all_as_text_map, "ratingQuestionAnswers": rating_map},
    ]


def _ja_browser_activity_answer_list_payload_variants(candidate_id, fields, note_text, reference):
    """Build browser-observed answer-list payloads for JobAdder API.

    v24.6.116: the user's successful JobAdder SPA save shows the tenant stores
    Screening Call fields as a flat answers array. The public candidate activity
    API rejects answers as a raw array, but its .NET error reveals that inside
    ActivityAnswerListModel, textAnswers must be an IList[ActivityTextAnswerModel]
    rather than a questionID map. Try object-wrapping the exact browser answer
    models as answers.textAnswers = [ ... ], including Presentability 62988 with
    numericValue + textValue.
    """
    raw_answers = _ja_screening_call_answers(
        fields,
        note_text,
        presentability_question_id=_ONENOTE_JA_PRESENTABILITY_QUESTION_IDS[0],
        presentability_mode="number",
    )
    rating_int = _onenote_presentability_rating_int(fields)
    answer_list = []
    text_list = []
    rating_list = []
    for a in raw_answers:
        qid = a.get("questionID") or a.get("questionId")
        if not qid:
            continue
        qid_int = _ja_maybe_int(qid)
        is_rating = _ja_answer_is_presentability(a)
        model = {
            "questionID": qid_int,
            "questionText": a.get("questionText") or ("Presentability (Confidence, Comms, Business Awareness)" if is_rating else ""),
            "textValue": str(rating_int) if is_rating else (a.get("textValue") or ""),
            "numericValue": rating_int if is_rating else None,
            "startDateValue": None,
            "endDateValue": None,
        }
        answer_list.append(dict(model))
        if is_rating:
            rating_list.append(dict(model))
        else:
            text_list.append(dict(model))

    answers_payloads = [
        {"textAnswers": answer_list},
        {"textAnswers": text_list, "ratingAnswers": rating_list},
        {"activityTextAnswers": answer_list},
        {"activityAnswers": answer_list},
        {"questionAnswers": answer_list},
        {"items": answer_list},
        {"answers": answer_list},
        {"values": answer_list},
        {"TextAnswers": answer_list},
        {"TextAnswers": text_list, "RatingAnswers": rating_list},
        {"ActivityAnswers": answer_list},
        {"Items": answer_list},
    ]
    variants = []
    for answers_payload in answers_payloads:
        payload = _ja_candidate_screening_call_base_payload(candidate_id, reference=reference)
        payload["answers"] = answers_payload
        variants.append(payload)
    return variants


def _ja_precise_qid_activity_payload_variants(candidate_id, fields, note_text, reference):
    """Build precise v105 JobAdder answer-map attempts before older guesses."""
    answers = _ja_screening_call_answers(
        fields,
        note_text,
        presentability_question_id=_ONENOTE_JA_PRESENTABILITY_QUESTION_IDS[0],
        presentability_mode="number",
    )
    rating = _onenote_presentability_rating_int(fields)
    variants = []
    for answers_payload in _ja_answer_model_qid_list_payloads_v105(answers, rating):
        payload = _ja_candidate_screening_call_base_payload(candidate_id, reference=reference)
        payload["answers"] = answers_payload
        variants.append(payload)
    return variants

def _ja_candidate_screening_call_payload(candidate_id, fields, note_text, reference=None, activity_id=None, answers_shape="items", presentability_question_id=None, presentability_mode="numeric"):
    cid_value = _ja_maybe_int(candidate_id)
    answers = _ja_screening_call_answers(fields, note_text, presentability_question_id=presentability_question_id, presentability_mode=presentability_mode)
    rating_required_validation = None
    if answers_shape.startswith("top_rating_"):
        rating = _onenote_presentability_rating_int(fields)
        text_answers, rating_answers, rating_by_qid = _ja_split_text_rating_answers(answers, rating)
        if answers_shape == "top_rating_items":
            answers_payload = {"items": text_answers}
        elif answers_shape == "top_rating_text_answers":
            answers_payload = {"textAnswers": text_answers, "items": text_answers}
        elif answers_shape == "top_rating_map":
            answers_payload = {str(a.get("questionID")): {"questionID": a.get("questionID"), "textValue": a.get("textValue") or ""} for a in text_answers}
        elif answers_shape == "top_rating_questions":
            answers_payload = {"questions": text_answers, "values": text_answers}
        else:
            answers_payload = {"items": text_answers}
        rating_required_validation = {"rating_answers": rating_answers, "rating_by_qid": rating_by_qid}
    elif answers_shape == "array":
        answers_payload = answers
    elif answers_shape == "map_full":
        answers_payload = {str(a.get("questionID")): dict(a) for a in answers}
    elif answers_shape == "map_text":
        answers_payload = {str(a.get("questionID")): (a.get("textValue") or "") for a in answers}
    elif answers_shape == "map_value":
        answers_payload = {}
        for a in answers:
            qid = str(a.get("questionID"))
            val = a.get("textValue")
            if not val and (a.get("ratingValue") is not None or a.get("numericValue") is not None or a.get("numberValue") is not None):
                val = a.get("ratingValue") if a.get("ratingValue") is not None else (a.get("numericValue") if a.get("numericValue") is not None else a.get("numberValue"))
            answers_payload[qid] = val if val is not None else ""
    elif answers_shape == "map_compact":
        answers_payload = {}
        for a in answers:
            qid = str(a.get("questionID"))
            if a.get("ratingValue") is not None or a.get("numericValue") is not None or a.get("numberValue") is not None:
                answers_payload[qid] = {
                    "questionID": a.get("questionID"),
                    "questionId": a.get("questionID"),
                    "ratingValue": a.get("ratingValue") if a.get("ratingValue") is not None else a.get("numericValue"),
                    "rating": a.get("rating") if a.get("rating") is not None else a.get("numericValue"),
                    "value": a.get("value") if a.get("value") is not None else a.get("numericValue"),
                    "numericValue": a.get("numericValue"),
                    "numberValue": a.get("numberValue"),
                    "textValue": a.get("textValue") or str(a.get("numericValue") or a.get("numberValue") or ""),
                }
            else:
                answers_payload[qid] = {
                    "questionID": a.get("questionID"),
                    "questionId": a.get("questionID"),
                    "textValue": a.get("textValue") or "",
                }
    elif answers_shape.startswith("rating_map_"):
        rating = _onenote_presentability_rating_int(fields)
        payloads = _ja_rating_map_answer_payloads(answers, rating)
        try:
            idx = int(answers_shape.rsplit("_", 1)[-1])
        except Exception:
            idx = 0
        answers_payload = payloads[idx] if 0 <= idx < len(payloads) else payloads[0]
    elif answers_shape in ("answer_bundle", "answer_bundle_object", "answer_bundle_pascal", "answer_bundle_maps", "answer_bundle_values"):
        rating = _onenote_presentability_rating_int(fields)
        bundle_mode = {
            "answer_bundle": "camel",
            "answer_bundle_object": "camel_object",
            "answer_bundle_pascal": "pascal",
            "answer_bundle_maps": "maps",
            "answer_bundle_values": "dollar_values",
        }.get(answers_shape, "camel")
        answers_payload = _ja_answer_model_bundle(answers, rating, bundle_mode=bundle_mode)
    else:
        wrappers = {
            "items": {"items": answers},
            "answers": {"answers": answers},
            "activityAnswers": {"activityAnswers": answers},
            "values": {"values": answers},
            "questions": {"questions": answers},
        }
        answers_payload = wrappers.get(answers_shape) or {"items": answers}
    payload = {
        "activitySettingID": _ONENOTE_JA_SCREENING_SETTING_ID,
        "actionName": "Candidate Screening Call",
        "activityType": "Screening",
        "answers": answers_payload,
        "attachments": [],
        "entity": {"entityID": cid_value},
        "entityID": cid_value,
        "mentionedUserIDs": [],
        "status": None,
        "task": None,
    }
    if rating_required_validation:
        rating_answers = rating_required_validation.get("rating_answers") or []
        rating_by_qid = rating_required_validation.get("rating_by_qid") or {}
        payload.update({
            "ratingAnswers": rating_answers,
            "ratings": rating_answers,
            "ratingQuestionAnswers": rating_answers,
            "activityRatingAnswers": rating_answers,
            "ratingValues": rating_answers,
            "ratingsByQuestionID": rating_by_qid,
            "ratingAnswersByQuestionID": rating_by_qid,
        })
    if reference:
        payload["reference"] = reference
    # Optional only: if a future diagnostic captures a required draft activityID,
    # the UI/backend can pass it without hard-coding the user's sample ID.
    if activity_id:
        payload["activityID"] = _ja_maybe_int(activity_id)
    return payload


def _ja_activity_payload_variants(candidate_id, activity_type, subject, note_text, fields, reference, now_utc):
    """Build JobAdder candidate activity payload variants.

    v24.6.97: Live diagnostics show candidates/{id}/activities is the
    reachable endpoint, but it rejects answers[] and expects an answers object
    (ActivityAnswerListModel). Therefore the first variants use exact tenant
    IDs with answers wrapped as objects. Browser-like answers[] remains last
    only for diagnostics.
    """
    cid = str(candidate_id or "")
    exact_variants = []
    # v24.6.116: Presentability is a mandatory 1-4 button/rating in JobAdder,
    # not a free-text field.  Try rating/numeric/select payloads before the
    # older text-style fallback.  Keep the attempt list short enough to avoid
    # slow transfers/timeouts.
    # Keep attempts limited: the user's captured browser payload confirms
    # Presentability questionID 62988, while 52988 is only a historical fallback.
    primary_presentability_qid = _ONENOTE_JA_PRESENTABILITY_QUESTION_IDS[0]
    # v24.6.116: the successful JobAdder SPA payload is a flat answers array.
    # The API rejects answers as a raw array, but its model binder says
    # answers.textAnswers must be an IList. Try answers.textAnswers = [models]
    # first, including Presentability 62988 as numericValue/textValue.
    exact_variants.extend(_ja_browser_activity_answer_list_payload_variants(cid, fields, note_text, reference))
    # v24.6.106 fallback: qid-map/list variants retained for diagnostics.
    exact_variants.extend(_ja_precise_qid_activity_payload_variants(cid, fields, note_text, reference))
    # v24.6.116: try top-level rating collections before answer-object
    # variants, because live JobAdder says the mandatory rating question is
    # still missing even though the endpoint and activity setting are valid.
    # First try answer-object shapes that explicitly expose rating values by
    # question ID. This targets JobAdder's ActivityAnswerListModel binding where
    # normal answers are object-wrapped but rating controls require a separate
    # rating map/typed answer.
    for p_mode in ("rating_full", "rating_value", "number", "single_int"):
        for shape in ("rating_map_0", "rating_map_1", "rating_map_2", "rating_map_3", "rating_map_4", "rating_map_5", "rating_map_6"):
            exact_variants.append(_ja_candidate_screening_call_payload(
                cid, fields, note_text, reference=reference,
                answers_shape=shape, presentability_question_id=primary_presentability_qid,
                presentability_mode=p_mode,
            ))
    for p_mode in ("rating_full", "rating_value", "number", "single_int"):
        for shape in ("top_rating_items", "top_rating_text_answers", "top_rating_map", "top_rating_questions"):
            exact_variants.append(_ja_candidate_screening_call_payload(
                cid, fields, note_text, reference=reference,
                answers_shape=shape, presentability_question_id=primary_presentability_qid,
                presentability_mode=p_mode,
            ))
    # v24.6.116: diagnostics still say the mandatory rating question is not
    # bound. Try richer ActivityAnswerListModel-style objects before older maps.
    for p_mode in ("rating_full", "rating_value", "number", "single_int"):
        for shape in ("answer_bundle", "answer_bundle_object", "answer_bundle_pascal", "answer_bundle_maps", "answer_bundle_values", "map_full", "map_compact", "map_value", "items"):
            exact_variants.append(_ja_candidate_screening_call_payload(
                cid, fields, note_text, reference=reference,
                answers_shape=shape, presentability_question_id=primary_presentability_qid,
                presentability_mode=p_mode,
            ))
    # Fallbacks only if the tenant still expects a different legacy ID/shape.
    for presentability_qid in _ONENOTE_JA_PRESENTABILITY_QUESTION_IDS[1:]:
        for shape in ("map_full", "map_compact", "items"):
            exact_variants.append(_ja_candidate_screening_call_payload(
                cid, fields, note_text, reference=reference,
                answers_shape=shape, presentability_question_id=presentability_qid,
                presentability_mode="rating_full",
            ))
    # Late diagnostics only: retained for tenants that unexpectedly accept the
    # original browser-like array or text maps.
    for shape in ("answers", "map_text", "array"):
        exact_variants.append(_ja_candidate_screening_call_payload(
            cid, fields, note_text, reference=reference,
            answers_shape=shape, presentability_question_id=primary_presentability_qid,
            presentability_mode="text",
        ))

    base = {
        "type": activity_type,
        "activityType": activity_type,
        "activityTypeName": activity_type,
        "subject": subject,
        "title": subject,
        "description": note_text,
        "text": note_text,
        "comments": note_text,
        "comment": note_text,
        "note": note_text,
        "completed": True,
        "completedAt": now_utc,
        "date": now_utc,
        "reference": reference,
        "fields": fields,
        "answers": {"items": _ja_screening_call_answers(fields, note_text)},
    }
    with_candidate = dict(base)
    with_candidate.update({
        "entityType": "candidate",
        "candidateId": cid,
        "candidate_id": cid,
        "entityId": cid,
        "entityID": _ja_maybe_int(cid),
        "entity": {"entityID": _ja_maybe_int(cid)},
        "candidate": {"candidateId": cid, "id": cid},
    })
    setting_named = dict(base)
    setting_named.update({
        "candidateId": cid,
        "activitySettingID": _ONENOTE_JA_SCREENING_SETTING_ID,
        "activitySetting": {"name": "Candidate Screening Call", "id": _ONENOTE_JA_SCREENING_SETTING_ID},
        "activitySettingName": "Candidate Screening Call",
        "actionName": "Candidate Screening Call",
        "activityType": "Screening",
        "isCompleted": True,
    })
    return exact_variants + [setting_named, with_candidate, base]



def _onenote_clean_note_text(value, max_len=25000):
    text = re.sub(r"\r\n?", "\n", str(value or ""))
    text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]", " ", text)
    text = re.sub(r"\n{4,}", "\n\n\n", text).strip()
    if len(text) > max_len:
        text = text[:max_len].rstrip() + "\n\n[CV Studio truncated this note because it was too long.]"
    return text


# v24.6.80: user clarified the OneNote Screening Call transfer may leave
# normal text fields blank when the candidate did not provide the information.
# Only Presentability must contain a 1-4 rating before transfer.
_ONENOTE_SCREENING_REQUIRED_FIELDS = [
    ("presentability_rating", "Presentability rating 1-4"),
]

def _onenote_clean_field_value(value, max_len=4000):
    text = re.sub(r"\r\n?", "\n", str(value or ""))
    text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]", " ", text)
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    if len(text) > max_len:
        text = text[:max_len].rstrip() + "…"
    return text

def _onenote_normalize_screening_fields(value):
    if not isinstance(value, dict):
        return {}
    out = {}
    for key in [
        "brief_overview", "reason_leaving", "looking_for", "current_salary_breakdown",
        "expected_salary", "notice_period", "leads", "remarks", "presentability_rating", "name", "email",
        "phone", "role", "location", "red_flags", "next_steps", "raw_presentability"
    ]:
        out[key] = _onenote_clean_field_value(value.get(key, ""), max_len=8000 if key == "brief_overview" else 4000)
    # Accept a few legacy/earlier field keys so older UI/state doesn't silently fail.
    if not out.get("current_salary_breakdown"):
        out["current_salary_breakdown"] = _onenote_clean_field_value(value.get("current_salary") or value.get("current_package") or "")
    if not out.get("looking_for"):
        out["looking_for"] = _onenote_clean_field_value(value.get("motivation") or value.get("interest") or value.get("target_role") or "")
    rating_int = _onenote_presentability_rating_int(out)
    out["presentability_rating"] = str(rating_int) if rating_int in (1, 2, 3, 4) else ""
    return out

def _onenote_missing_screening_fields(fields):
    missing = []
    for key, label in _ONENOTE_SCREENING_REQUIRED_FIELDS:
        if key == "presentability_rating":
            # Presentability is not a free-text field in JobAdder. It is a
            # mandatory 1/2/3/4 rating button. Treat anything else as missing
            # locally so we do not send a blank rating and receive JobAdder's
            # confusing "All rating mandatory questions are required" error.
            if _onenote_presentability_rating_int(fields) not in (1, 2, 3, 4):
                missing.append(label)
            continue
        if not _onenote_clean_field_value(fields.get(key, "")):
            missing.append(label)
    return missing



def _jobadder_web_base():
    api_url = (_ja_creds_store.get("api_url") or "").strip().rstrip("/")
    m = re.search(r"https?://(?:api\.([a-z0-9]+\.jobadder\.com)|([a-z0-9]+)api\.jobadder\.com)", api_url, re.I)
    if m:
        region = m.group(1) or ((m.group(2) or "") + ".jobadder.com")
        return "https://" + region
    return "https://app.jobadder.com"


def _ja_spa_screening_call_answers(fields, note_text="", include_extended=False):
    """Return the flat answer array observed from JobAdder's SPA UI.

    v24.6.116: the user captured a successful *new* Candidate Screening Call
    create request. The SPA create route posts to
    /spa/api/candidates/{id}/activities/standardactivity and includes only the
    standard six text questions plus Presentability. Older edit requests can
    include additional Leads/Remarks questions, but sending them during create
    is less safe, so the browser-create helper defaults to the captured create
    shape.
    """
    fields = fields or {}
    rating = _onenote_presentability_rating_int(fields)
    rating = int(rating) if str(rating or "").strip().isdigit() else None
    values = {
        "brief_overview": _onenote_clean_field_value(fields.get("brief_overview", ""), max_len=8000),
        "reason_leaving": _onenote_clean_field_value(fields.get("reason_leaving", "")),
        "looking_for": _onenote_clean_field_value(fields.get("looking_for", "")),
        "current_salary_breakdown": _onenote_clean_field_value(fields.get("current_salary_breakdown", "")),
        "expected_salary": _onenote_clean_field_value(fields.get("expected_salary", "")),
        "notice_period": _onenote_clean_field_value(fields.get("notice_period", "")),
        "leads": _onenote_clean_field_value(fields.get("leads", "")),
        "remarks": _onenote_screening_remarks_value(fields, note_text),
    }
    question_rows = [
        (41172, "Brief Overview of Experience", "brief_overview"),
        (41173, "Reason For Leaving", "reason_leaving"),
        (41174, "Looking For?", "looking_for"),
        (41175, "Current Salary Breakdown", "current_salary_breakdown"),
        (41176, "Expected Salary", "expected_salary"),
        (41177, "Notice Period", "notice_period"),
    ]
    if include_extended:
        question_rows.extend([
            (35900, "Leads - Follow format: Active (Client - Role, Stage, Y/N)  Y denotes agency representation", "leads"),
            (41178, "Remarks and things to take note", "remarks"),
        ])
    answers = []
    # v24.6.116: user clarified that if Brief Overview / Summary is empty,
    # leave Brief Overview blank instead of stuffing the raw OneNote note there.
    # Other standard create fields still use N/A when absent to avoid vague
    # JobAdder 500s on empty required text fields.
    for qid, qtext, key in question_rows:
        text_value = values.get(key, "")
        if not text_value and key != "brief_overview":
            text_value = "N/A"
        answers.append({
            "questionID": qid,
            "questionText": qtext,
            "textValue": text_value,
            "startDateValue": None,
            "endDateValue": None,
            "numericValue": None,
        })
    answers.append({
        "questionID": _ONENOTE_JA_PRESENTABILITY_QUESTION_IDS[0],
        "questionText": "Presentability (Confidence, Comms, Business Awareness)",
        "textValue": str(rating or ""),
        "startDateValue": None,
        "endDateValue": None,
        "numericValue": rating,
    })
    return answers


def _ja_spa_screening_call_payload(candidate_id, fields, note_text="", activity_id=None, include_extended=False):
    """Build the JobAdder browser-SPA payload captured from manual Network requests.

    This payload is not sent by the Flask backend. It is used to generate a
    console helper script that the user runs inside their already-authenticated
    JobAdder browser tab, so cookies/tokens never need to be copied into CV Studio.
    """
    cid_value = _ja_maybe_int(candidate_id)
    payload = {
        "activityID": _ja_maybe_int(activity_id) if activity_id else 0,
        "activitySettingID": _ONENOTE_JA_SCREENING_SETTING_ID,
        "actionName": "Candidate Screening Call",
        "activityType": "Screening",
        "answers": _ja_spa_screening_call_answers(fields, note_text, include_extended=include_extended),
        "attachments": None,
        "entity": {"entityID": cid_value},
        "entityID": cid_value,
        "mentionedUserIDs": None,
        "status": None,
        "task": "",
    }
    return payload




def _ja_spa_salary_update_helper_js(salary_canonical):
    """Apply backend-calculated canonical salary values in the emergency helper.

    No salary text is reparsed in the JobAdder browser. The same canonical object
    that the backend calculated is embedded and applied directly.
    """
    canonical_json = json.dumps(salary_canonical or {}, ensure_ascii=False, separators=(",", ":"))
    return r"""
  const CV_CANONICAL_SALARY = %s;
  function cvSalaryFormatMoney(n) {
    if (n === null || n === undefined || !Number.isFinite(Number(n))) return '';
    return String(Math.round(Number(n))).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }
  const CV_SALARY_PERMANENT_WORKTYPE = { workTypeID: 6727, name: 'Permanent', salaryType: 'NotSpecified', placementType: null };
  function cvSalaryRangeText(min, max) {
    if (min === null || min === undefined) return null;
    if (max === null || max === undefined || Number(max) === Number(min)) return cvSalaryFormatMoney(min);
    return `${cvSalaryFormatMoney(min)} - ${cvSalaryFormatMoney(max)}`;
  }
  function cvSetSalaryBlock(existingBlock, min, max) {
    const block = Object.assign({}, existingBlock || {});
    const oldSalary = Object.assign({}, block.salary || {});
    block.workType = Object.assign({}, CV_SALARY_PERMANENT_WORKTYPE);
    oldSalary.type = 'PerMonth';
    if (min !== null && min !== undefined && Number.isFinite(Number(min))) {
      oldSalary.salaryMin = Number(min);
      oldSalary.salaryMax = Number(max ?? min);
      oldSalary.salaryRange = cvSalaryRangeText(min, max ?? min);
    }
    if (!('unitPerUnit' in oldSalary)) oldSalary.unitPerUnit = null;
    block.salary = oldSalary;
    return block;
  }
  function cvCandidatePayloadClone(existing) {
    const payload = Object.assign({}, existing || {});
    ['candidateID','name','status','resume','formattedResume','coverLetter','otherSalaries','recruiters','seeking','rank','dateResumeUpdated','dateUpdatedUtc','lastContactedAt','lastPlaced','careerUpdateProfileLastUpdatedAt','rsmInTimeEmbeddedUrl','attachmentTypeNames','internalRating','remoteLookedUp','talentPoolIDs'].forEach(k => delete payload[k]);
    return payload;
  }
  async function cvFetchJson(url) {
    const r = await fetch(url, { credentials: 'same-origin', headers: {'Accept':'application/json, text/plain, */*', 'x-jobadder-spa':'1'} });
    const text = await readText(r);
    let data = null;
    try { data = JSON.parse(text || '{}'); } catch(e) {}
    return { ok: r.ok, status: r.status, data, text };
  }
  async function cvPutJson(url, body) {
    const r = await fetch(url, {
      method: 'PUT', credentials: 'same-origin',
      headers: {'Accept':'application/json, text/plain, */*', 'Content-Type':'application/json', 'x-jobadder-spa':'1', 'x-correlation-id': Math.random().toString(36).slice(2, 14)},
      body: JSON.stringify(body)
    });
    return { ok: r.ok, status: r.status, text: await readText(r) };
  }
  async function cvStudioOneNoteSalaryUpdate() {
    const canonical = CV_CANONICAL_SALARY || {};
    const results = { canonicalSalary: canonical };
    const candidateUrl = location.origin + '/spa/api/candidates/' + encodeURIComponent(candidateId);
    const g = await cvFetchJson(candidateUrl);
    if (!g.ok || !g.data) return { ok:false, reason:`Could not read candidate salary API (HTTP ${g.status})`, canonicalSalary:canonical };
    const candidatePayload = cvCandidatePayloadClone(g.data);
    const current = canonical.current || {};
    const expected = canonical.expected || {};
    let currentMin = null;
    if (current.writeToProfile && Number.isFinite(Number(current.monthlyEquivalent))) {
      currentMin = Number(current.monthlyEquivalent);
      candidatePayload.currentSalary = cvSetSalaryBlock(g.data.currentSalary, currentMin, currentMin);
      results.currentSalary = { ok:true, value:currentMin, fingerprint:(canonical.validation||{}).salaryFingerprint };
    } else {
      candidatePayload.currentSalary = cvSetSalaryBlock(g.data.currentSalary, null, null);
      results.currentSalary = { ok:true, skipped:true, reason:'Canonical current salary did not request an overwrite' };
    }
    let idealMin = expected.minAmount, idealMax = expected.maxAmount;
    const existingCurrent = Number((((g.data.currentSalary||{}).salary||{}).salaryMin));
    if (!Number.isFinite(Number(idealMin)) && expected.type === 'same_as_current_unresolved' && Number.isFinite(existingCurrent)) {
      idealMin = existingCurrent; idealMax = existingCurrent;
    }
    if (!Number.isFinite(Number(idealMin)) && String(expected.type||'').startsWith('percent') && Number.isFinite(existingCurrent)) {
      const pmin = Number(expected.percentMin), pmax = Number(expected.percentMax);
      if (Number.isFinite(pmin) && Number.isFinite(pmax)) {
        idealMin = Math.round(existingCurrent * (1 + pmin / 100));
        idealMax = Math.round(existingCurrent * (1 + pmax / 100));
      }
    }
    if (Number.isFinite(Number(idealMin))) {
      candidatePayload.idealSalary = cvSetSalaryBlock(g.data.idealSalary, Number(idealMin), Number(idealMax ?? idealMin));
      results.expectedSalary = { ok:true, min:Number(idealMin), max:Number(idealMax ?? idealMin), basisCurrentAmount:expected.basisCurrentAmount ?? existingCurrent };
    } else {
      candidatePayload.idealSalary = cvSetSalaryBlock(g.data.idealSalary, null, null);
      results.expectedSalary = { ok:true, skipped:true, reason:'Canonical expected salary did not request an overwrite' };
    }
    const currencySelection = canonical.currencySelection || {};
    const currencyOption = String(currencySelection.jobAdderOption || '').trim();
    if (currencyOption) {
      const customFields = Object.assign({}, g.data.customFields || {});
      const existingCurrency = Object.assign({}, customFields[4] || customFields['4'] || { fieldID:4, valueList:[] });
      existingCurrency.fieldID = 4;
      existingCurrency.value = currencyOption;
      if (!Array.isArray(existingCurrency.valueList)) existingCurrency.valueList = [];
      customFields[4] = existingCurrency;
      candidatePayload.customFields = customFields;
      results.currencyField = { ok:true, fieldID:4, value:currencyOption, selectionRule:currencySelection.selectionRule || null };
    } else {
      results.currencyField = { ok:true, skipped:true, reason:'No supported canonical currency option' };
    }
    const notice = canonical.notice || {};
    if (notice.spaPayload) {
      candidatePayload.availability = { type:notice.spaPayload.type, date:notice.spaPayload.date };
      results.noticePeriod = { ok:true, matched:notice.display, payload:notice.spaPayload };
    } else {
      results.noticePeriod = { ok:true, skipped:true, reason:'No supported canonical SPA notice payload' };
    }
    const put = await cvPutJson(candidateUrl, candidatePayload);
    results.put = { ok:put.ok, status:put.status, text:String(put.text||'').slice(0,300) };
    results.ok = !!put.ok;
    if (!put.ok) results.reason = `Salary/notice PUT failed (HTTP ${put.status})`;
    return results;
  }
""" % canonical_json

def _ja_spa_browser_bridge(candidate_id, fields, note_text="", email="", salary_canonical=None, spelling_correction=True):
    """Return a safe copy/paste browser helper for the JobAdder SPA endpoint.

    v24.6.116: create-only. The user clarified OneNote transfer must always
    create a new Screening Call and must not update an existing Screening Call.
    The helper therefore tries likely JobAdder SPA create routes only. If all
    create routes fail, it prints a concise diagnostic and asks the user to
    capture the Network request from manually creating a brand-new Screening
    Call (not editing an existing one).
    """
    cid = str(candidate_id or "").strip()
    cid_q = urllib.parse.quote(cid, safe="")
    endpoint = "/spa/api/candidates/{}/activities/standardactivity".format(cid_q)
    profile_path = "/candidates/{}?tab=2&activityView=Activity".format(cid_q)
    # v24.6.116: captured successful create request uses standardactivity,
    # activityID: 0, attachments/mentionedUserIDs as null, task as empty string.
    # Add an in-browser sanitizer too, because older row.browser_bridge objects can
    # linger in the UI and because JobAdder returns only a vague HTTP 500 when a
    # required standard text field is blank.
    payload = _ja_spa_screening_call_payload(cid, fields, note_text, include_extended=False)
    if salary_canonical is None:
        salary_canonical = _ja_build_salary_notice_canonical(fields, {}, spelling_correction=spelling_correction)
    payload_json = json.dumps(payload, ensure_ascii=False, indent=2)
    compact_payload_json = json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
    script = """(async () => {
  const helperVersion = 'v24.6.235';
  const candidateId = %s;
  const payload = %s;
  const profilePath = %s;
  const headers = {
    'Accept': 'application/json, text/plain, */*',
    'Content-Type': 'application/json',
    'x-jobadder-spa': '1'
  };
  function cleanText(value, fallback) {
    const s = String(value == null ? '' : value).replace(/\\s+/g, ' ').trim();
    return s || fallback || 'N/A';
  }
  function answerByQuestion(qid) {
    return (Array.isArray(payload.answers) ? payload.answers : []).find(a => Number(a && a.questionID) === Number(qid)) || {};
  }
  function textAnswer(qid, qtext) {
    const a = answerByQuestion(qid);
    const fallback = Number(qid) === 41172 ? '' : 'N/A';
    return {
      questionID: qid,
      questionText: qtext,
      textValue: cleanText(a.textValue, fallback),
      startDateValue: null,
      endDateValue: null,
      numericValue: null
    };
  }
  function ratingAnswer() {
    const a = answerByQuestion(62988);
    let rating = Number(a.numericValue || a.textValue || 0);
    if (![1, 2, 3, 4].includes(rating)) {
      throw new Error('Presentability must be 1, 2, 3 or 4 before creating the Screening Call.');
    }
    return {
      questionID: 62988,
      questionText: 'Presentability (Confidence, Comms, Business Awareness)',
      textValue: String(rating),
      startDateValue: null,
      endDateValue: null,
      numericValue: rating
    };
  }
  // Match the successful manual-create shape exactly: six text answers + rating.
  const createPayload = {
    activityID: 0,
    activitySettingID: 8225,
    actionName: 'Candidate Screening Call',
    activityType: 'Screening',
    answers: [
      textAnswer(41172, 'Brief Overview of Experience'),
      textAnswer(41173, 'Reason For Leaving'),
      textAnswer(41174, 'Looking For?'),
      textAnswer(41175, 'Current Salary Breakdown'),
      textAnswer(41176, 'Expected Salary'),
      textAnswer(41177, 'Notice Period'),
      ratingAnswer()
    ],
    attachments: null,
    entity: {entityID: Number(candidateId) || candidateId},
    entityID: Number(candidateId) || candidateId,
    mentionedUserIDs: null,
    status: null,
    task: ''
  };
  async function readText(res) {
    try { return await res.text(); } catch (e) { return String(e || ''); }
  }
%s
  console.log('CV Studio OneNote → CREATE-ONLY helper', helperVersion);
  console.log('CV Studio OneNote → sanitized JobAdder CREATE payload', createPayload);
  const url = '/spa/api/candidates/' + encodeURIComponent(candidateId) + '/activities/standardactivity';
  const res = await fetch(url, {
    method: 'POST',
    credentials: 'same-origin',
    headers,
    body: JSON.stringify(createPayload)
  });
  const text = await readText(res);
  console.log('CV Studio OneNote → create-only response', res.status, text);
  if (res.ok) {
    let salaryResult = null;
    try {
      salaryResult = await cvStudioOneNoteSalaryUpdate();
      console.log('CV Studio OneNote → salary/notice update result', salaryResult);
    } catch (salaryErr) {
      salaryResult = { ok: false, reason: String(salaryErr && salaryErr.message || salaryErr) };
      console.warn('CV Studio OneNote → salary/notice update failed after Screening Call create', salaryResult);
    }
    const salaryMsg = salaryResult && salaryResult.ok
      ? 'Salary/notice update also completed.'
      : 'Screening Call created, but salary/notice update needs review in console.';
    alert('CV Studio Screening Call created as a NEW activity. ' + salaryMsg + ' Refresh the Activity tab if you do not see it immediately.');
    if (location.pathname !== profilePath.split('?')[0]) location.href = profilePath;
    return;
  }
  console.error('CV Studio OneNote → CREATE-ONLY failed. No existing Screening Call was updated.', {status: res.status, response: text, payload: createPayload});
  alert([
    'CV Studio could not create a NEW Candidate Screening Call via JobAdder standardactivity.',
    'No existing Screening Call was updated.',
    '',
    'Please copy the failed Network request Payload and Preview/Response only.'
  ].join(String.fromCharCode(10)));
  throw new Error('Create-only JobAdder SPA attempt failed: HTTP ' + res.status);
})();""" % (json.dumps(cid), compact_payload_json, json.dumps(profile_path), _ja_spa_salary_update_helper_js(salary_canonical))
    return {
        "method": "CREATE-ONLY browser SPA helper using /standardactivity; never updates existing Screening Calls",
        "endpoint": endpoint,
        "fallback": "No update fallback. Uses the captured JobAdder SPA create route /activities/standardactivity. If it fails, capture the successful Network request from manually creating a brand-new Candidate Screening Call.",
        "profile_url": _jobadder_candidate_activity_url(cid),
        "payload": payload,
        "payload_json": payload_json,
        "script": script,
        "warning": "Run this only in the JobAdder candidate page DevTools Console while logged into JobAdder. It uses your browser session automatically and does not expose cookies to CV Studio. This script never updates an existing Screening Call; it posts only to /activities/standardactivity to create a new one. Blank standard text fields are filled with N/A for create compatibility.",
        "email": email,
        "candidate_id": cid,
        "salary_canonical": salary_canonical,
    }

def _jobadder_candidate_activity_url(candidate_id):
    cid = urllib.parse.quote(str(candidate_id or ""), safe="")
    return _jobadder_web_base() + "/candidates/{}?tab=2&activityView=Activity".format(cid)



# v24.6.137: production OneNote → JobAdder path based on JobAdder's official
# OpenAPI v2 contract. Source of truth:
# https://api.jobadder.com/v2/docs#operation/AddCandidateActivity
#
# POST/write model:
#   textAnswers [{questionId, text}]
#   ratingValueAnswers [{questionId, rating}]
# GET/read model is intentionally different and must not be reused for writes.
def _ja_official_screening_activity_payload(fields, note_text=""):
    fields = fields or {}
    rating = _onenote_presentability_rating_int(fields)
    if rating not in (1, 2, 3, 4):
        raise ValueError("Presentability rating must be 1-4")
    values = {
        "brief_overview": _onenote_clean_field_value(fields.get("brief_overview", ""), max_len=8000),
        "reason_leaving": _onenote_clean_field_value(fields.get("reason_leaving", "")),
        "looking_for": _onenote_clean_field_value(fields.get("looking_for", "")),
        "current_salary_breakdown": _onenote_clean_field_value(fields.get("current_salary_breakdown", "")),
        "expected_salary": _onenote_clean_field_value(fields.get("expected_salary", "")),
        "notice_period": _onenote_clean_field_value(fields.get("notice_period", "")),
        "leads": _onenote_clean_field_value(fields.get("leads", "")),
        "remarks": _onenote_screening_remarks_value(fields, note_text),
    }
    text_answers = []
    for question_id, _question_text, key in _ONENOTE_JA_SCREENING_QUESTIONS_BASE:
        value = values.get(key, "")
        # Normal Screening Call text fields are optional in this tenant. Omit
        # unanswered questions rather than inserting artificial N/A text.
        if value:
            text_answers.append({"questionId": int(question_id), "text": value})
    return {
        "activitySettingId": _ONENOTE_JA_SCREENING_SETTING_ID,
        "answers": {
            "textAnswers": text_answers,
            "listValueAnswers": [],
            "dateRangeValueAnswers": [],
            "ratingValueAnswers": [
                {"questionId": _ONENOTE_JA_PRESENTABILITY_QUESTION_IDS[0], "rating": int(rating)}
            ],
        },
    }


_ONENOTE_JA_PERMANENT_WORKTYPE_ID = 6727

# JobAdder candidate custom field 4 is the single-value Currency field, confirmed
# by Kano's API-backed Panel implementation. The public OAuth API represents the
# same field through UpdateCandidate.custom [{fieldId, value}].
_JA_CURRENCY_CUSTOM_FIELD_ID = 4
_JA_CURRENCY_OPTIONS = {
    "BND": "Brunei Dollar (BND)",
    "KHR": "Cambodian Riel (KHR)",
    "IDR": "Indonesian Rupiah (IDR)",
    "LAK": "Lao Kip (LAK)",
    "MYR": "Malaysian Ringgit (MYR)",
    "MMK": "Myanmar Kyat (MMK)",
    "PHP": "Philippine Peso (PHP)",
    "SGD": "Singapore Dollar (SGD)",
    "THB": "Thai Baht (THB)",
    "VND": "Vietnamese Đồng (VND)",
    "CNY": "Chinese Yuan Renminbi (CNY)",
    "HKD": "Hong Kong Dollar (HKD)",
    "AUD": "Australian Dollar (AUD)",
    "EUR": "Euro (EUR) - Used in the European Union",
    "USD": "United States Dollar (USD)",
    "INR": "Indian Rupee (INR)",
}
_JA_CURRENCY_ALIAS_PATTERNS = [
    ("MYR", [r"(?<![a-z])myr(?![a-z])", r"(?<![a-z])rm(?![a-z])", r"malaysian\s+ringgit", r"\bringgit\b"]),
    ("SGD", [r"(?<![a-z])sgd(?![a-z])", r"(?<![a-z])s\$", r"singapore\s+dollars?", r"sing\s*dollars?"]),
    ("USD", [r"(?<![a-z])usd(?![a-z])", r"(?<![a-z])us\$", r"u\.?s\.?\s*dollars?", r"united\s+states\s+dollars?"]),
    ("AUD", [r"(?<![a-z])aud(?![a-z])", r"(?<![a-z])a\$", r"australian\s+dollars?"]),
    ("EUR", [r"(?<![a-z])eur(?![a-z])", r"€", r"\beuros?\b"]),
    ("INR", [r"(?<![a-z])inr(?![a-z])", r"₹", r"(?<![a-z])rs\.?(?![a-z])", r"indian\s+rupees?", r"\brupees?\b"]),
    ("IDR", [r"(?<![a-z])idr(?![a-z])", r"(?<![a-z])rp\.?(?![a-z])", r"indonesian\s+rupiah", r"\brupiah\b"]),
    ("BND", [r"(?<![a-z])bnd(?![a-z])", r"(?<![a-z])bn\$", r"brunei\s+dollars?"]),
    ("KHR", [r"(?<![a-z])khr(?![a-z])", r"cambodian\s+riel", r"\briel\b"]),
    ("LAK", [r"(?<![a-z])lak(?![a-z])", r"lao\s+kip", r"\bkip\b"]),
    ("MMK", [r"(?<![a-z])mmk(?![a-z])", r"myanmar\s+kyat", r"burmese\s+kyat", r"\bkyat\b"]),
    ("PHP", [r"(?<![a-z])php(?![a-z])", r"₱", r"philippine\s+pesos?", r"filipino\s+pesos?"]),
    ("THB", [r"(?<![a-z])thb(?![a-z])", r"฿", r"thai\s+baht", r"\bbaht\b"]),
    ("VND", [r"(?<![a-z])vnd(?![a-z])", r"₫", r"vietnamese\s+(?:dong|đồng)", r"\b(?:dong|đồng)\b"]),
    ("CNY", [r"(?<![a-z])cny(?![a-z])", r"(?<![a-z])rmb(?![a-z])", r"chinese\s+yuan", r"yuan\s+renminbi", r"\brenminbi\b", r"\byuan\b"]),
    ("HKD", [r"(?<![a-z])hkd(?![a-z])", r"(?<![a-z])hk\$", r"hong\s+kong\s+dollars?"]),
]


def _ja_salary_currency_candidates_from_field(raw):
    """Return supported currency aliases found in one salary field, in text order.

    The caller must pass only Current Salary Breakdown or Expected Salary.  The
    result is deliberately evidence-bearing so an AI response cannot override a
    single explicit alias and can only disambiguate between aliases actually
    present in the same field.
    """
    text = _ja_salary_normalize_recruiter_typos(raw)
    if not text.strip():
        return []
    by_code = {}
    for code, patterns in _JA_CURRENCY_ALIAS_PATTERNS:
        for pattern in patterns:
            for match in re.finditer(pattern, text, re.I):
                item = {
                    "code": code,
                    "start": int(match.start()),
                    "end": int(match.end()),
                    "evidence": match.group(0),
                }
                previous = by_code.get(code)
                if previous is None or item["start"] < previous["start"]:
                    by_code[code] = item
    return sorted(by_code.values(), key=lambda item: (item["start"], item["code"]))


def _ja_salary_currency_from_field(raw):
    """Detect a supported JobAdder currency from one salary field only.

    A single explicit alias is authoritative.  When a field genuinely contains
    multiple currencies, this compatibility helper returns the earliest textual
    clue; `_ja_currency_selection` may let AI disambiguate only among those
    explicit candidates.
    """
    candidates = _ja_salary_currency_candidates_from_field(raw)
    return candidates[0]["code"] if candidates else None


def _ja_candidate_existing_currency(candidate):
    employment = (candidate or {}).get("employment") if isinstance(candidate, dict) else {}
    if isinstance(employment, dict):
        # Expected/ideal currency is preferred when a saved profile already has
        # two different currencies, mirroring the OneNote expected-wins rule.
        for branch in ("ideal", "current"):
            item = employment.get(branch)
            salary = item.get("salary") if isinstance(item, dict) else None
            code = str((salary or {}).get("currency") or "").strip().upper() if isinstance(salary, dict) else ""
            if code in _JA_CURRENCY_OPTIONS:
                return code
    for item in (candidate or {}).get("custom") or []:
        if not isinstance(item, dict):
            continue
        try:
            field_id = int(item.get("fieldId") or 0)
        except Exception:
            continue
        if field_id != _JA_CURRENCY_CUSTOM_FIELD_ID:
            continue
        value = str(item.get("value") or "")
        for code, label in _JA_CURRENCY_OPTIONS.items():
            if value == label or re.search(r"\({}\)".format(re.escape(code)), value, re.I):
                return code
    return None


def _ja_currency_option_for_code(code):
    return _JA_CURRENCY_OPTIONS.get(str(code or "").strip().upper())


def _ja_currency_selection(current_raw, expected_raw, candidate=None, ai_components=None):
    """Resolve per-field currencies and the single JobAdder dropdown value.

    Deterministic explicit aliases outrank AI.  AI can assist only when a salary
    field contains multiple explicit supported currencies, or when no explicit
    alias is present.  Expected Salary still wins the one JobAdder dropdown.
    """
    ai_components = ai_components if isinstance(ai_components, dict) else {}
    ai_cur = str(ai_components.get("currentCurrency") or ((ai_components.get("current") or {}).get("currency") if isinstance(ai_components.get("current"), dict) else "") or "").upper()
    ai_exp = str(ai_components.get("expectedCurrency") or ((ai_components.get("expected") or {}).get("currency") if isinstance(ai_components.get("expected"), dict) else "") or "").upper()
    if ai_cur not in _JA_CURRENCY_OPTIONS:
        ai_cur = None
    if ai_exp not in _JA_CURRENCY_OPTIONS:
        ai_exp = None

    current_candidates = _ja_salary_currency_candidates_from_field(current_raw)
    expected_candidates = _ja_salary_currency_candidates_from_field(expected_raw)

    def resolve(candidates, ai_code, field_name):
        codes = [item["code"] for item in candidates]
        if len(codes) == 1:
            warning = None
            if ai_code and ai_code != codes[0]:
                warning = "AI currency {} conflicted with explicit {} alias {}; explicit alias was retained.".format(ai_code, field_name, codes[0])
            return codes[0], field_name + "_explicit_alias", warning
        if len(codes) > 1:
            if ai_code in codes:
                return ai_code, field_name + "_ai_disambiguated_explicit_aliases", None
            warning = "Multiple explicit currencies were found in {} ({}); earliest textual alias {} was used.".format(field_name.replace("_", " "), ", ".join(codes), codes[0])
            if ai_code:
                warning += " AI suggested {} but it was not one of the explicit aliases.".format(ai_code)
            return codes[0], field_name + "_ambiguous_earliest_alias", warning
        if ai_code:
            return ai_code, field_name + "_ai_only", None
        return None, field_name + "_none", None

    current_currency, current_source, current_warning = resolve(current_candidates, ai_cur, "current_salary")
    expected_currency, expected_source, expected_warning = resolve(expected_candidates, ai_exp, "expected_salary")
    existing_currency = _ja_candidate_existing_currency(candidate)
    selected = expected_currency or current_currency or existing_currency
    if expected_currency:
        rule = "expected_salary_currency_wins"
        source = expected_source
    elif current_currency:
        rule = "current_salary_currency_used"
        source = current_source
    elif existing_currency:
        rule = "existing_candidate_currency_preserved"
        source = "existing_candidate_profile"
    else:
        rule = "no_currency_detected"
        source = "none"
    warnings = [x for x in (current_warning, expected_warning) if x]
    return {
        "currentCurrency": current_currency,
        "expectedCurrency": expected_currency,
        "selectedCurrency": selected,
        "jobAdderOption": _ja_currency_option_for_code(selected),
        "selectionRule": rule,
        "selectionSource": source,
        "detectionScope": ["current_salary_breakdown", "expected_salary"],
        "ignoredScreeningFields": ["brief_overview", "reason_leaving", "looking_for", "leads", "remarks", "presentability_rating", "notice_period"],
        "localCurrentCurrency": current_candidates[0]["code"] if current_candidates else None,
        "localExpectedCurrency": expected_candidates[0]["code"] if expected_candidates else None,
        "localCurrentCandidates": current_candidates,
        "localExpectedCandidates": expected_candidates,
        "aiCurrentCurrency": ai_cur,
        "aiExpectedCurrency": ai_exp,
        "existingCurrency": existing_currency,
        "optionSource": "configured_supported_list" if selected else "none",
        "optionValidated": False,
        "warning": " ".join(warnings) if warnings else None,
    }


def _ja_validate_currency_option_with_api(selection):
    """Validate custom field 4 against the tenant's official field definition.

    If the read fails, use the exact supported option list supplied for this
    tenant. If the field definition is read successfully but the option is not
    present, skip the custom-field write rather than submitting an invalid value.
    """
    selection = dict(selection or {})
    code = str(selection.get("selectedCurrency") or "").upper()
    default = _ja_currency_option_for_code(code)
    if not code or not default:
        return selection
    try:
        status, data = _ja_get_json("candidates/fields/custom/{}".format(_JA_CURRENCY_CUSTOM_FIELD_ID), timeout=15)
        values = data.get("values") if isinstance(data, dict) else None
        values = [str(x) for x in (values or []) if str(x).strip()]
        if values:
            exact = default if default in values else next((x for x in values if re.search(r"\({}\)".format(re.escape(code)), x, re.I)), None)
            if exact:
                selection.update({"jobAdderOption": exact, "optionSource": "official_candidate_custom_field_definition", "optionValidated": True, "definitionStatus": status})
            else:
                selection.update({"jobAdderOption": None, "optionSource": "official_candidate_custom_field_definition", "optionValidated": False, "definitionStatus": status, "warning": "Detected {} but JobAdder Currency field 4 did not advertise a matching option.".format(code)})
        else:
            selection.update({"jobAdderOption": default, "optionSource": "configured_supported_list_empty_api_values", "optionValidated": False, "definitionStatus": status})
    except Exception as e:
        selection.update({"jobAdderOption": default, "optionSource": "configured_supported_list_api_read_failed", "optionValidated": False, "definitionError": str(e)[:300]})
    return selection


# Recruiter salary notes are often typed quickly and contain predictable
# spelling variants.  Normalize only a conservative allow-list inside the two
# salary fields; never run broad fuzzy autocorrection that could silently turn
# unrelated prose into salary components.  The original raw note remains the
# stored/displayed breakdown.
_JA_SALARY_TYPO_RULES = [
    (
        "ordinal_month",
        re.compile(
            r"(?<![a-z0-9])(\d+(?:\.\d+)?(?:th|st|nd|rd))\s*"
            r"(?:monnth|monnths|monht|monhth|moth|mnth|mth|mthh|mnt)(s?)(?![a-z])",
            re.I,
        ),
        lambda m: m.group(1) + " month" + ("s" if m.group(2) else ""),
    ),
    (
        "allowance",
        re.compile(
            r"(?<![a-z])(?:allowance|allowence|allowanse|alowance|alowence|alowanse|"
            r"allwance|allwan(?:ce)?|alwance|alwan(?:ce)?|allowan(?:ce)?|allownce|"
            r"alowanc(?:e)?|alwanc(?:e)?|allowanc(?:e)?|alwnce|alwn|sllowance)(?![a-z])",
            re.I,
        ),
        "allowance",
    ),
    (
        "month",
        re.compile(
            r"(?<![a-z])(?:month|monnth|monnths|monht|monhth|moth|mnth|mth|mthh|mnt)(s?)(?![a-z])",
            re.I,
        ),
        lambda m: "month" + ("s" if m.group(1) else ""),
    ),
    (
        "bonus",
        re.compile(r"(?<![a-z])(?:bonus|bonous|bouns|bonos|bonnus|bnus)(?![a-z])", re.I),
        "bonus",
    ),
    (
        "epf",
        re.compile(r"(?<![a-z])(?:epf|efp|epff)(?![a-z])", re.I),
        "EPF",
    ),
    (
        "percent",
        re.compile(r"(?<![a-z])(?:percent|precent|persent|percet|percnt)(?![a-z])", re.I),
        "percent",
    ),
    (
        "myr_currency",
        re.compile(
            r"(?<![a-z])(?:ringgit|rngint|rnggit|ringit|ringgt|ringgitt|ringet|"
            r"renggit|rengit|ringint|ringgint|rngit|rngt)(?![a-z])",
            re.I,
        ),
        "MYR",
    ),
]


def _ja_salary_normalize_recruiter_typos(raw, with_changes=False):
    """Normalize conservative salary-only typo aliases deterministically.

    This is intentionally scoped to Current Salary Breakdown / Expected Salary
    parser calls.  It does not inspect Summary, RFL, Looking For, Remarks or any
    other Screening Call section.
    """
    text = str(raw or "")
    changes = []
    for rule_name, pattern, replacement in _JA_SALARY_TYPO_RULES:
        def repl(match, _replacement=replacement, _name=rule_name):
            value = _replacement(match) if callable(_replacement) else _replacement
            original = match.group(0)
            if original.casefold() != str(value).casefold():
                changes.append({"type": _name, "from": original, "to": value})
            return value
        text = pattern.sub(repl, text)
    return (text, changes) if with_changes else text


def _ja_salary_plain_number(raw):
    tokens = _ja_salary_amount_tokens(raw)
    return int(tokens[0]["value"]) if tokens else None


def _ja_salary_has_actual_amount(raw):
    text = _ja_salary_normalize_recruiter_typos(raw).replace(",", "")
    return bool(re.search(r"\b\d+(?:\.\d+)?\s*[kK]\b", text) or re.search(r"\b\d{4,8}\b", text))


def _ja_salary_currency(raw_values, candidate=None):
    values = list(raw_values or [])
    current_raw = values[0] if values else ""
    expected_raw = values[1] if len(values) > 1 else ""
    return _ja_currency_selection(current_raw, expected_raw, candidate).get("selectedCurrency")


_JA_SALARY_ANNUAL_COMPONENT_RE = re.compile(
    r"(?:\b(?:1[2-9]|2[0-4])(?:\.\d+)?\s*(?:th|st|nd|rd)?\s*(?:mon+ths?|mnths?|mths?|mos?)\b|"
    r"(?:x|×)\s*(?:1[2-9]|2[0-4])(?:\.\d+)?\b|\b(?:1[2-9]|2[0-4])(?:\.\d+)?\s*(?:th|st|nd|rd)\s*(?:salary|pay|bonus)\b|\bAWS\b|\bannual\s+wage\s+supplement\b|"
    r"\b(?:contractual|guaranteed|fixed)\s+bonus\b|\bbonus\s+(?:contractual|guaranteed|fixed)\b)",
    re.I,
)
_JA_SALARY_EXCLUDED_COMPONENT_RE = re.compile(
    r"(?:\bbonus\b|\bannual\s+wage\s+supplement\b|\bAWS\b|\bEPF\b|\bKWSP\b|\bSOCSO\b|\bEIS\b|"
    r"\bcommission\b|\bincentive\b|\bvariable\b|\bperformance\b|\bRSU\b|\bESOP\b|\bstock\b|\bshares?\b|"
    r"\boptions?\b|\bclaims?\b|\bclaimable\b|\breimburse(?:ment|able)?\b|\bmedical\b|\binsurance\b|"
    r"\bemployer\s+contribution\b|\btravel\s+claim\b|\bparking\s+claim\b)",
    re.I,
)
_JA_SALARY_ALLOWANCE_COMPONENT_RE = re.compile(
    r"(?:(?<![a-z])(?:allowance|allowence|alowance|sllowance)\b|\btransport\b|\bphone\b|\bmobile\b|"
    r"\bhousing\b|\bcar\b|\bmeal\b|\bcash\s+allowance\b)",
    re.I,
)
_JA_SALARY_FIXED_RECURRING_RE = re.compile(r"\b(?:fixed|monthly|per\s+month|recurring|regular)\b", re.I)
_JA_SALARY_BASE_HINT_RE = re.compile(r"\b(?:current|salary|base|basic|last\s+drawn|monthly\s+pay|package)\b", re.I)


def _ja_round_currency(value):
    """Round positive salary values consistently across Python and JavaScript.

    Python's built-in round uses banker's rounding while JavaScript Math.round
    rounds .5 upward for positive numbers. ROUND_HALF_UP removes that drift.
    """
    try:
        return int(Decimal(str(value)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    except Exception:
        return None


def _ja_salary_component_parts(raw):
    """Split a salary breakdown without breaking thousand separators."""
    normalized = _ja_salary_normalize_recruiter_typos(raw)
    return [
        part.strip()
        for part in re.split(r"\s*\+\s*|[;\n]+|,(?!\d{3}\b)", normalized)
        if part and part.strip()
    ]


def _ja_salary_amount_tokens(raw):
    """Return normalized salary amount tokens while ignoring periods/percentages.

    Besides K shorthand, support common regional salary notation used by the
    configured currency list: M/million, Indian lakh/lac/L and crore/Cr.  A bare
    `m` is treated as million only when the salary field contains an explicit
    currency clue, and `2m bonus`-style month shorthand is excluded.
    """
    text = _ja_salary_normalize_recruiter_typos(raw).replace(",", "")
    field_currency = _ja_salary_currency_from_field(text)
    # JobAdder stores monthly salary.  Annual/per-annum amounts are normalized
    # per salary component, not across the whole field.  This matters for input
    # such as ``RM120k annual + RM500 monthly allowance``: only the first
    # component is divided by 12.
    annual_re = re.compile(
        r"(?:\bper\s+annum\b|\bp\.?\s*a\.?\b|/\s*annum\b|"
        r"\bannual(?:ly)?\b|\bper\s+year\b|/\s*year\b|\byearly\b|\blpa\b)",
        re.I,
    )
    out = []
    currency_after = r"(?:RM|MYR|SGD|USD|AUD|EUR|IDR|PHP|BND|KHR|LAK|MMK|THB|VND|CNY|HKD|INR)"
    # Recruiter notes often omit whitespace between an amount and the component
    # label (for example ``32sllowance`` or ``16epf``).  Permit only known
    # salary-component labels here so the tokenizer does not start accepting
    # arbitrary digits embedded in prose.
    component_after = (
        r"(?:allowance|allowence|alowance|sllowance|epf|kwsp|socso|eis|"
        r"bonus|commission|incentive|claim|claims|reimbursement|reimbursements)"
    )
    pattern = re.compile(
        r"(\d+(?:\.\d+)?)(?![\d.])\s*"
        r"(million|millions|mil|crore|crores|cr|lpa|lakh|lakhs|lac|lacs|[kKmMLl])?"
        r"(?=\s*" + currency_after + r"\b|\s*" + component_after + r"\b|\b)",
        re.I,
    )
    for m in pattern.finditer(text):
        number = float(m.group(1))
        suffix_token = str(m.group(2) or "")
        suffix_lower = suffix_token.lower()
        suffix = text[m.end():m.end() + 32]
        prefix = text[max(0, m.start() - 16):m.start()]
        # Do not reinterpret the lower bound of ``15-30%`` as a fixed salary
        # amount.  The upper bound is already caught by the direct-percent
        # guard below; this companion guard covers the first number.
        if not suffix_token and re.match(
            r"\s*(?:-|–|—|to\b)\s*\d+(?:\.\d+)?\s*(?:%|percent\b|pct\b)",
            suffix,
            re.I,
        ):
            continue
        if re.match(r"\s*(?:%|percent\b|pct\b)", suffix, re.I):
            continue
        if re.match(r"\s*(?:th|st|nd|rd)?\s*(?:day|days|week|weeks|mon+th|mon+ths|mnth|mnths|mth|mths|mo|mos|year|years)\b", suffix, re.I):
            continue
        if 12 <= number <= 36 and re.match(r"\s*(?:th|st|nd|rd)\s*(?:salary|pay|bonus)\b", suffix, re.I):
            continue
        if 12 <= number <= 36 and re.search(r"(?:x|×)\s*$", prefix, re.I):
            continue
        if suffix_lower == "m" and number <= 12 and re.match(r"\s*(?:bonus|salary\s+months?|months?|mths?)\b", suffix, re.I):
            continue
        if re.search(r"(?:date|day|week|month|year)\s*$", prefix, re.I) and not suffix_token and number < 1000:
            continue

        scale = 1
        kind = "plain"
        if suffix_lower == "k":
            scale, kind = 1000, "thousand"
        elif suffix_lower in ("million", "millions", "mil"):
            scale, kind = 1000000, "million"
        elif suffix_lower == "m":
            if not field_currency:
                # Ambiguous without a salary currency clue; let AI assist rather
                # than deterministically turning month shorthand into millions.
                continue
            scale, kind = 1000000, "million"
        elif suffix_lower == "lpa":
            scale, kind = 100000, "lakh_per_annum"
        elif suffix_lower in ("l", "lakh", "lakhs", "lac", "lacs"):
            if suffix_lower == "l" and field_currency != "INR":
                continue
            scale, kind = 100000, "lakh"
        elif suffix_lower in ("cr", "crore", "crores"):
            scale, kind = 10000000, "crore"

        component_start = max(text.rfind("+", 0, m.start()), text.rfind(";", 0, m.start()), text.rfind("\n", 0, m.start())) + 1
        component_ends = [pos for pos in (text.find("+", m.end()), text.find(";", m.end()), text.find("\n", m.end())) if pos >= 0]
        component_end = min(component_ends) if component_ends else len(text)
        token_component = text[component_start:component_end]
        annual_divisor = 12 if (annual_re.search(token_component) or suffix_lower == "lpa") else 1
        value = _ja_round_currency(Decimal(str(number)) * Decimal(scale) / Decimal(annual_divisor))
        if value is None or value <= 0:
            continue
        out.append({
            "start": m.start(), "end": m.end(), "value": value,
            "raw": m.group(0), "isK": scale == 1000, "scale": scale,
            "scaleKind": kind, "numeric": number,
            "sourceFrequency": "annual" if annual_divisor == 12 else "monthly_or_unspecified",
            "annualDivisor": annual_divisor,
        })
    return out


def _ja_extract_guaranteed_salary_months(raw):
    """Return one canonical guaranteedSalaryMonths value.

    Total-package expressions (13, 13.5, 14, 14.5 months, x13, etc.)
    establish a total. AWS/13th month establishes 13. Explicit N-month
    contractual/guaranteed/fixed bonuses are additions to the total salary
    months. Performance/variable/discretionary bonuses are never additions.
    """
    raw_text = str(raw or "")
    parts = _ja_salary_component_parts(raw_text)
    total_candidates = []
    bonus_additions = []
    evidence = []

    total_patterns = [
        re.compile(r"\b((?:1[2-9]|2[0-4])(?:\.\d+)?)\s*(?:th|st|nd|rd)?\s*(?:mon+ths?|mnths?|mths?|mos?)\b", re.I),
        # Recruiter shorthand often appears as "13.5th bonus" or
        # "14th bonus". In salary breakdown context this describes the
        # guaranteed total salary-month package, not an additional 13.5/14
        # bonus months. Treat it as the same total as "13.5 months".
        re.compile(r"\b((?:1[2-9]|2[0-4])(?:\.\d+)?)\s*(?:th|st|nd|rd)\s*(?:month(?:ly)?|salary|pay|bonus)\b", re.I),
        re.compile(r"(?:x|×)\s*((?:1[2-9]|2[0-4])(?:\.\d+)?)\b", re.I),
    ]
    bonus_patterns = [
        re.compile(r"\b(\d+(?:\.\d+)?)\s*(?:mon+ths?|mnths?|mths?)\s*(?:of\s+)?(?:contractual|guaranteed|fixed)\s*(?:cash\s+)?bonus\b", re.I),
        re.compile(r"\b(?:contractual|guaranteed|fixed)\s*(?:cash\s+)?bonus(?:\s+(?:of|equivalent\s+to))?\s*(\d+(?:\.\d+)?)\s*(?:mon+ths?|mnths?|mths?)\b", re.I),
    ]

    for part in parts or [raw_text]:
        for pattern in total_patterns:
            for m in pattern.finditer(part):
                value = float(m.group(1))
                if 12 <= value <= 36:
                    total_candidates.append(value)
                    evidence.append({"type": "total_salary_months", "months": value, "raw": m.group(0)})
        if re.search(r"\b(?:AWS|annual\s+wage\s+supplement)\b", part, re.I):
            total_candidates.append(13.0)
            evidence.append({"type": "aws", "months": 13.0, "raw": part})
        # 13th month is already caught by the total pattern. Keep this explicit
        # fallback for unusual wording such as "13th-month pay".
        if re.search(r"\b13th[-\s]+(?:mon+th|mnth|mth)(?:\s+pay|\s+salary|\s+bonus)?\b", part, re.I):
            total_candidates.append(13.0)
        for pattern in bonus_patterns:
            for m in pattern.finditer(part):
                value = float(m.group(1))
                if 0 < value < 12:
                    # "inclusive/included" usually describes a total package,
                    # so do not add the same bonus twice.
                    if re.search(r"\b(?:incl|including|included|inclusive|comprising)\b", part, re.I):
                        continue
                    bonus_additions.append(value)
                    evidence.append({"type": "guaranteed_bonus_months", "months": value, "raw": m.group(0)})

    # Overlapping shorthand patterns can both match the same phrase (for
    # example ``13th month``).  Keep one evidence item so records remain stable
    # and readable even though duplicate candidates would not change max().
    deduped_evidence = []
    seen_evidence = set()
    for item in evidence:
        key = (str(item.get("type") or ""), float(item.get("months") or 0), str(item.get("raw") or "").strip().lower())
        if key in seen_evidence:
            continue
        seen_evidence.add(key)
        deduped_evidence.append(item)
    evidence = deduped_evidence

    base_total = max(total_candidates) if total_candidates else 12.0
    total = base_total + sum(bonus_additions)
    if total < 12:
        total = 12.0
    if total > 36:
        total = 36.0
    return {
        "guaranteedSalaryMonths": float(total),
        "baseSalaryMonths": float(base_total),
        "additionalGuaranteedBonusMonths": float(sum(bonus_additions)),
        "evidence": evidence,
    }


def _ja_salary_component_is_excluded(part):
    text = _ja_salary_normalize_recruiter_typos(part)
    if _JA_SALARY_ANNUAL_COMPONENT_RE.search(text):
        return True
    if _JA_SALARY_EXCLUDED_COMPONENT_RE.search(text):
        return True
    if re.search(r"\d+(?:\.\d+)?\s*%", text):
        return True
    if re.fullmatch(r"\s*\d+(?:\.\d+)?\s*(?:days?|weeks?|months?|years?)\s*", text, re.I):
        return True
    return False


def _ja_salary_currency_label(currency):
    code = str(currency or "").upper()
    return {"MYR": "RM", "SGD": "SGD", "USD": "USD", "AUD": "AUD", "GBP": "GBP", "EUR": "EUR", "IDR": "IDR", "PHP": "PHP", "BND": "BND"}.get(code, code)


def _ja_salary_display(currency, min_value, max_value=None, equivalent=False):
    if min_value is None:
        return ""
    label = _ja_salary_currency_label(currency)
    left = "{:,}".format(int(min_value))
    prefix = (label + " ") if label else ""
    if max_value is not None and int(max_value) != int(min_value):
        body = "{}{} to {}{}".format(prefix, left, prefix, "{:,}".format(int(max_value)))
    else:
        body = prefix + left
    return body + ("/month equivalent" if equivalent else "/month")


def _ja_calc_fixed_salary_detailed(raw, currency=None):
    """Calculate one deterministic monthly-equivalent current salary object.

    The helper has a stable mapping contract: unparseable or incomplete input
    returns an empty dict rather than None, so future direct callers can safely
    inspect fields without a NoneType failure.
    """
    if not str(raw or "").strip():
        return {}
    parts = _ja_salary_component_parts(raw)
    if not parts:
        return {}

    token_parts = []
    for index, part in enumerate(parts):
        for token in _ja_salary_amount_tokens(part):
            token_parts.append((index, part, token))
    if not token_parts:
        return {}

    # Month markers, percentages, EPF and bonus counters must never become the
    # base salary. Token filtering removes those markers; eligibility then keeps
    # salary-sized values or a smaller amount explicitly labelled base/current.
    eligible = []
    for item in token_parts:
        _index, part, token = item
        base_hint = bool(_JA_SALARY_BASE_HINT_RE.search(part))
        allowance_only = bool(_JA_SALARY_ALLOWANCE_COMPONENT_RE.search(part)) and not re.search(r"\b(?:base|basic|current|last\s+drawn)\b", part, re.I)
        salary_sized = bool(token["isK"] or token["value"] >= 1000)
        if (salary_sized or (base_hint and not allowance_only)) and not (token["value"] < 1000 and _JA_SALARY_EXCLUDED_COMPONENT_RE.search(part)):
            eligible.append(item)
    if not eligible:
        return {}

    base_item = None
    for item in eligible:
        index, part, token = item
        if _JA_SALARY_BASE_HINT_RE.search(part) and not (
            _JA_SALARY_ALLOWANCE_COMPONENT_RE.search(part)
            and not re.search(r"\b(?:base|basic|current|salary|last\s+drawn)\b", part, re.I)
        ):
            base_item = item
            break
    if base_item is None:
        base_item = next((item for item in eligible if item[2]["isK"] or item[2]["value"] >= 1000), None)
    if base_item is None:
        base_item = eligible[0]

    base_index, base_part, base_token = base_item
    base = int(base_token["value"])
    allowances = 0
    included = []
    excluded = []

    month_info = _ja_extract_guaranteed_salary_months(raw)
    guaranteed_months = float(month_info["guaranteedSalaryMonths"])

    for index, part in enumerate(parts):
        tokens = _ja_salary_amount_tokens(part)
        is_excluded = _ja_salary_component_is_excluded(part)
        allowance_like = bool(_JA_SALARY_ALLOWANCE_COMPONENT_RE.search(part))
        fixed_recurring = bool(_JA_SALARY_FIXED_RECURRING_RE.search(part))
        base_hint = bool(_JA_SALARY_BASE_HINT_RE.search(part))
        if is_excluded:
            # If the same component combines a real base with an annual marker,
            # preserve the base but never add the marker's number as cash.
            non_base_tokens = [t for t in tokens if not (index == base_index and t["start"] == base_token["start"] and t["value"] == base)]
            if non_base_tokens or index != base_index:
                if part not in excluded:
                    excluded.append(part)
            continue
        for token in tokens:
            if index == base_index and token["start"] == base_token["start"] and token["value"] == base:
                continue
            stripped_cash = re.sub(
                r"(?i)(?:RM|MYR|SGD|USD|AUD|GBP|EUR|IDR|PHP|BND|KHR|LAK|MMK|THB|VND|CNY|HKD|INR|S\$|US\$|A\$|HK\$|BN\$)",
                "",
                part,
            ).strip()
            bare_additive_cash = bool(
                index != base_index
                and len(tokens) == 1
                and int(token["value"]) >= 50
                and re.fullmatch(r"\d+(?:\.\d+)?\s*[kK]?", stripped_cash)
            )
            include_as_allowance = allowance_like or (fixed_recurring and not base_hint) or bare_additive_cash
            if include_as_allowance:
                allowances += int(token["value"])
                included.append({
                    "raw": part,
                    "value": int(token["value"]),
                    "classification": "bare_additive_fixed_cash" if bare_additive_cash else "labelled_fixed_allowance",
                })
            elif token["value"] != base and part not in excluded:
                excluded.append(part)

    multiplier = guaranteed_months / 12.0
    adjusted_base = _ja_round_currency(Decimal(base) * Decimal(str(guaranteed_months)) / Decimal(12))
    value = _ja_round_currency(Decimal(base) * Decimal(str(guaranteed_months)) / Decimal(12) + Decimal(allowances))
    return {
        "value": value,
        "base": base,
        "baseMonthly": base,
        "guaranteedSalaryMonths": guaranteed_months,
        "baseSalaryMonths": month_info["baseSalaryMonths"],
        "additionalGuaranteedBonusMonths": month_info["additionalGuaranteedBonusMonths"],
        "monthEvidence": month_info["evidence"],
        "multiplier": multiplier,
        "adjustedBase": adjusted_base,
        "allowances": int(allowances),
        "fixedMonthlyAllowance": int(allowances),
        "otherFixedMonthlyCash": 0,
        "includedEmployerEpf": 0,
        "includedAllowances": included,
        "excluded": excluded,
        "monthlyEquivalent": value,
        "display": _ja_salary_display(currency, value, equivalent=True),
        "breakdown": str(raw or "").strip(),
        "monthlyRule": "canonical_guaranteed_months_plus_fixed_monthly_cash",
        "roundingRule": "ROUND_HALF_UP_TO_WHOLE_CURRENCY",
    }


def _ja_salary_parse_range(raw):
    clean = _ja_salary_normalize_recruiter_typos(raw).replace(",", "")
    pct = re.search(r"%|\bpercent\b|\bpct\b", clean, re.I)
    if pct:
        before = clean[:pct.start()]
        if not _ja_salary_amount_tokens(before):
            return None
    tokens = _ja_salary_amount_tokens(clean)
    if not tokens:
        return None
    if len(tokens) >= 2:
        first, second = tokens[0], tokens[1]
        between = clean[first["end"]:second["start"]]
        if re.search(r"(?:-|–|—|\bto\b|~)", between, re.I):
            left, right = int(first["value"]), int(second["value"])
            # In 13-15k / 20-25m shorthand, inherit the scale from the right.
            if int(first.get("scale") or 1) == 1 and int(second.get("scale") or 1) > 1 and float(first.get("numeric") or 0) < 1000:
                left = _ja_round_currency(
                    Decimal(str(first.get("numeric") or 0))
                    * Decimal(int(second.get("scale") or 1))
                    / Decimal(int(second.get("annualDivisor") or 1))
                )
            return {"min": min(left, right), "max": max(left, right)} if left > 0 and right > 0 else None
    value = int(tokens[0]["value"])
    return {"min": value, "max": value} if value > 0 else None


def _ja_salary_parse_percent_increment(raw):
    text = _ja_salary_normalize_recruiter_typos(raw).replace("％", "%")
    if not re.search(r"%|\bpercent\b|\bpct\b", text, re.I):
        return None
    num = r"([+-]?\d+(?:\.\d+)?)"
    unit = r"(?:%|percent|pct)"
    sep = r"(?:-|–|—|to|until|~)"
    patterns = [
        re.compile(num + r"\s*" + unit + r"\s*" + sep + r"\s*" + num + r"(?:\s*" + unit + r")?", re.I),
        re.compile(num + r"\s*(?:" + unit + r")?\s*" + sep + r"\s*" + num + r"\s*" + unit, re.I),
    ]
    for pattern in patterns:
        m = pattern.search(text)
        if m:
            lo, hi = float(m.group(1)), float(m.group(2))
            if lo > -100 and hi > -100 and max(abs(lo), abs(hi)) <= 500:
                return {"min": min(lo, hi), "max": max(lo, hi), "raw": m.group(0)}
    m = re.search(num + r"\s*" + unit, text, re.I)
    if m:
        value = float(m.group(1))
        if value > -100 and abs(value) <= 500:
            return {"min": value, "max": value, "raw": m.group(0)}
    return None


def _ja_expected_means_same_as_current(raw):
    text = str(raw or "").lower().strip()
    patterns = [
        r"\bsame\s+as\s+current\b", r"\bsame\s+current\b", r"\bmaintain\s+(?:the\s+)?current\b",
        r"\bmatch\s+(?:the\s+)?current\b", r"\bno\s+(?:increment|increase|change)\b",
        r"\b(?:horizontal|lateral)\s+move\b", r"\bcurrent\s+(?:salary|package|compensation)\s+(?:is\s+)?(?:ok|okay|fine|acceptable)\b",
        r"\bopen\s+to\s+current\b", r"\bas\s+current\b",
    ]
    return any(re.search(pattern, text, re.I) for pattern in patterns)


def _ja_expected_is_open(raw):
    return bool(re.search(r"\b(?:open|negotiable|nego|discuss|tbd|n/?a|not\s+available|flexible)\b", str(raw or ""), re.I))


def _ja_build_expected_canonical(expected_raw, current_value, currency=None):
    raw = str(expected_raw or "").strip()
    out = {
        "raw": raw,
        "type": "blank" if not raw else "unparsed",
        "monthlyAmount": None,
        "minAmount": None,
        "maxAmount": None,
        "percent": None,
        "percentMin": None,
        "percentMax": None,
        "basisCurrentAmount": None,
        "display": "",
        "writeToProfile": False,
    }
    if not raw:
        return out

    # Priority 1-2: explicit fixed amount/range always wins over percentage.
    explicit = _ja_salary_parse_range(raw)
    if explicit:
        lo, hi = int(explicit["min"]), int(explicit.get("max", explicit["min"]))
        out.update({
            "type": "fixed" if lo == hi else "range",
            "monthlyAmount": lo if lo == hi else None,
            "minAmount": lo,
            "maxAmount": hi,
            "display": _ja_salary_display(currency, lo, hi),
            "writeToProfile": True,
        })
        return out

    # Priority 3: only explicit same-as-current intent, not any mention of current.
    if _ja_expected_means_same_as_current(raw):
        out["type"] = "same_as_current"
        if current_value is not None:
            value = int(current_value)
            out.update({
                "monthlyAmount": value, "minAmount": value, "maxAmount": value,
                "basisCurrentAmount": value, "display": _ja_salary_display(currency, value),
                "writeToProfile": True,
            })
        else:
            out["type"] = "same_as_current_unresolved"
        return out

    # Priority 4-5: percentage increment/range from the one canonical current.
    pct = _ja_salary_parse_percent_increment(raw)
    if pct:
        out.update({
            "type": "percent" if pct["min"] == pct["max"] else "percent_range",
            "percent": pct["min"] if pct["min"] == pct["max"] else None,
            "percentMin": pct["min"], "percentMax": pct["max"],
            "basisCurrentAmount": int(current_value) if current_value is not None else None,
        })
        if current_value is not None:
            lo = _ja_round_currency(Decimal(int(current_value)) * (Decimal(1) + Decimal(str(pct["min"])) / Decimal(100)))
            hi = _ja_round_currency(Decimal(int(current_value)) * (Decimal(1) + Decimal(str(pct["max"])) / Decimal(100)))
            out.update({
                "monthlyAmount": lo if lo == hi else None, "minAmount": lo, "maxAmount": hi,
                "display": _ja_salary_display(currency, lo, hi), "writeToProfile": True,
            })
        else:
            out["type"] += "_unresolved"
        return out

    # Priority 6: open/negotiable/N/A.
    if _ja_expected_is_open(raw):
        out["type"] = "open"
        out["display"] = raw
    return out


def _ja_expected_salary_range(expected_raw, current_value=None):
    """Compatibility wrapper backed by the canonical expected calculation."""
    item = _ja_build_expected_canonical(expected_raw, current_value)
    if item.get("writeToProfile") and item.get("minAmount") is not None:
        return {"min": int(item["minAmount"]), "max": int(item.get("maxAmount", item["minAmount"]))}
    return None


def _ja_existing_current_salary(candidate):
    try:
        salary = candidate.get("employment", {}).get("current", {}).get("salary", {})
        rate = salary.get("rate")
        return _ja_round_currency(rate) if rate is not None else None
    except Exception:
        return None

def _ja_valid_iso_date(year, month, day):
    try:
        return date(int(year), int(month), int(day)).isoformat()
    except Exception:
        return None


def _ja_bool_setting(value, default=True):
    if value is None:
        return bool(default)
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() not in ("0", "false", "off", "no", "disabled")


def _ja_edit_distance_limited(a, b, max_distance):
    a, b = str(a or ""), str(b or "")
    if abs(len(a) - len(b)) > max_distance:
        return max_distance + 1
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        current = [i]
        row_min = i
        for j, cb in enumerate(b, 1):
            cost = 0 if ca == cb else 1
            value = min(current[j - 1] + 1, previous[j] + 1, previous[j - 1] + cost)
            if i > 1 and j > 1 and ca == b[j - 2] and a[i - 2] == cb:
                value = min(value, previous[j - 2] + 1)
            current.append(value)
            row_min = min(row_min, value)
        if row_min > max_distance:
            return max_distance + 1
        previous = current
    return previous[-1]


