_JA_RECRUITMENT_FUZZY_TERMS = (
    "allowance", "contract", "contractual", "permanent", "expatriate", "nationality", "sponsorship", "citizenship",
    "relocation", "employment", "guaranteed", "negotiable", "availability", "environment", "experience",
    "communication", "presentability", "candidate", "residential",
)
_JA_RECRUITMENT_PROTECTED_WORDS = {
    "allowance", "allowances", "contract", "contracts", "contracted", "contracting", "contractor", "contractors",
    "contractual", "contractually", "permanent", "permanently", "expatriate", "expatriates", "local", "locals",
    "nationality", "nationalities", "sponsorship", "sponsorships", "sponsor", "sponsored", "sponsoring",
    "citizenship", "citizenships", "citizen", "citizens", "relocation", "relocate", "relocated", "relocating",
    "employment", "employed", "employer", "employers", "employee", "employees", "salary", "salaries", "bonus", "bonuses",
    "guaranteed", "guarantee", "guarantees", "negotiable", "availability", "available", "environment", "environments",
    "experience", "experienced", "experiences", "communication", "communications", "presentability", "candidate", "candidates",
    "residential", "residence", "visa", "visas", "permit", "permits", "status", "remote", "hybrid", "onsite",
}

def _ja_case_like(original, corrected):
    original = str(original or "")
    corrected = str(corrected or "")
    if original and original == original.upper():
        return corrected.upper()
    if re.fullmatch(r"[A-Z][a-z]+", original):
        return corrected[:1].upper() + corrected[1:]
    return corrected

def _ja_recruitment_typo_target(token, allow_fuzzy=True):
    lower = str(token or "").lower()
    if not lower or lower in _JA_RECRUITMENT_PROTECTED_WORDS:
        return ""
    explicit = _JA_RECRUITMENT_TYPO_ALIASES.get(lower)
    if explicit:
        return explicit
    if not allow_fuzzy or len(lower) < 8:
        return ""
    best = None
    for target in _JA_RECRUITMENT_FUZZY_TERMS:
        if lower[0] != target[0] or lower[-1] != target[-1] or abs(len(lower) - len(target)) > 2:
            continue
        allowed = 2 if max(len(lower), len(target)) >= 11 else 1
        distance = _ja_edit_distance_limited(lower, target, allowed)
        if distance <= allowed and distance / max(len(lower), len(target)) <= 0.20:
            if best is None or distance < best[1]:
                best = (target, distance)
    return best[0] if best else ""

def _ja_correct_recruitment_typos(raw_text, enabled=True, allow_fuzzy=True, with_changes=False):
    text = str(raw_text or "")
    if not text or not enabled:
        return (text, []) if with_changes else text
    changes = []
    def replace_token(match):
        token = match.group(0)
        target = _ja_recruitment_typo_target(token, allow_fuzzy=allow_fuzzy)
        if not target or target.lower() == token.lower():
            return token
        replacement = _ja_case_like(token, target)
        if len(changes) < 12:
            changes.append("{} -> {}".format(token, replacement))
        return replacement
    corrected = re.sub(r"[A-Za-z]+", replace_token, text)
    return (corrected, changes) if with_changes else corrected

def _ja_correct_screening_field_typos(fields, enabled=True):
    fields = dict(fields or {})
    if not enabled:
        return fields
    field_rules = {
        "brief_overview": False,
        "reason_leaving": True,
        "looking_for": True,
        "current_salary_breakdown": True,
        "expected_salary": True,
        "notice_period": True,
        "leads": True,
        "remarks": True,
        "role": True,
        "location": True,
        "red_flags": True,
        "next_steps": True,
        "raw_presentability": True,
    }
    for key, allow_fuzzy in field_rules.items():
        fields[key] = _ja_correct_recruitment_typos(fields.get(key, ""), enabled=True, allow_fuzzy=allow_fuzzy)
    return fields

def _ja_correct_notice_typos(raw_text, enabled=True):
    text = str(raw_text or "").strip()
    if not text or not enabled:
        return text
    if re.search(r"\b20\d{2}[-/]\d{1,2}[-/]\d{1,2}\b", text) or re.search(r"\b\d{1,2}[/-]\d{1,2}[/-]20\d{2}\b", text):
        return text
    immediate_aliases = {
        "imm", "immed", "imdt", "immdiate", "immedaite", "imediate", "immediatey",
        "immediatly", "immediatley", "immediatelly", "immidiately", "immidiate",
    }
    month_aliases = {
        "monht": "month", "monhts": "months", "monhth": "month", "monhths": "months",
        "moth": "month", "moths": "months", "mothn": "month", "mothns": "months",
        "monnth": "month", "monnths": "months", "monthh": "month", "monthhs": "months",
    }
    week_aliases = {"wek": "week", "weks": "weeks", "weeek": "week", "weeeks": "weeks"}
    day_aliases = {"daay": "day", "daays": "days", "dayz": "days"}
    found_immediate = False

    def fix_token(match):
        nonlocal found_immediate
        token = match.group(0).lower()
        if token in ("immediate", "immediately") or token in immediate_aliases:
            found_immediate = True
            return "immediate"
        if 7 <= len(token) <= 12 and (
            _ja_edit_distance_limited(token, "immediate", 2) <= 2
            or _ja_edit_distance_limited(token, "immediately", 2) <= 2
        ):
            found_immediate = True
            return "immediate"
        if token in month_aliases:
            return month_aliases[token]
        if token in week_aliases:
            return week_aliases[token]
        if token in day_aliases:
            return day_aliases[token]
        return match.group(0)

    corrected = re.sub(r"[A-Za-z]+", fix_token, text)
    corrected = re.sub(r"\s+", " ", corrected).strip()
    if found_immediate or re.search(r"\b(?:available|availble|avalable)\s+now\b", corrected, re.I):
        return "Immediate"
    if re.fullmatch(r"(?:0|none|nil|n/a)", corrected, re.I):
        return "Immediate"
    word_numbers = {"one": 1, "a": 1, "an": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6}
    m = re.fullmatch(r"(one|a|an|two|three|four|five|six)\s*(day|days|week|weeks|month|months)", corrected, re.I)
    if m:
        corrected = "{} {}".format(word_numbers[m.group(1).lower()], m.group(2).lower())
    m = re.fullmatch(r"(\d+)\s*(day|days|week|weeks|month|months)", corrected, re.I)
    if m:
        number = int(m.group(1))
        unit = m.group(2).lower()
        singular = "month" if unit.startswith("month") else "week" if unit.startswith("week") else "day"
        return "{} {}{}".format(number, singular, "" if number == 1 else "s")
    if re.fullmatch(r"\d+", corrected):
        number = int(corrected)
        if number == 0:
            return "Immediate"
        if 1 <= number <= 12:
            return "{} month{}".format(number, "" if number == 1 else "s")
    return corrected


def _ja_notice_availability(raw, spelling_correction=True):
    original_raw_text = str(raw or "").strip()
    raw_text = _ja_correct_notice_typos(original_raw_text, enabled=bool(spelling_correction))
    if not raw_text:
        return None, {"ok": True, "skipped": True, "reason": "No notice period value"}

    raw_lower = raw_text.lower().strip()

    # Specific availability dates must be parsed before normalising hyphens,
    # otherwise an ISO date such as 2026-08-15 is destroyed into plain words.
    m = re.search(r"\b(20\d{2})[-/](\d{1,2})[-/](\d{1,2})\b", raw_lower)
    if m:
        iso = _ja_valid_iso_date(m.group(1), m.group(2), m.group(3))
        if iso:
            return {"date": iso}, {"ok": True, "raw": raw_text, "matched": iso, "payload": {"date": iso}}
        return None, {"ok": False, "raw": raw_text, "reason": "Invalid calendar date"}
    m = re.search(r"\b(\d{1,2})[/-](\d{1,2})[/-](20\d{2})\b", raw_lower)
    if m:
        iso = _ja_valid_iso_date(m.group(3), m.group(2), m.group(1))
        if iso:
            return {"date": iso}, {"ok": True, "raw": raw_text, "matched": iso, "payload": {"date": iso}}
        return None, {"ok": False, "raw": raw_text, "reason": "Invalid calendar date"}

    month_map = {
        "jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3,
        "apr": 4, "april": 4, "may": 5, "jun": 6, "june": 6, "jul": 7, "july": 7,
        "aug": 8, "august": 8, "sep": 9, "sept": 9, "september": 9,
        "oct": 10, "october": 10, "nov": 11, "november": 11, "dec": 12, "december": 12,
    }
    date_match = re.search(
        r"\b(\d{1,2})\s+(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)(?:\s*,?\s*(20\d{2}))?\b",
        raw_lower,
        re.I,
    )
    if not date_match:
        date_match = re.search(
            r"\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+(\d{1,2})(?:\s*,?\s*(20\d{2}))?\b",
            raw_lower,
            re.I,
        )
        if date_match:
            month_name, day_text, year_text = date_match.group(1), date_match.group(2), date_match.group(3)
        else:
            month_name = day_text = year_text = None
    else:
        day_text, month_name, year_text = date_match.group(1), date_match.group(2), date_match.group(3)
    if date_match and month_name and day_text:
        month_key = month_name.lower()
        month = month_map.get(month_key) or month_map.get(month_key[:3])
        day = int(day_text)
        today = date.today()
        year = int(year_text) if year_text else today.year
        try:
            candidate_date = date(year, month, day)
            if not year_text and candidate_date < today:
                candidate_date = date(year + 1, month, day)
            iso = candidate_date.isoformat()
            return {"date": iso}, {"ok": True, "raw": raw_text, "matched": iso, "payload": {"date": iso}}
        except Exception:
            pass

    lower = raw_lower.replace("–", " ").replace("—", " ").replace("-", " ")
    word_map = {"one":"1", "a":"1", "an":"1", "two":"2", "three":"3", "four":"4", "five":"5", "six":"6"}
    for word, number in word_map.items():
        lower = re.sub(r"\b" + re.escape(word) + r"\b", number, lower)
    # Standard recruiter abbreviations remain supported even when optional
    # typo correction is off. Obvious misspellings are corrected only when the
    # OneNote setting is enabled.
    lower = re.sub(r"(?<![a-z])(?:mnth|mnths|mth|mths|mthhs|mos|mo)(?![a-z])", "month", lower)
    lower = re.sub(r"(?<![a-z])(?:wk|wks)(?![a-z])", "week", lower)
    lower = re.sub(r"\s+", " ", lower).strip()
    if "immediate" in lower or "immediately" in lower or "available now" in lower or lower in ("0", "none"):
        return {"immediate": True}, {"ok": True, "raw": raw_text, "matched": "Immediate", "payload": {"immediate": True}}
    # Parse the complete numeric token, including decimals. The prior integer-only
    # search could start after the decimal point, so "1.5 months" became
    # "5 Months". Decimal handling is now explicit and never partial:
    #   1.5 months -> 1 Month; 2.5 -> 2 Months; 3.5 -> 3 Months;
    #   0.5 month  -> 2 Weeks.
    m = re.search(r"(?<![\d.])(\d+(?:\.\d+)?)\s*(day|days|week|weeks|month|months)\b", lower)
    if m:
        amount = Decimal(m.group(1))
        raw_unit = m.group(2).lower()
        normalization = None
        if amount <= 0:
            payload = {"immediate": True}
            return payload, {"ok": True, "raw": raw_text, "matched": "Immediate", "payload": payload}

        if raw_unit.startswith("month"):
            whole_months = int(amount)
            if whole_months >= 1:
                period, unit = whole_months, "Month"
                if amount != Decimal(whole_months):
                    normalization = {
                        "rule": "truncate_fractional_month_to_whole_month",
                        "input": str(amount),
                        "output": "%s Month%s" % (period, "s" if period != 1 else ""),
                    }
            else:
                # JobAdder availability accepts whole relative units. For a
                # sub-one-month value, convert the fraction to four-week months.
                # This preserves the user's required 0.5 month -> 2 weeks rule.
                period = max(1, int((amount * Decimal(4)).to_integral_value(rounding=ROUND_HALF_UP)))
                unit = "Week"
                normalization = {
                    "rule": "fractional_month_below_one_to_weeks",
                    "input": str(amount),
                    "output": "%s Week%s" % (period, "s" if period != 1 else ""),
                }
        elif raw_unit.startswith("week"):
            period = int(amount)
            if period <= 0:
                period = 1
            unit = "Week"
            if amount != Decimal(int(amount)):
                normalization = {
                    "rule": "truncate_fractional_week_to_whole_week",
                    "input": str(amount),
                    "output": "%s Week%s" % (period, "s" if period != 1 else ""),
                }
            if period > 4:
                original_period = period
                period, unit = (period + 3) // 4, "Month"
                normalization = normalization or {
                    "rule": "weeks_over_four_to_months",
                    "input": "%s weeks" % original_period,
                    "output": "%s Month%s" % (period, "s" if period != 1 else ""),
                }
        else:
            days = int(amount)
            if days <= 0:
                days = 1
            if amount != Decimal(int(amount)):
                normalization = {
                    "rule": "truncate_fractional_day_to_whole_day",
                    "input": str(amount),
                    "output": "%s day%s" % (days, "s" if days != 1 else ""),
                }
            if days <= 21:
                period, unit = max(1, (days + 6) // 7), "Week"
            else:
                period, unit = max(1, (days + 29) // 30), "Month"

        payload = {"relative": {"period": period, "unit": unit}}
        meta = {"ok": True, "raw": raw_text, "matched": "%s %s%s" % (period, unit, "s" if period != 1 else ""), "payload": payload}
        if normalization:
            meta["normalization"] = normalization
        return payload, meta
    return None, {"ok": False, "raw": raw_text, "reason": "Could not match notice period"}


def _ja_add_months_iso(start_date, months):
    months = int(months)
    month_index = start_date.month - 1 + months
    year = start_date.year + month_index // 12
    month = month_index % 12 + 1
    day = min(start_date.day, calendar.monthrange(year, month)[1])
    return date(year, month, day).isoformat()


def _ja_notice_spa_payload(availability):
    if not isinstance(availability, dict):
        return None
    if availability.get("immediate"):
        return {"type": "Immediate", "date": None}
    if availability.get("date"):
        # Preserve the date in the canonical object. The normal OAuth update uses
        # the official {date} model. The emergency SPA route may vary by tenant,
        # so no guessed type is sent for date-only availability.
        return None
    rel = availability.get("relative")
    if isinstance(rel, dict):
        period = int(rel.get("period") or 0)
        unit = str(rel.get("unit") or "")
        if period > 0 and unit == "Week":
            return {"type": "In{}Week{}".format(period, "" if period == 1 else "s"), "date": (date.today() + timedelta(days=period * 7)).isoformat()}
        if period > 0 and unit == "Month":
            return {"type": "In{}Month{}".format(period, "" if period == 1 else "s"), "date": _ja_add_months_iso(date.today(), period)}
    return None



_SALARY_AI_CACHE_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "runtime", "salary_ai_component_cache.json")
_SALARY_AI_CACHE_LOCK = threading.Lock()


def _ja_salary_ai_cache_load():
    legacy, fingerprint = _cvstudio_legacy_json_read(_SALARY_AI_CACHE_PATH, dict)
    try:
        if legacy is not None:
            _CVSTUDIO_SALARY_REPOSITORY.import_legacy(legacy, fingerprint)
        return _CVSTUDIO_SALARY_REPOSITORY.load()
    except StorageError:
        raise
    except Exception:
        return legacy if isinstance(legacy, dict) else {}


def _ja_salary_ai_cache_get(cache_key):
    with _SALARY_AI_CACHE_LOCK:
        item = _ja_salary_ai_cache_load().get(str(cache_key or ""))
    return item if isinstance(item, dict) else None


def _ja_salary_ai_cache_put(cache_key, components, provider, model):
    if not cache_key or not isinstance(components, dict):
        return
    with _SALARY_AI_CACHE_LOCK:
        data = _ja_salary_ai_cache_load()
        data[str(cache_key)] = {
            "components": components,
            "provider": provider,
            "model": model,
            "savedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
        }
        # keep newest 500 entries by insertion order
        if len(data) > 500:
            data = dict(list(data.items())[-500:])
        _CVSTUDIO_SALARY_REPOSITORY.save(data)
        try:
            _cvstudio_legacy_json_write(_SALARY_AI_CACHE_PATH, data, indent=2)
        except Exception:
            # SQLite is authoritative; keep the existing legacy file untouched
            # if this compatibility mirror cannot be updated.
            pass


def _ja_salary_ai_num(value, minimum=0, maximum=1000000000):
    try:
        if value is None or isinstance(value, bool):
            return None
        number = Decimal(str(value))
        if number < Decimal(str(minimum)) or number > Decimal(str(maximum)):
            return None
        return float(number) if number != number.to_integral_value() else int(number)
    except Exception:
        return None


def _ja_salary_ai_sanitize(obj):
    if not isinstance(obj, dict):
        return None
    cur = obj.get("current") if isinstance(obj.get("current"), dict) else {}
    exp = obj.get("expected") if isinstance(obj.get("expected"), dict) else {}
    allowed = set(_JA_CURRENCY_OPTIONS)
    current_currency = str(cur.get("currency") or obj.get("currentCurrency") or "").strip().upper()
    expected_currency = str(exp.get("currency") or obj.get("expectedCurrency") or "").strip().upper()
    # Ignore legacy top-level currency output. It cannot prove which salary
    # field supplied the clue and could violate the strict field-scope rule.
    if current_currency not in allowed: current_currency = None
    if expected_currency not in allowed: expected_currency = None
    base = _ja_salary_ai_num(cur.get("baseMonthly"), 1)
    months = _ja_salary_ai_num(cur.get("guaranteedSalaryMonths"), 12, 36)
    allowance = _ja_salary_ai_num(cur.get("fixedMonthlyAllowance"), 0) or 0
    other = _ja_salary_ai_num(cur.get("otherFixedMonthlyCash"), 0) or 0
    # Employer EPF/KWSP is excluded from this workflow unless a future explicit
    # opt-in setting is added. Never let AI silently include it as monthly cash.
    epf = 0
    expected = {
        "currency": expected_currency,
        "explicitAmount": _ja_salary_ai_num(exp.get("explicitAmount"), 1),
        "explicitMin": _ja_salary_ai_num(exp.get("explicitMin"), 1),
        "explicitMax": _ja_salary_ai_num(exp.get("explicitMax"), 1),
        "sameAsCurrent": bool(exp.get("sameAsCurrent")),
        "percent": _ja_salary_ai_num(exp.get("percent"), 0, 500),
        "percentMin": _ja_salary_ai_num(exp.get("percentMin"), 0, 500),
        "percentMax": _ja_salary_ai_num(exp.get("percentMax"), 0, 500),
        "open": bool(exp.get("open")),
        "confidence": str(exp.get("confidence") or "").lower()[:12],
    }
    current = {
        "currency": current_currency,
        "baseMonthly": base,
        "guaranteedSalaryMonths": months,
        "fixedMonthlyAllowance": allowance,
        "otherFixedMonthlyCash": other,
        "includedEmployerEpf": epf,
        "excludedComponents": [],
        "evidence": [],
        "confidence": str(cur.get("confidence") or "").lower()[:12],
    }
    if base is None and not any(v is not None for v in (expected["explicitAmount"], expected["explicitMin"], expected["percent"], expected["percentMin"])) and not expected["sameAsCurrent"] and not expected["open"] and not current_currency and not expected_currency:
        return None
    selected = expected_currency or current_currency
    return {
        "currency": selected,
        "currentCurrency": current_currency,
        "expectedCurrency": expected_currency,
        "current": current,
        "expected": expected,
    }



def _ja_salary_usage_int(usage, *keys):
    for key in keys:
        try:
            if (usage or {}).get(key) is not None:
                return int((usage or {}).get(key) or 0)
        except Exception:
            pass
    return 0


def _ja_salary_cost_details(model, usage, provider):
    return _llm_cost_details(model, usage, provider)


def _ja_salary_cost_provenance(cost, paid_call_status):
    cost = cost if isinstance(cost, dict) else {}
    output = {
        "paidCallStatus": str(paid_call_status or ""),
        "estimatedCostUsd": cost.get("estimated_cost_usd"),
        "costValueType": str(cost.get("cost_value_type") or "local_estimate"),
        "costAuthority": str(cost.get("cost_authority") or "local_rate_table"),
        "usageAuthority": str(cost.get("usage_authority") or "not_returned"),
        "providerBillingStatus": str(
            cost.get("provider_billing_status") or "unavailable"
        ),
        "providerAuthoritativeCostUsd": cost.get(
            "provider_authoritative_cost_usd"
        ),
        "providerAuthoritativeCostUsdText": cost.get(
            "provider_authoritative_cost_usd_text"
        ),
        "providerAuthoritativeCost": cost.get(
            "provider_authoritative_cost"
        ),
        "providerAuthoritativeCostText": cost.get(
            "provider_authoritative_cost_text"
        ),
        "providerAuthoritativeCostCurrency": cost.get(
            "provider_authoritative_cost_currency"
        ),
        "providerBillingCurrency": cost.get("provider_billing_currency"),
        "providerBillingSource": cost.get("provider_billing_source"),
        "reconciliationStatus": str(
            cost.get("reconciliation_status")
            or "provider_billing_unavailable"
        ),
        "reconciliationDifferenceUsd": cost.get(
            "reconciliation_difference_usd"
        ),
        "billingDataMissing": bool(cost.get("billing_data_missing", True)),
        "billingDataInvalid": bool(cost.get("billing_data_invalid", False)),
        "estimateStatus": str(cost.get("estimate_status") or ""),
        "usageValidationStatus": str(
            cost.get("usage_validation_status") or ""
        ),
        "usageValidationReason": str(
            cost.get("usage_validation_reason") or ""
        ),
        "guardrailEnabled": bool(cost.get("guardrail_enabled")),
        "guardrailLimitUsd": cost.get("guardrail_limit_usd"),
        "guardrailStatus": str(cost.get("guardrail_status") or ""),
    }
    if str(paid_call_status or "").startswith("not_called"):
        output.update({
            "providerBillingStatus": "not_applicable",
            "reconciliationStatus": "not_called",
            "billingDataMissing": False,
        })
    return output


def _ja_salary_llm_text(data):
    out = []
    for block in (data or {}).get("content") or []:
        if isinstance(block, dict) and block.get("type") in ("text", "output_text"):
            out.append(str(block.get("text") or ""))
        elif isinstance(block, str):
            out.append(block)
    return "".join(out).strip()


def _ja_salary_ai_extract(fields, config=None):
    config = config if isinstance(config, dict) else {}
    enabled = bool(config.get("enabled"))
    provider = str(config.get("provider") or "deepseek").strip().lower()
    if provider == "claude": provider = "anthropic"
    if provider == "gpt": provider = "openai"
    model = str(config.get("model") or ("deepseek-v4-flash" if provider == "deepseek" else "")).strip()
    api_key = str(config.get("api_key") or "").strip()
    # Privacy/scope boundary: only the two salary fields are sent. Summary,
    # RFL, Looking For, Remarks, Leads, Presentability, notice and full note text
    # are never included in this AI request.
    raw = {
        "currentSalaryBreakdown": _onenote_clean_field_value((fields or {}).get("current_salary_breakdown", "")),
        "expectedSalary": _onenote_clean_field_value((fields or {}).get("expected_salary", "")),
    }
    base_processing = {
        "fieldExtraction": "local_label_parser",
        "salaryCalculation": "deterministic_code",
        "aiAttempted": False,
        "aiUsed": False,
        "aiApiCalled": False,
        "cacheHit": False,
        "provider": "none",
        "model": "none",
        "inputTokens": 0,
        "outputTokens": 0,
        "costUsd": 0.0,
        "costReason": "Local deterministic salary parser used; no AI API call.",
    }
    base_processing.update(
        _ja_salary_cost_provenance(
            _ja_salary_cost_details("none", {}, "none"),
            "not_called",
        )
    )
    if not enabled or not any(raw.values()):
        return None, base_processing
    cache_key = hashlib.sha256(json.dumps({"v":"salary-ai-v4-typo-tolerant","provider":provider,"model":model,"raw":raw}, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
    cached = _ja_salary_ai_cache_get(cache_key)
    cached_components = _ja_salary_ai_sanitize(cached.get("components")) if isinstance(cached, dict) else None
    if cached_components:
        cached_processing = {
            "fieldExtraction": "ai_component_extraction_cache",
            "salaryCalculation": "deterministic_code",
            "aiAttempted": True,
            "aiUsed": True,
            "aiApiCalled": False,
            "cacheHit": True,
            "cacheKey": cache_key[:20],
            "provider": str(cached.get("provider") or provider),
            "model": str(cached.get("model") or model),
            "inputTokens": 0,
            "outputTokens": 0,
            "costUsd": 0.0,
            "costReason": "Reused cached AI-extracted components; no new token charge. Deterministic code calculated final values.",
        }
        cached_processing.update(
            _ja_salary_cost_provenance(
                _ja_salary_cost_details(
                    str(cached.get("model") or model),
                    {},
                    str(cached.get("provider") or provider),
                ),
                "not_called_cache_hit",
            )
        )
        return cached_components, cached_processing
    if not api_key:
        p=dict(base_processing)
        p.update({"aiAttempted": False, "fallbackReason": "AI salary assist enabled but no saved API key was available.", "costReason": "No AI call; local deterministic fallback."})
        return None, p
    system = """You extract salary and currency components from exactly two recruiter fields: currentSalaryBreakdown and expectedSalary. Return JSON only. Never calculate final current salary, expected salary, or JobAdder values. Never infer an unstated amount or currency. Detect current.currency only from currentSalaryBreakdown. Detect expected.currency only from expectedSalary. Do not copy current currency into expected when expected does not state one. No Summary, RFL, Looking For, Remarks, Leads, Presentability, notice text or full screening note is provided; never infer from those sections. Normalize currency aliases to one of these exact ISO codes only: BND, KHR, IDR, LAK, MYR, MMK, PHP, SGD, THB, VND, CNY, HKD, AUD, EUR, USD, INR. Examples: RM/MYR/ringgit=MYR; Rp/rupiah=IDR; S$/SGD=SGD; US$/USD=USD; Rs/₹/rupee=INR; RMB/yuan/renminbi=CNY; HK$/HKD=HKD; A$/AUD=AUD; euro/€=EUR; peso/₱=PHP; baht/฿=THB; dong/đồng/₫=VND. AWS means a 13-month total package. Wording such as 13.5th bonus, 13.5 months, or x13.5 means total guaranteedSalaryMonths=13.5, not an additional 13.5 months. A phrase such as 2 months contractual/guaranteed/fixed bonus means total 14 months unless the text already states a higher total package. A plain 2 months bonus without contractual/guaranteed/fixed wording is variable and excluded. EPF/KWSP, SOCSO, EIS and employer contributions are always excluded from the JobAdder monthly current salary. Commission, variable/performance/discretionary bonus, claims, reimbursements and stock are excluded. Only a separately stated fixed recurring cash allowance may be included. Recruiter spelling is noisy: interpret obvious salary-field typos such as allwan/alwan/alwance/alowance as allowance; mth/mths/mnth/moth/monnth as month/months; bonous/bouns as bonus; efp as EPF; precent/persent as percent; and rngint/rnggit/ringit as Malaysian Ringgit (MYR). Currency may appear before or after the amount with no space, for example RM2000, 2000RM, MYR10k, 10kMYR, or 2000rngint. A separate additive amount such as +500 may be fixed monthly cash. Fixed expected amount/range has priority over percentage. Output this exact object shape with nulls when unknown: {"current":{"currency":null,"baseMonthly":null,"guaranteedSalaryMonths":null,"fixedMonthlyAllowance":0,"otherFixedMonthlyCash":0,"includedEmployerEpf":0,"excludedComponents":[],"evidence":[],"confidence":"high|medium|low"},"expected":{"currency":null,"explicitAmount":null,"explicitMin":null,"explicitMax":null,"sameAsCurrent":false,"percent":null,"percentMin":null,"percentMax":null,"open":false,"confidence":"high|medium|low"}}"""
    payload = {
        "model": model,
        "max_tokens": 900,
        "temperature": 0,
        "system": system,
        "messages": [{"role":"user","content":json.dumps(raw, ensure_ascii=False)}],
        "_timeout_seconds": 90,
    }
    usage = {}
    api_called = False
    try:
        data = call_llm(provider, api_key, payload)
        api_called = True
        usage = (data or {}).get("usage") or {}
        obj = _lead_extract_json(_ja_salary_llm_text(data))
        components = _ja_salary_ai_sanitize(obj)
        if not components:
            raise ValueError("AI response did not contain usable salary components")
        cost = _ja_salary_cost_details(model, usage, provider)
        _ja_salary_ai_cache_put(cache_key, components, provider, model)
        processing = {
            "fieldExtraction": "ai_component_extraction",
            "salaryCalculation": "deterministic_code",
            "aiAttempted": True,
            "aiUsed": True,
            "aiApiCalled": True,
            "cacheHit": False,
            "cacheKey": cache_key[:20],
            "provider": provider,
            "model": model,
            "inputTokens": int(cost.get("input_tokens") or 0),
            "outputTokens": int(cost.get("output_tokens") or 0),
            "totalTokens": int(cost.get("total_tokens") or 0),
            "apiCalls": int(cost.get("api_calls") or 0),
            "promptCacheHitTokens": int(cost.get("prompt_cache_hit_tokens") or 0),
            "promptCacheMissTokens": int(cost.get("prompt_cache_miss_tokens") or 0),
            "costUsd": float(cost.get("usd") or 0.0),
            "pricingKnown": bool(cost.get("pricing_known")),
            "pricingModelKey": cost.get("pricing_model_key"),
            "costMethod": cost.get("cost_method"),
            "costReason": "AI extracted components only; deterministic code calculated final salary values.",
        }
        processing.update(
            _ja_salary_cost_provenance(cost, "provider_response_received")
        )
        return components, processing
    except Exception as e:
        p = dict(base_processing)
        cost = _ja_salary_cost_details(model, usage, provider)
        if not api_called:
            cost = dict(cost)
            cost.update({
                "pricing_known": False,
                "pricing_model_key": None,
                "cost_method": "no_api_response",
            })
        failure = _llm_paid_failure_fields(
            e,
            model,
            provider,
            usage,
            attempted=True,
        )
        p.update({
            "aiAttempted": True,
            "aiUsed": False,
            "aiApiCalled": bool(api_called),
            "provider": provider,
            "model": model or "none",
            "inputTokens": int(cost.get("input_tokens") or 0),
            "outputTokens": int(cost.get("output_tokens") or 0),
            "totalTokens": int(cost.get("total_tokens") or 0),
            "apiCalls": int(cost.get("api_calls") or 0),
            "promptCacheHitTokens": int(cost.get("prompt_cache_hit_tokens") or 0),
            "promptCacheMissTokens": int(cost.get("prompt_cache_miss_tokens") or 0),
            "costUsd": float(cost.get("usd") or 0.0),
            "pricingKnown": bool(cost.get("pricing_known")),
            "pricingModelKey": cost.get("pricing_model_key"),
            "costMethod": cost.get("cost_method"),
            "fallbackReason": str(e)[:500],
            "costReason": "AI API returned no usable components; returned token usage/cost was still recorded before local deterministic fallback." if api_called else "AI extraction failed before an API response; local deterministic fallback used.",
        })
        p.update(
            _ja_salary_cost_provenance(
                cost,
                failure.get("paid_call_status"),
            )
        )
        p["billingReconciliation"] = failure.get("billing_reconciliation")
        return None, p


def _ja_ai_number_matches_token(value, tokens, tolerance=1):
    if value is None:
        return False
    return any(abs(float(token.get("value") or 0) - float(value)) <= tolerance for token in tokens)


def _ja_validate_ai_current_components(ai_components, current_raw):
    cur = (ai_components or {}).get("current") if isinstance((ai_components or {}).get("current"), dict) else {}
    if not cur or cur.get("baseMonthly") is None:
        return False, "AI did not provide a usable current base salary."
    base = float(cur.get("baseMonthly"))
    months = float(cur.get("guaranteedSalaryMonths") or 12)
    additions = sum(float(cur.get(key) or 0) for key in ("fixedMonthlyAllowance", "otherFixedMonthlyCash", "includedEmployerEpf"))
    tokens = _ja_salary_amount_tokens(current_raw)
    confidence = str(cur.get("confidence") or "").lower()
    if tokens and not _ja_ai_number_matches_token(base, tokens):
        return False, "AI base salary conflicted with explicit numeric salary evidence."
    if not tokens and confidence not in ("high", "medium"):
        return False, "AI current salary had no explicit numeric evidence and insufficient confidence."
    month_info = _ja_extract_guaranteed_salary_months(current_raw)
    if month_info.get("evidence"):
        if abs(float(month_info.get("guaranteedSalaryMonths") or 12) - months) > 0.001:
            return False, "AI guaranteed salary months conflicted with explicit month/AWS evidence."
    elif abs(months - 12.0) > 0.001:
        return False, "AI introduced guaranteed salary months without evidence in Current Salary Breakdown."
    if additions < 0 or additions > max(base * 5, 10000000):
        return False, "AI fixed cash additions were outside conservative salary bounds."
    if tokens:
        remaining = list(tokens)
        for i, token in enumerate(remaining):
            if abs(float(token.get("value") or 0) - base) <= 1:
                remaining.pop(i)
                break
        explicit_addition_ceiling = sum(float(token.get("value") or 0) for token in remaining)
        if additions > explicit_addition_ceiling + 1:
            return False, "AI fixed cash additions exceeded explicit salary amounts in the field."
    return True, None


def _ja_validate_ai_expected_components(ai_components, expected_raw, local_expected):
    exp = (ai_components or {}).get("expected") if isinstance((ai_components or {}).get("expected"), dict) else {}
    if not exp:
        return False, "AI did not provide usable expected salary components."
    # Explicit deterministic parsing always wins where it can identify amount,
    # range, same-as-current, percentage or open/negotiable intent.
    if (local_expected or {}).get("type") not in (None, "blank", "unparsed"):
        return False, "Deterministic Expected Salary evidence was authoritative."
    tokens = _ja_salary_amount_tokens(expected_raw)
    amounts = [exp.get("explicitAmount"), exp.get("explicitMin"), exp.get("explicitMax")]
    for amount in [x for x in amounts if x is not None]:
        if tokens and not _ja_ai_number_matches_token(amount, tokens):
            return False, "AI expected amount conflicted with explicit numeric salary evidence."
    confidence = str(exp.get("confidence") or "").lower()
    has_value = any(x is not None for x in amounts + [exp.get("percent"), exp.get("percentMin"), exp.get("percentMax")]) or exp.get("sameAsCurrent") or exp.get("open")
    if not has_value:
        return False, "AI did not identify an expected salary intent."
    if not tokens and confidence not in ("high", "medium") and not exp.get("sameAsCurrent") and not exp.get("open"):
        return False, "AI expected salary had no explicit numeric evidence and insufficient confidence."
    return True, None


def _ja_current_from_ai_components(ai_components, raw, currency):
    cur = (ai_components or {}).get("current") if isinstance((ai_components or {}).get("current"), dict) else {}
    base = cur.get("baseMonthly")
    if base is None:
        return None
    months = cur.get("guaranteedSalaryMonths") or 12
    allowance = int(cur.get("fixedMonthlyAllowance") or 0)
    other = int(cur.get("otherFixedMonthlyCash") or 0)
    epf = int(cur.get("includedEmployerEpf") or 0)
    adjusted = _ja_round_currency(Decimal(str(base)) * Decimal(str(months)) / Decimal(12))
    value = _ja_round_currency(Decimal(str(base)) * Decimal(str(months)) / Decimal(12) + Decimal(allowance + other + epf))
    return {
        "value": value,
        "base": int(base),
        "baseMonthly": int(base),
        "guaranteedSalaryMonths": float(months),
        "baseSalaryMonths": float(months),
        "additionalGuaranteedBonusMonths": max(0.0, float(months)-12.0),
        "monthEvidence": list(cur.get("evidence") or []),
        "multiplier": float(months)/12.0,
        "adjustedBase": adjusted,
        "allowances": allowance + other + epf,
        "fixedMonthlyAllowance": allowance,
        "otherFixedMonthlyCash": other,
        "includedEmployerEpf": epf,
        "includedAllowances": list(cur.get("evidence") or []),
        "excluded": list(cur.get("excludedComponents") or []),
        "monthlyEquivalent": value,
        "display": _ja_salary_display(currency, value, equivalent=True),
        "breakdown": str(raw or "").strip(),
        "monthlyRule": "ai_components_then_deterministic_guaranteed_months_plus_fixed_cash",
        "roundingRule": "ROUND_HALF_UP_TO_WHOLE_CURRENCY",
        "componentSource": "ai_component_extraction",
        "extractionConfidence": cur.get("confidence") or "",
    }


def _ja_expected_from_ai_components(ai_components, raw, current_value, currency):
    exp = (ai_components or {}).get("expected") if isinstance((ai_components or {}).get("expected"), dict) else {}
    if not exp or not str(raw or "").strip():
        return None
    out = {"raw":str(raw or "").strip(),"type":"unparsed","monthlyAmount":None,"minAmount":None,"maxAmount":None,"percent":None,"percentMin":None,"percentMax":None,"basisCurrentAmount":None,"display":"","writeToProfile":False,"componentSource":"ai_component_extraction"}
    amount=exp.get("explicitAmount"); lo=exp.get("explicitMin"); hi=exp.get("explicitMax")
    if amount is not None:
        value=_ja_round_currency(amount); out.update({"type":"fixed","monthlyAmount":value,"minAmount":value,"maxAmount":value,"display":_ja_salary_display(currency,value),"writeToProfile":True}); return out
    if lo is not None or hi is not None:
        lo=_ja_round_currency(lo if lo is not None else hi); hi=_ja_round_currency(hi if hi is not None else lo); lo,hi=min(lo,hi),max(lo,hi); out.update({"type":"range" if lo!=hi else "fixed","monthlyAmount":lo if lo==hi else None,"minAmount":lo,"maxAmount":hi,"display":_ja_salary_display(currency,lo,hi),"writeToProfile":True}); return out
    if exp.get("sameAsCurrent"):
        out["type"]="same_as_current" if current_value is not None else "same_as_current_unresolved"
        if current_value is not None:
            value=int(current_value); out.update({"monthlyAmount":value,"minAmount":value,"maxAmount":value,"basisCurrentAmount":value,"display":_ja_salary_display(currency,value),"writeToProfile":True})
        return out
    pmin=exp.get("percentMin"); pmax=exp.get("percentMax"); p=exp.get("percent")
    if p is not None: pmin=pmax=p
    if pmin is not None or pmax is not None:
        pmin=float(pmin if pmin is not None else pmax); pmax=float(pmax if pmax is not None else pmin); pmin,pmax=min(pmin,pmax),max(pmin,pmax)
        out.update({"type":"percent" if pmin==pmax else "percent_range","percent":pmin if pmin==pmax else None,"percentMin":pmin,"percentMax":pmax,"basisCurrentAmount":int(current_value) if current_value is not None else None})
        if current_value is not None:
            lo=_ja_round_currency(Decimal(int(current_value))*(Decimal(1)+Decimal(str(pmin))/Decimal(100))); hi=_ja_round_currency(Decimal(int(current_value))*(Decimal(1)+Decimal(str(pmax))/Decimal(100))); out.update({"monthlyAmount":lo if lo==hi else None,"minAmount":lo,"maxAmount":hi,"display":_ja_salary_display(currency,lo,hi),"writeToProfile":True})
        else: out["type"] += "_unresolved"
        return out
    if exp.get("open"):
        out.update({"type":"open","display":str(raw or "").strip()}); return out
    return None

def _ja_build_salary_notice_canonical(fields, candidate=None, ai_components=None, processing=None, spelling_correction=True):
    """Build the single canonical object used by JobAdder, UI and records."""
    fields = fields or {}
    candidate = candidate if isinstance(candidate, dict) else {}
    current_raw = _onenote_clean_field_value(fields.get("current_salary_breakdown", ""))
    expected_raw = _onenote_clean_field_value(fields.get("expected_salary", ""))
    notice_raw = _onenote_clean_field_value(fields.get("notice_period", ""))
    current_normalized, current_typo_changes = _ja_salary_normalize_recruiter_typos(current_raw, with_changes=True)
    expected_normalized, expected_typo_changes = _ja_salary_normalize_recruiter_typos(expected_raw, with_changes=True)
    currency_selection = _ja_currency_selection(current_raw, expected_raw, candidate, ai_components)
    currency = currency_selection.get("selectedCurrency")
    current_currency = currency_selection.get("currentCurrency") or currency
    expected_currency = currency_selection.get("expectedCurrency") or currency

    local_current_calc = _ja_calc_fixed_salary_detailed(current_raw, currency=current_currency)
    ai_current_ok, ai_current_reason = _ja_validate_ai_current_components(ai_components, current_raw) if ai_components else (False, "No AI components supplied.")
    ai_current_calc = _ja_current_from_ai_components(ai_components, current_raw, current_currency) if ai_components and ai_current_ok else None
    current_calc = ai_current_calc or local_current_calc
    current = {
        "raw": current_raw,
        "currency": current_currency,
        "source": "blank" if not current_raw else "unparsed",
        "baseMonthly": None,
        "fixedMonthlyAllowance": 0,
        "otherFixedMonthlyCash": 0,
        "includedEmployerEpf": 0,
        "guaranteedSalaryMonths": 12.0,
        "monthlyEquivalent": None,
        "display": "",
        "breakdown": current_raw,
        "writeToProfile": False,
    }
    if current_calc and current_calc.get("monthlyEquivalent") is not None:
        current.update(current_calc)
        current["currency"] = current_currency
        current["display"] = _ja_salary_display(current_currency, current.get("monthlyEquivalent"), equivalent=True)
        current["source"] = "ai_component_extraction_validated" if ai_current_calc else "screening_note"
        current["writeToProfile"] = True
    elif current_raw and _ja_salary_has_actual_amount(current_raw):
        fallback = _ja_salary_plain_number(current_raw)
        if fallback:
            current.update({
                "source": "screening_note_plain_amount", "baseMonthly": fallback,
                "monthlyEquivalent": fallback, "display": _ja_salary_display(current_currency, fallback, equivalent=True),
                "writeToProfile": True, "roundingRule": "ROUND_HALF_UP_TO_WHOLE_CURRENCY",
            })

    existing_current = _ja_existing_current_salary(candidate)
    basis_current = current.get("monthlyEquivalent")
    if basis_current is None and existing_current is not None:
        basis_current = int(existing_current)
        current.update({
            "source": "existing_candidate_profile", "monthlyEquivalent": basis_current,
            "display": _ja_salary_display(current_currency, basis_current, equivalent=True),
            "writeToProfile": False,
        })

    local_expected = _ja_build_expected_canonical(expected_raw, basis_current, currency=expected_currency)
    ai_expected_ok, ai_expected_reason = _ja_validate_ai_expected_components(ai_components, expected_raw, local_expected) if ai_components else (False, "No AI components supplied.")
    expected = _ja_expected_from_ai_components(ai_components, expected_raw, basis_current, expected_currency) if ai_components and ai_expected_ok else None
    if expected is None:
        expected = local_expected
    expected["currency"] = expected_currency

    availability, notice_details = _ja_notice_availability(notice_raw, spelling_correction=spelling_correction)
    notice = {
        "raw": notice_raw,
        "display": notice_details.get("matched") or (notice_raw if notice_raw else ""),
        "ok": notice_details.get("ok") is not False,
        "payload": availability,
        "spaPayload": _ja_notice_spa_payload(availability),
        "details": notice_details,
    }

    expected_basis_ok = True
    if expected.get("type", "").startswith("percent") and expected.get("writeToProfile"):
        expected_basis_ok = expected.get("basisCurrentAmount") == current.get("monthlyEquivalent")
        if not expected_basis_ok and current.get("monthlyEquivalent") is not None:
            expected = _ja_build_expected_canonical(expected_raw, current.get("monthlyEquivalent"), currency=expected_currency)
            expected["currency"] = expected_currency
            expected_basis_ok = expected.get("basisCurrentAmount") == current.get("monthlyEquivalent")

    fingerprint_input = {
        "currentRaw": current_raw,
        "expectedRaw": expected_raw,
        "currentCurrency": current_currency,
        "expectedCurrency": expected_currency,
        "selectedCurrency": currency,
        "basisCurrent": current.get("monthlyEquivalent"),
        "canonicalVersion": "salary-v1",
        "aiComponents": ai_components if isinstance(ai_components, dict) else None,
    }
    fingerprint = hashlib.sha256(json.dumps(fingerprint_input, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()[:20]
    proc = dict(processing or {
        "fieldExtraction": "local_label_parser",
        "salaryCalculation": "deterministic_code",
        "aiAttempted": False,
        "aiUsed": False,
        "aiApiCalled": False,
        "cacheHit": False,
        "provider": "none",
        "model": "none",
        "inputTokens": 0,
        "outputTokens": 0,
        "costUsd": 0.0,
        "costReason": "Local deterministic salary parser used; no AI provider call."
    })
    proc.update({
        "currencyDetectionScope": ["current_salary_breakdown", "expected_salary"],
        "currencySelectionRule": currency_selection.get("selectionRule"),
        "selectedCurrency": currency,
        "jobAdderCurrencyOption": currency_selection.get("jobAdderOption"),
        "aiCurrentComponentsApplied": bool(ai_current_calc),
        "aiExpectedComponentsApplied": bool(expected.get("componentSource") == "ai_component_extraction"),
        "aiCurrentValidationReason": ai_current_reason,
        "aiExpectedValidationReason": ai_expected_reason,
        "salaryTypoNormalizationVersion": "salary-typo-v1",
        "salaryTypoNormalizationApplied": bool(current_typo_changes or expected_typo_changes),
        "salaryTypoNormalizationCount": len(current_typo_changes) + len(expected_typo_changes),
    })
    return {
        "canonicalVersion": "salary-v1",
        "currency": currency,
        "currentCurrency": current_currency,
        "expectedCurrency": expected_currency,
        "currencySelection": currency_selection,
        "current": current,
        "expected": expected,
        "notice": notice,
        "normalization": {
            "version": "salary-typo-v1",
            "scope": ["current_salary_breakdown", "expected_salary"],
            "currentNormalizedForParsing": current_normalized,
            "expectedNormalizedForParsing": expected_normalized,
            "currentChanges": current_typo_changes,
            "expectedChanges": expected_typo_changes,
        },
        "processing": proc,
        "validation": {
            "salaryFingerprint": fingerprint,
            "expectedBasisMatchesCurrent": bool(expected_basis_ok),
            "roundingRule": "ROUND_HALF_UP_TO_WHOLE_CURRENCY",
            "noDisplayReparse": True,
            "calculationOwner": "deterministic_code",
            "aiOnlyExtractedComponents": bool(ai_components),
            "aiComponentsEvidenceValidated": True,
            "currencyDetectionLimitedToSalaryFields": True,
            "explicitCurrencyAliasesOverrideConflictingAi": True,
            "expectedCurrencyWinsDropdown": True,
            "salaryTypoNormalizationDeterministic": True,
            "salaryTypoNormalizationScopeLimited": True,
        },
    }


def _ja_submit_employment_from_candidate(candidate):
    """Convert the readable candidate employment model to safe update fields.

    Only current/ideal branches are preserved because they are the branches this
    workflow may update. Employment history is deliberately omitted from the PUT
    so the workflow never rewrites CV-derived job history.
    """
    employment = candidate.get("employment") if isinstance(candidate, dict) else None
    if not isinstance(employment, dict):
        return {}
    out = {}
    current = employment.get("current")
    if isinstance(current, dict):
        c = {}
        for key in ("employer", "position"):
            if current.get(key) not in (None, ""):
                c[key] = current.get(key)
        wt = current.get("workType")
        if isinstance(wt, dict) and wt.get("workTypeId") is not None:
            c["workTypeId"] = wt.get("workTypeId")
        salary = current.get("salary")
        if isinstance(salary, dict):
            s = {k: salary.get(k) for k in ("ratePer", "rate", "currency") if salary.get(k) is not None}
            if s:
                c["salary"] = s
        if c:
            out["current"] = c
    ideal = employment.get("ideal")
    if isinstance(ideal, dict):
        i = {}
        if ideal.get("position") not in (None, ""):
            i["position"] = ideal.get("position")
        wt = ideal.get("workType")
        if isinstance(wt, dict) and wt.get("workTypeId") is not None:
            i["workTypeId"] = wt.get("workTypeId")
        salary = ideal.get("salary")
        if isinstance(salary, dict):
            s = {k: salary.get(k) for k in ("ratePer", "rateLow", "rateHigh", "currency") if salary.get(k) is not None}
            if s:
                i["salary"] = s
        other_out = []
        for other in ideal.get("other") or []:
            if not isinstance(other, dict):
                continue
            o = {}
            wt = other.get("workType")
            if isinstance(wt, dict) and wt.get("workTypeId") is not None:
                o["workTypeId"] = wt.get("workTypeId")
            salary = other.get("salary")
            if isinstance(salary, dict):
                s = {k: salary.get(k) for k in ("ratePer", "rateLow", "rateHigh", "currency") if salary.get(k) is not None}
                if s:
                    o["salary"] = s
            if o:
                other_out.append(o)
        if other_out:
            i["other"] = other_out
        if i:
            out["ideal"] = i
    return out


def _ja_candidate_salary_notice_payload(fields, candidate=None, salary_canonical=None):
    fields = fields or {}
    candidate = candidate if isinstance(candidate, dict) else {}
    canonical = salary_canonical if isinstance(salary_canonical, dict) else _ja_build_salary_notice_canonical(fields, candidate)
    current_item = canonical["current"]
    expected_item = canonical["expected"]
    notice_item = canonical["notice"]
    currency = canonical.get("currency")
    current_currency = canonical.get("currentCurrency") or currency
    expected_currency = canonical.get("expectedCurrency") or currency
    currency_selection = canonical.get("currencySelection") if isinstance(canonical.get("currencySelection"), dict) else {}

    details = {
        "currentSalary": {"ok": True, "skipped": True, "reason": "No current salary value"},
        "expectedSalary": {"ok": True, "skipped": True, "reason": "No expected salary value"},
        "noticePeriod": notice_item.get("details") or {"ok": True, "skipped": True},
        "currency": currency,
        "currencyField": {
            "ok": True,
            "skipped": not bool(currency_selection.get("jobAdderOption")),
            "selectedCurrency": currency,
            "currentCurrency": current_currency,
            "expectedCurrency": expected_currency,
            "jobAdderOption": currency_selection.get("jobAdderOption"),
            "selectionRule": currency_selection.get("selectionRule"),
            "optionSource": currency_selection.get("optionSource"),
            "warning": currency_selection.get("warning"),
        },
        "canonicalSalary": canonical,
    }
    employment = _ja_submit_employment_from_candidate(candidate)
    employment_changed = False

    if current_item.get("writeToProfile") and current_item.get("monthlyEquivalent") is not None:
        value = int(current_item["monthlyEquivalent"])
        current = dict(employment.get("current") or {})
        if current.get("workTypeId") is None:
            current["workTypeId"] = _ONENOTE_JA_PERMANENT_WORKTYPE_ID
        salary = {"ratePer": "Month", "rate": value}
        if current_currency:
            salary["currency"] = current_currency
        current["salary"] = salary
        employment["current"] = current
        employment_changed = True
        details["currentSalary"] = {
            "ok": True, "value": value, "raw": current_item.get("raw"),
            "calculation": current_item, "fingerprint": canonical["validation"]["salaryFingerprint"],
        }
    elif current_item.get("raw"):
        details["currentSalary"] = {"ok": False, "reason": "Could not parse current salary", "raw": current_item.get("raw")}

    if expected_item.get("writeToProfile") and expected_item.get("minAmount") is not None:
        lo = int(expected_item["minAmount"])
        hi = int(expected_item.get("maxAmount", lo))
        ideal = dict(employment.get("ideal") or {})
        if ideal.get("workTypeId") is None:
            ideal["workTypeId"] = _ONENOTE_JA_PERMANENT_WORKTYPE_ID
        salary = {"ratePer": "Month", "rateLow": lo, "rateHigh": hi}
        if expected_currency:
            salary["currency"] = expected_currency
        ideal["salary"] = salary
        employment["ideal"] = ideal
        employment_changed = True
        details["expectedSalary"] = {
            "ok": True, "min": lo, "max": hi, "raw": expected_item.get("raw"),
            "calculation": expected_item, "basisCurrentAmount": expected_item.get("basisCurrentAmount"),
            "fingerprint": canonical["validation"]["salaryFingerprint"],
        }
    elif expected_item.get("raw") and expected_item.get("type") not in ("open", "blank"):
        details["expectedSalary"] = {"ok": False, "reason": "Could not parse expected salary", "raw": expected_item.get("raw")}
    elif expected_item.get("type") == "open":
        details["expectedSalary"] = {"ok": True, "skipped": True, "reason": "Expected salary is open/negotiable", "raw": expected_item.get("raw")}

    payload = {}
    if employment_changed:
        payload["employment"] = employment
    if notice_item.get("payload"):
        payload["availability"] = notice_item["payload"]
    currency_option = currency_selection.get("jobAdderOption")
    candidate_custom_present = "custom" in candidate and isinstance(candidate.get("custom"), list)
    if currency_option and not candidate_custom_present:
        details["currencyField"].update({
            "ok": False,
            "skipped": True,
            "reason": "Candidate GET did not include the custom field collection; Currency write was skipped to avoid clearing unseen custom fields.",
            "value": currency_option,
            "fieldId": _JA_CURRENCY_CUSTOM_FIELD_ID,
        })
    elif currency_option:
        existing_option = None
        for custom_item in candidate.get("custom") or []:
            if not isinstance(custom_item, dict):
                continue
            try:
                existing_field_id = int(custom_item.get("fieldId") or 0)
            except Exception:
                continue
            if existing_field_id == _JA_CURRENCY_CUSTOM_FIELD_ID:
                existing_option = str(custom_item.get("value") or "")
                break
        if existing_option != currency_option:
            # Preserve every existing public-API custom field value while
            # replacing/adding field 4. This mirrors Kano's full customFields
            # clone and avoids clearing unrelated Industry/Skills/etc. values
            # if the tenant treats UpdateCandidate.custom as replacement-like.
            custom_payload = []
            currency_replaced = False
            for custom_item in candidate.get("custom") or []:
                if not isinstance(custom_item, dict):
                    continue
                try:
                    field_id = int(custom_item.get("fieldId"))
                except Exception:
                    continue
                value = custom_item.get("value")
                if field_id == _JA_CURRENCY_CUSTOM_FIELD_ID:
                    custom_payload.append({"fieldId": field_id, "value": currency_option})
                    currency_replaced = True
                elif value is not None:
                    custom_payload.append({"fieldId": field_id, "value": value})
            if not currency_replaced:
                custom_payload.append({"fieldId": _JA_CURRENCY_CUSTOM_FIELD_ID, "value": currency_option})
            payload["custom"] = custom_payload
            details["currencyField"].update({"skipped": False, "value": currency_option, "fieldId": _JA_CURRENCY_CUSTOM_FIELD_ID, "preservedCustomFieldCount": max(0, len(custom_payload) - 1)})
        else:
            details["currencyField"].update({"skipped": True, "reason": "Candidate Currency already matched", "value": currency_option, "fieldId": _JA_CURRENCY_CUSTOM_FIELD_ID})
    elif currency_selection.get("selectedCurrency"):
        details["currencyField"].update({"ok": False, "skipped": True, "reason": currency_selection.get("warning") or "No matching JobAdder Currency option"})
    return payload, details

def _ja_update_candidate_salary_notice(candidate_id, fields, ai_components=None, ai_processing=None, spelling_correction=True):
    candidate_path = "candidates/{}".format(urllib.parse.quote(str(candidate_id), safe=""))
    candidate = {}
    read_status = None
    read_warning = None
    try:
        read_status, candidate = _ja_get_json(candidate_path, timeout=20)
        if not isinstance(candidate, dict):
            candidate = {}
    except Exception as e:
        read_warning = "Could not read existing candidate profile before salary/notice update: {}".format(str(e)[:500])
        # Safety boundary: do not write nested employment/availability without
        # first reading the current profile that must be preserved.
        preview_canonical = _ja_build_salary_notice_canonical(fields, {}, ai_components, ai_processing, spelling_correction=spelling_correction)
        preview_payload, preview_details = _ja_candidate_salary_notice_payload(fields, {}, preview_canonical)
        return {
            "ok": False,
            "skipped": True,
            "candidate_read_status": None,
            "candidate_read_warning": read_warning,
            "payload_fields": sorted(preview_payload.keys()),
            "details": preview_details,
            "salary_canonical": preview_details.get("canonicalSalary"),
            "error": read_warning,
        }
    canonical = _ja_build_salary_notice_canonical(fields, candidate, ai_components, ai_processing, spelling_correction=spelling_correction)
    canonical["currencySelection"] = _ja_validate_currency_option_with_api(canonical.get("currencySelection"))
    canonical["processing"]["jobAdderCurrencyOption"] = canonical["currencySelection"].get("jobAdderOption")
    canonical["processing"]["currencyOptionSource"] = canonical["currencySelection"].get("optionSource")
    payload, details = _ja_candidate_salary_notice_payload(fields, candidate, canonical)
    result = {
        "ok": True,
        "skipped": not bool(payload),
        "candidate_read_status": read_status,
        "candidate_read_warning": read_warning,
        "payload_fields": sorted(payload.keys()),
        "details": details,
        "salary_canonical": details.get("canonicalSalary"),
    }
    parse_warnings = []
    for key in ("currentSalary", "expectedSalary", "noticePeriod", "currencyField"):
        item = details.get(key) or {}
        if item.get("ok") is False:
            parse_warnings.append("{}: {}".format(key, item.get("reason") or "could not parse"))
    if not payload:
        result["warning"] = "; ".join(parse_warnings) if parse_warnings else None
        return result
    try:
        status, response = _ja_put_json(candidate_path, payload, timeout=25)
        result.update({"status": status, "response": response, "skipped": False})
        if parse_warnings:
            result["warning"] = "; ".join(parse_warnings)
        return result
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", errors="replace")
        result.update({
            "ok": False,
            "skipped": False,
            "status": int(e.code),
            "error": "JobAdder candidate profile update failed",
            "detail": _ja_compact_error_body(body),
            "raw": body[:3000],
        })
        return result
    except Exception as e:
        result.update({"ok": False, "skipped": False, "error": str(e)[:1000]})
        return result


@app.route("/jobadder/onenote_browser_bridge", methods=["POST"])
def jobadder_onenote_browser_bridge():
    """Generate a JobAdder-browser console helper for Screening Call creation.

    This does not contact JobAdder and does not require or read browser cookies.
    The generated script must be run by the user inside JobAdder's own page, so
    the request is same-origin and uses their normal JobAdder session safely.
    """
    data = request.get_json(silent=True) or {}
    candidate_id = str(data.get("candidate_id") or data.get("candidateId") or "").strip()
    email = str(data.get("email") or "").strip()
    if not candidate_id:
        return jsonify({"error": "Missing candidate_id"}), 400
    spelling_correction = _ja_bool_setting(data.get("spelling_correction"), default=True)
    fields = _onenote_normalize_screening_fields(data.get("fields") or {})
    if spelling_correction:
        fields = _ja_correct_screening_field_typos(fields, enabled=True)
        fields["notice_period"] = _ja_correct_notice_typos(fields.get("notice_period", ""), enabled=True)
    missing = _onenote_missing_screening_fields(fields)
    if missing:
        return jsonify({"error": "Missing mandatory Screening Call fields", "missing": missing}), 400
    note_text = _onenote_clean_note_text(data.get("note_text") or data.get("text") or "")
    # Never trust a client-supplied canonical salary object.  Rebuild from the
    # labelled fields so emergency profile values remain server-calculated.
    salary_canonical = _ja_build_salary_notice_canonical(fields, {}, spelling_correction=spelling_correction)
    bridge = _ja_spa_browser_bridge(candidate_id, fields, note_text, email=email, salary_canonical=salary_canonical, spelling_correction=spelling_correction)
    return jsonify({"ok": True, "browser_bridge": bridge, "salary_canonical": salary_canonical})

@app.route("/jobadder/onenote_log_screening", methods=["POST"])
def jobadder_onenote_log_screening():
    """Create a native Candidate Screening Call from a OneNote screening note.

    v24.6.137 uses JobAdder's documented AddCandidateActivity OAuth schema as
    the only normal backend activity write. It creates a NEW activity, never
    edits an existing Screening Call, and never creates a Candidate Note.
    After creation it separately updates parsed current/expected salary and
    notice-period profile fields through the documented UpdateCandidate model.
    """
    token = _ja_refresh_access_token(force=False)
    if not token:
        return jsonify({"error": "Not authenticated"}), 401
    data = request.get_json(silent=True) or {}
    candidate_id = str(data.get("candidate_id") or data.get("candidateId") or "").strip()
    email = str(data.get("email") or "").strip()
    if not candidate_id:
        return jsonify({"error": "Missing candidate_id"}), 400
    spelling_correction = _ja_bool_setting(data.get("spelling_correction"), default=True)
    fields = _onenote_normalize_screening_fields(data.get("fields") or {})
    if spelling_correction:
        fields = _ja_correct_screening_field_typos(fields, enabled=True)
        fields["notice_period"] = _ja_correct_notice_typos(fields.get("notice_period", ""), enabled=True)
    missing = _onenote_missing_screening_fields(fields)
    if missing:
        return jsonify({"error": "Missing mandatory Screening Call fields", "missing": missing}), 400
    note_text = _onenote_clean_note_text(data.get("note_text") or data.get("text") or "")
    if not note_text:
        return jsonify({"error": "Missing note_text"}), 400

    candidate_id_q = urllib.parse.quote(candidate_id, safe="")
    create_path = "candidates/{}/activities".format(candidate_id_q)
    activity_url = _jobadder_candidate_activity_url(candidate_id)
    payload = _ja_official_screening_activity_payload(fields, note_text)
    salary_ai_config = dict(data.get("salary_ai") or {}) if isinstance(data.get("salary_ai"), dict) else {}
    if salary_ai_config:
        # Browser requests carry only a backend-secure sentinel after the localStorage
        # migration. Resolve the real provider key inside the trusted backend before
        # invoking the narrowly scoped salary component extractor.
        salary_ai_config["api_key"] = _resolve_request_api_key(salary_ai_config, "main")
    ai_components, ai_processing = _ja_salary_ai_extract(fields, salary_ai_config)
    preview_salary_canonical = _ja_build_salary_notice_canonical(fields, {}, ai_components, ai_processing, spelling_correction=spelling_correction)
    try:
        status, result = _ja_post_json(create_path, payload, timeout=30)
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", errors="replace")
        browser_bridge = _ja_spa_browser_bridge(candidate_id, fields, note_text, email=email, salary_canonical=preview_salary_canonical)
        http_status = int(e.code)
        response_status = http_status if http_status in (401, 403) else 502
        return jsonify({
            "error": "Could not create JobAdder Candidate Screening Call through the official OAuth API. No Candidate Note was created.",
            "why": _ja_compact_error_body(body) or "JobAdder rejected AddCandidateActivity.",
            "next_step": "Use Copy Create Script only as the emergency fallback. It creates a new Screening Call through the logged-in JobAdder browser and never edits an existing Screening Call.",
            "candidate_id": candidate_id,
            "email": email,
            "activity_url": activity_url,
            "official_reference": "https://api.jobadder.com/v2/docs#operation/AddCandidateActivity",
            "browser_bridge": browser_bridge,
            "salary_canonical": preview_salary_canonical,
            "attempts": [{
                "path": create_path,
                "status": http_status,
                "detail": _ja_compact_error_body(body),
                "raw": body[:3000],
            }],
        }), response_status
    except PermissionError as e:
        return jsonify({"error": str(e)}), 401
    except Exception as e:
        browser_bridge = _ja_spa_browser_bridge(candidate_id, fields, note_text, email=email, salary_canonical=preview_salary_canonical)
        return jsonify({
            "error": "Could not create JobAdder Candidate Screening Call through the official OAuth API. No Candidate Note was created.",
            "why": str(e)[:1000],
            "candidate_id": candidate_id,
            "email": email,
            "activity_url": activity_url,
            "official_reference": "https://api.jobadder.com/v2/docs#operation/AddCandidateActivity",
            "browser_bridge": browser_bridge,
            "salary_canonical": preview_salary_canonical,
            "attempts": [{"path": create_path, "error": str(e)[:1000]}],
        }), 502

    activity_id = None
    if isinstance(result, dict):
        for key in ("activityId", "activityID"):
            try:
                activity_id = int(result.get(key))
                break
            except Exception:
                pass
    profile_update = _ja_update_candidate_salary_notice(candidate_id, fields, ai_components, ai_processing, spelling_correction=spelling_correction)
    warning_parts = []
    if not profile_update.get("ok"):
        warning_parts.append("Screening Call was created, but salary/notice profile update failed: {}".format(
            profile_update.get("detail") or profile_update.get("error") or "review required"
        ))
    elif profile_update.get("warning"):
        warning_parts.append("Screening Call was created; some profile values were not parsed: {}".format(profile_update.get("warning")))
    candidate_read_warning = profile_update.get("candidate_read_warning")
    if candidate_read_warning and not any(candidate_read_warning in str(part) for part in warning_parts):
        warning_parts.append(candidate_read_warning)
    warning = " ".join(p for p in warning_parts if p).strip()
    return jsonify({
        "ok": True,
        "mode": "candidate_activity",
        "path": create_path,
        "status": status,
        "candidate_id": candidate_id,
        "email": email,
        "activity_id": activity_id,
        "activity_url": activity_url,
        "screening_fields": fields,
        "result": result,
        "profile_update": profile_update,
        "salary_canonical": profile_update.get("salary_canonical"),
        "warning": warning or None,
        "official_reference": "https://api.jobadder.com/v2/docs#operation/AddCandidateActivity",
    })



def _ja_activity_diagnostic_response_headers(headers):
    """Keep useful response metadata while excluding cookie/authentication headers."""
    blocked = {"set-cookie", "set-cookie2", "authorization", "proxy-authorization"}
    try:
        return {str(k): str(v) for k, v in headers.items() if str(k).lower() not in blocked}
    except Exception:
        return {}


def _ja_activity_diagnostic_network_error(error):
    """Preserve the legacy diagnostic field with shared-client redaction."""
    if isinstance(error, ExternalServiceError):
        return str(getattr(error, "safe_detail", "") or error)
    return str(getattr(error, "reason", error))


def _ja_activity_diagnostic_get(path, timeout=25):
    """Perform one exact read-only JobAdder OAuth GET and preserve the raw response.

    The returned report deliberately excludes the OAuth token and request
    Authorization header. Response bodies are not shortened so the user can
    provide the complete model-binding evidence for review.
    """
    token = str(_ja_creds_store.get("access_token") or "").strip()
    if not token:
        raise PermissionError("Not authenticated")
    url = _ja_api(path)
    started = datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    try:
        response = _JOBADDER_CLIENT.request_raw(
            path,
            method="GET",
            token=token,
            timeout=timeout,
            headers={"Accept": "application/json, text/plain, */*"},
        )
        raw_text = response.body.decode("utf-8", errors="replace")
        headers = _ja_activity_diagnostic_response_headers(response.headers)
        parsed = None
        if raw_text.strip():
            try:
                parsed = json.loads(raw_text)
            except Exception:
                parsed = None
        return {
            "method": "GET",
            "path": path,
            "url": url,
            "started_utc": started,
            "ok": True,
            "status": int(response.status or 200),
            "response_headers": headers,
            "response_body": raw_text,
            "response_json": parsed,
        }
    except urllib.error.HTTPError as e:
        raw_bytes = e.read()
        raw_text = raw_bytes.decode("utf-8", errors="replace")
        headers = _ja_activity_diagnostic_response_headers(e.headers)
        parsed = None
        if raw_text.strip():
            try:
                parsed = json.loads(raw_text)
            except Exception:
                parsed = None
        return {
            "method": "GET",
            "path": path,
            "url": url,
            "started_utc": started,
            "ok": False,
            "status": int(e.code),
            "reason": str(getattr(e, "reason", "") or ""),
            "response_headers": headers,
            "response_body": raw_text,
            "response_json": parsed,
        }
    except (urllib.error.URLError, ExternalServiceError) as e:
        return {
            "method": "GET",
            "path": path,
            "url": url,
            "started_utc": started,
            "ok": False,
            "status": None,
            "network_error": _ja_activity_diagnostic_network_error(e),
            "response_headers": {},
            "response_body": "",
            "response_json": None,
        }


def _ja_activity_diagnostic_summary(request_results):
    """Return a conservative summary without guessing undocumented API behavior."""
    statuses = [r.get("status") for r in (request_results or [])]
    numeric_statuses = [s for s in statuses if isinstance(s, int)]
    if any(200 <= s < 300 for s in numeric_statuses):
        return "At least one OAuth activity GET succeeded. Review the complete response body for the saved Screening Call and Presentability answer model."
    if len(numeric_statuses) == 2 and all(s in (404, 405) for s in numeric_statuses):
        return "Both OAuth activity GET routes returned 404/405. This is evidence that these read routes are unavailable, but the exact POST response must still be reviewed separately before making a final endpoint conclusion."
    if any(s in (401, 403) for s in numeric_statuses):
        return "JobAdder rejected at least one read request as unauthorised. Reconnect JobAdder OAuth before interpreting endpoint availability."
    return "The read requests did not expose a successful activity model. Review each full status and response body before deciding the next controlled test."


@app.route("/jobadder/onenote_activity_diagnostic", methods=["POST"])
def jobadder_onenote_activity_diagnostic():
    """Run the two exact read-only OAuth activity checks requested by the user.

    Safety boundary: this route only performs GET requests. It never creates or
    edits a Screening Call, Candidate Note, salary, notice period, or profile.
    """
    if not _ja_creds_store.get("access_token"):
        return jsonify({"error": "JobAdder is not connected. Reconnect OAuth in CV Studio first."}), 401
    data = request.get_json(silent=True) or {}
    candidate_id = str(data.get("candidate_id") or "").strip()
    activity_id = str(data.get("activity_id") or "").strip()
    if not re.fullmatch(r"\d+", candidate_id):
        return jsonify({"error": "Candidate ID must contain digits only."}), 400
    if not re.fullmatch(r"\d+", activity_id):
        return jsonify({"error": "Activity ID must contain digits only."}), 400

    cid_q = urllib.parse.quote(candidate_id, safe="")
    aid_q = urllib.parse.quote(activity_id, safe="")
    paths = [
        "candidates/{}/activities".format(cid_q),
        "candidates/{}/activities/{}".format(cid_q, aid_q),
    ]
    results = [_ja_activity_diagnostic_get(path, timeout=25) for path in paths]
    generated = datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    report = {
        "diagnostic": "CV Studio JobAdder OAuth Candidate Activity Read Test",
        "cv_studio_version": "v24.6.235",
        "generated_utc": generated,
        "safety": {
            "read_only": True,
            "http_methods_used": ["GET"],
            "created_or_updated_anything": False,
            "oauth_token_included_in_report": False,
        },
        "candidate_id": candidate_id,
        "activity_id": activity_id,
        "api_base": _ja_normalize_api_base(_ja_creds_store.get("api_url")),
        "requests": results,
        "summary": _ja_activity_diagnostic_summary(results),
        "next_boundary": "No OAuth POST was sent. Review this read report before authorising one controlled create test.",
    }
    filename = "jobadder_activity_diagnostic_{}_{}_{}.json".format(
        candidate_id,
        activity_id,
        re.sub(r"[^0-9]", "", generated)[:14],
    )
    return jsonify({"ok": True, "filename": filename, "report": report})


_JA_ACTIVITY_CREATE_DIAG_USED = set()


def _ja_activity_diagnostic_post(path, payload, timeout=25):
    """Send one OAuth POST and preserve the complete response for diagnostics.

    Authentication/cookie headers are never copied into the returned report.
    """
    token = _ja_refresh_access_token(force=False)
    if not token:
        raise PermissionError("JobAdder is not connected")
    url = _ja_api(path)
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    started = datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    base = {
        "method": "POST",
        "path": path,
        "url": url,
        "started_utc": started,
        "request_payload": payload,
    }
    try:
        response = _JOBADDER_CLIENT.request_raw(
            path,
            method="POST",
            body=body,
            token=token,
            timeout=timeout,
            headers={
                "Accept": "application/json, text/plain, */*",
                "Content-Type": "application/json; charset=utf-8",
            },
            safe_to_retry=False,
            retries=0,
        )
        raw_text = response.body.decode("utf-8", errors="replace")
        parsed = None
        if raw_text.strip():
            try:
                parsed = json.loads(raw_text)
            except Exception:
                parsed = None
        base.update({
            "ok": True,
            "status": int(response.status or 200),
            "response_headers": _ja_activity_diagnostic_response_headers(response.headers),
            "response_body": raw_text,
            "response_json": parsed,
        })
        return base
    except urllib.error.HTTPError as e:
        raw_bytes = e.read()
        raw_text = raw_bytes.decode("utf-8", errors="replace")
        parsed = None
        if raw_text.strip():
            try:
                parsed = json.loads(raw_text)
            except Exception:
                parsed = None
        base.update({
            "ok": False,
            "status": int(e.code),
            "reason": str(getattr(e, "reason", "") or ""),
            "response_headers": _ja_activity_diagnostic_response_headers(e.headers),
            "response_body": raw_text,
            "response_json": parsed,
        })
        return base
    except (urllib.error.URLError, ExternalServiceError) as e:
        base.update({
            "ok": False,
            "status": None,
            "network_error": _ja_activity_diagnostic_network_error(e),
            "response_headers": {},
            "response_body": "",
            "response_json": None,
        })
        return base


def _ja_activity_ids_from_list_result(result):
    parsed = (result or {}).get("response_json")
    if not isinstance(parsed, dict):
        return []
    items = parsed.get("items")
    if not isinstance(items, list):
        return []
    out = []
    for item in items:
        if not isinstance(item, dict):
            continue
        value = item.get("activityId")
        if value is None:
            value = item.get("activityID")
        try:
            out.append(int(value))
        except Exception:
            pass
    return out


def _ja_activity_id_from_post_result(result):
    parsed = (result or {}).get("response_json")
    if isinstance(parsed, dict):
        for key in ("activityId", "activityID"):
            value = parsed.get(key)
            try:
                return int(value)
            except Exception:
                pass
        for container_key in ("activity", "item", "result", "data"):
            child = parsed.get(container_key)
            if isinstance(child, dict):
                for key in ("activityId", "activityID"):
                    value = child.get(key)
                    try:
                        return int(value)
                    except Exception:
                        pass
    headers = (result or {}).get("response_headers") or {}
    for key, value in headers.items():
        if str(key).lower() == "location":
            m = re.search(r"/activities/(\d+)(?:$|[/?#])", str(value))
            if m:
                return int(m.group(1))
    return None


def _ja_controlled_official_activity_payload(candidate_id):
    """Build one AddCandidateActivity request from JobAdder's official v2 schema.

    Official reference:
    https://api.jobadder.com/v2/docs#operation/AddCandidateActivity

    The public OAuth write model is intentionally different from both the SPA
    request model and the GET response model:
      - textAnswers: [{questionId, text}]
      - listValueAnswers: [{questionId, values}]
      - dateRangeValueAnswers: [{questionId, startDate, endDate}]
      - ratingValueAnswers: [{questionId, rating}]

    This diagnostic sends one exact documented request only. It does not add
    SPA-only fields, response-only fields, aliases, or automatic fallbacks.
    """
    _ = _ja_maybe_int(candidate_id)  # Validate the fixture ID shape without adding it to the body.
    text_rows = [
        (41172, "N/A"),
        (41173, "why"),
        (41174, "somethjihng"),
        (41175, "2324rm + 32sllowance + 3months"),
        (41176, "4222rm"),
        (41177, "2 months"),
    ]
    return {
        "activitySettingId": _ONENOTE_JA_SCREENING_SETTING_ID,
        "answers": {
            "textAnswers": [
                {"questionId": question_id, "text": answer}
                for question_id, answer in text_rows
            ],
            "listValueAnswers": [],
            "dateRangeValueAnswers": [],
            "ratingValueAnswers": [
                {"questionId": 62988, "rating": 3}
            ],
        },
    }


@app.route("/jobadder/onenote_activity_create_diagnostic", methods=["POST"])
def jobadder_onenote_activity_create_diagnostic():
    """Create exactly one controlled Screening Call on the Max Low dummy fixture.

    This is intentionally separate from the normal OneNote transfer route. It
    never creates Candidate Notes, never edits an existing activity, never
    updates salary/notice/profile fields, and never changes the F12 helper.
    """
    if not _ja_creds_store.get("access_token"):
        return jsonify({"error": "JobAdder is not connected. Reconnect OAuth in CV Studio first."}), 401
    data = request.get_json(silent=True) or {}
    candidate_id = str(data.get("candidate_id") or "").strip()
    confirmation = str(data.get("confirmation") or "").strip()
    if candidate_id != "41262878":
        return jsonify({"error": "This controlled diagnostic is locked to Max Low candidate ID 41262878."}), 400
    if confirmation != "CREATE ONE MAX LOW TEST":
        return jsonify({"error": "Type CREATE ONE MAX LOW TEST exactly before running the controlled POST."}), 400

    guard_key = ("v24.6.235", candidate_id)
    if guard_key in _JA_ACTIVITY_CREATE_DIAG_USED:
        return jsonify({"error": "The one-shot controlled POST has already been run in this CV Studio session. Restarting is intentionally required before any repeat test."}), 409
    # Mark before the network call so a timeout/double-click cannot emit a second POST.
    _JA_ACTIVITY_CREATE_DIAG_USED.add(guard_key)

    cid_q = urllib.parse.quote(candidate_id, safe="")
    list_path = "candidates/{}/activities".format(cid_q)
    create_path = list_path
    before = _ja_activity_diagnostic_get(list_path, timeout=25)
    before_ids = set(_ja_activity_ids_from_list_result(before))
    payload = _ja_controlled_official_activity_payload(candidate_id)
    post_result = _ja_activity_diagnostic_post(create_path, payload, timeout=30)
    after = _ja_activity_diagnostic_get(list_path, timeout=25)
    after_ids = set(_ja_activity_ids_from_list_result(after))
    new_ids = sorted(after_ids - before_ids)
    created_activity_id = _ja_activity_id_from_post_result(post_result)
    if created_activity_id is None and len(new_ids) == 1:
        created_activity_id = new_ids[0]
    detail = None
    if created_activity_id is not None:
        detail = _ja_activity_diagnostic_get(
            "candidates/{}/activities/{}".format(cid_q, urllib.parse.quote(str(created_activity_id), safe="")),
            timeout=25,
        )

    generated = datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    report = {
        "diagnostic": "CV Studio JobAdder OAuth Official AddCandidateActivity Create Test",
        "cv_studio_version": "v24.6.235",
        "generated_utc": generated,
        "candidate_fixture": {
            "name": "Max Low",
            "candidate_id": candidate_id,
            "previous_successful_activity_id": 503608,
        },
        "test_hypothesis": "Use JobAdder's official AddCandidateActivity v2 write contract exactly: activitySettingId 8225; textAnswers use questionId + text; ratingValueAnswers uses questionId 62988 + rating 3; listValueAnswers and dateRangeValueAnswers are empty; no SPA-only or response-only fields.",
        "official_reference": "https://api.jobadder.com/v2/docs#operation/AddCandidateActivity",
        "safety": {
            "oauth_post_count": 1,
            "candidate_notes_created": False,
            "existing_activity_edited": False,
            "salary_or_notice_profile_updated": False,
            "f12_helper_changed": False,
            "oauth_token_included_in_report": False,
            "one_shot_guard_active_for_session": True,
        },
        "preflight_activity_list": before,
        "controlled_post": post_result,
        "postflight_activity_list": after,
        "activity_ids_before": sorted(before_ids),
        "activity_ids_after": sorted(after_ids),
        "new_activity_ids_detected": new_ids,
        "created_activity_id": created_activity_id,
        "created_activity_detail": detail,
        "result_summary": (
            "Controlled POST returned success and a new activity was detected. Review created_activity_detail to confirm text and Presentability 3/4."
            if post_result.get("ok") and created_activity_id is not None
            else "Controlled POST did not produce a confirmed new activity. Review the complete response body; no second POST was attempted."
        ),
        "next_boundary": "Do not repeat or alter the payload until this exact report is reviewed.",
    }
    filename = "jobadder_activity_create_official_schema_diag_{}_{}.json".format(
        candidate_id,
        re.sub(r"[^0-9]", "", generated)[:14],
    )
    return jsonify({"ok": True, "filename": filename, "report": report})


@app.route("/jobadder/onenote_activity_probe", methods=["GET"])
def jobadder_onenote_activity_probe():
    """Read-only diagnostics for JobAdder candidate activity availability.

    This does not create notes or activities. It helps identify the tenant's
    activity settings/endpoints after a transfer fails.
    """
    token = _ja_refresh_access_token(force=False)
    if not token:
        return jsonify({"error": "Not authenticated"}), 401
    candidate_id = str(request.args.get("candidate_id") or "").strip()
    cid = urllib.parse.quote(candidate_id, safe="") if candidate_id else ""
    paths = [
        "candidateActivitySettings",
        "candidate-activity-settings",
        "activities/settings",
        "activities/settings?entityType=candidate",
        "activities/candidates/settings",
        "activitySettings?entityType=candidate",
    ]
    if cid:
        paths.extend([
            "candidateActivities?candidateId={}".format(cid),
            "activities?candidateId={}".format(cid),
            "candidates/{}/activities".format(cid),
            "candidates/{}/activity".format(cid),
            "candidate/{}/activities".format(cid),
            "candidate/{}/activity".format(cid),
        ])
    results = []
    for path in paths:
        try:
            status, data = _ja_get_json(path, timeout=12)
            snippet = data
            try:
                snippet = json.dumps(data, ensure_ascii=False)[:1500]
            except Exception:
                snippet = str(data)[:1500]
            results.append({"path": path, "status": status, "ok": True, "data": snippet})
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            results.append({"path": path, "status": e.code, "ok": False, "detail": _ja_compact_error_body(body), "raw": body[:1500]})
        except Exception as e:
            results.append({"path": path, "ok": False, "error": str(e)[:1000]})
    return jsonify({"ok": True, "candidate_id": candidate_id, "results": results})


def _spider_terms(value, max_terms=18):
    """Split recruiter filter text into safe, compact terms for candidate filtering."""
    if value is None:
        return []
    if isinstance(value, (list, tuple, set)):
        raw_parts = []
        for v in value:
            raw_parts.extend(_spider_terms(v, max_terms=max_terms))
        out, seen = [], set()
        for t in raw_parts:
            k = t.lower()
            if k not in seen:
                seen.add(k)
                out.append(t)
        return out[:max_terms]
    text = str(value or "")
    # Split before stripping control chars so newline-separated must-haves stay separate terms.
    parts = re.split(r"[,;\n\r]+", text)
    out, seen = [], set()
    for part in parts:
        part = re.sub(r"[\x00-\x1f\x7f]", " ", part)
        part = re.sub(r"^[\s\-•*]+", "", part).strip().strip('"\'')
        part = re.sub(r"\s+", " ", part)
        if len(part) < 2 or len(part) > 80:
            continue
        k = part.lower()
        if k in seen:
            continue
        seen.add(k)
        out.append(part)
        if len(out) >= max_terms:
            break
    return out


def _spider_boolean_not_terms(value, max_terms=18):
    """Extract simple NOT terms from recruiter Boolean keyword rules."""
    text = re.sub(r"[\x00-\x1f\x7f]", " ", str(value or ""))
    out, seen = [], set()
    pat = re.compile(r"\bNOT\s+(?:\"([^\"]+)\"|'([^']+)'|\(([^)]+)\)|([^\s(),;]+))", re.I)
    for m in pat.finditer(text):
        raw = next((g for g in m.groups() if g), "")
        for term in re.split(r"\bAND\b|\bOR\b|[,;/]+", raw, flags=re.I):
            term = re.sub(r"^[\s\-•*]+", "", term).strip().strip('"\'()')
            term = re.sub(r"\s+", " ", term)
            if len(term) < 2 or len(term) > 80:
                continue
            k = term.lower()
            if k in seen:
                continue
            seen.add(k)
            out.append(term)
            if len(out) >= max_terms:
                return out
    return out


def _spider_boolean_positive_terms(value, max_terms=24):
    """Extract positive match terms from simple Boolean rules without treating AND/OR as terms."""
    text = re.sub(r"[\x00-\x1f\x7f]", " ", str(value or ""))
    if not text.strip():
        return []
    text = re.sub(r"\bNOT\s+(?:\"[^\"]+\"|'[^']+'|\([^)]+\)|[^\s(),;]+)", " ", text, flags=re.I)
    text = text.replace("（", "(").replace("）", ")")
    parts = []
    for q in re.findall(r"\"([^\"]+)\"|'([^']+)'", text):
        parts.append(q[0] or q[1])
    text = re.sub(r"\"[^\"]+\"|'[^']+'", " ", text)
    parts.extend(re.split(r"\bAND\b|\bOR\b|[,;\n\r()/|]+", text, flags=re.I))
    out, seen = [], set()
    for part in parts:
        term = re.sub(r"^[\s\-•*]+", "", str(part or "")).strip().strip('"\'()')
        term = re.sub(r"\s+", " ", term)
        if not term or term.lower() in {"and", "or", "not"}:
            continue
        if len(term) < 2 or len(term) > 80:
            continue
        k = term.lower()
        if k in seen:
            continue
        seen.add(k)
        out.append(term)
        if len(out) >= max_terms:
            break
    return out


def _spider_terms_for_fit(value, max_terms=24):
    text = str(value or "")
    if re.search(r"\b(AND|OR|NOT)\b|[()\"]", text):
        return _spider_boolean_positive_terms(text, max_terms)
    return _spider_terms(text, max_terms)


def _spider_min_years_value(value):
    try:
        n = int(float(str(value or "0").strip() or 0))
    except Exception:
        n = 0
    return max(0, min(40, n))


def _spider_max_years_value(value):
    """Return an inclusive upper experience bound, or ``None`` for no maximum.

    The UI uses 40 as its LinkedIn-style open-ended right edge (40+), so a
    selected value of 40 intentionally means no upper cap rather than excluding
    a candidate with more than forty years of visible experience.
    """
    if value is None or str(value).strip() == "":
        return None
    try:
        n = int(float(str(value).strip()))
    except Exception:
        return None
    n = max(0, min(40, n))
    return None if n >= 40 else n


def _spider_years_bounds(filters):
    filters = filters if isinstance(filters, dict) else {}
    minimum = _spider_min_years_value(
        filters.get("years_min")
        if filters.get("years_min") is not None
        else (filters.get("years") or filters.get("experience_years"))
    )
    maximum = _spider_max_years_value(
        filters.get("years_max")
        if filters.get("years_max") is not None
        else filters.get("experience_years_max")
    )
    if maximum is not None and maximum < minimum:
        maximum = minimum
    return minimum, maximum


def _spider_parse_employment_month(value, is_end=False):
    raw = re.sub(r"\s+", " ", str(value or "")).strip()
    if not raw:
        return None
    if re.search(r"\b(?:present|current|now|ongoing|to date)\b", raw, re.I):
        today = date.today()
        return today.year * 12 + (today.month - 1)
    m = re.search(r"(?<!\d)((?:19|20)\d{2})(?:[-/.](1[0-2]|0?[1-9]))?(?!\d)", raw)
    if not m:
        month_names = {
            "jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3,
            "apr": 4, "april": 4, "may": 5, "jun": 6, "june": 6, "jul": 7, "july": 7,
            "aug": 8, "august": 8, "sep": 9, "sept": 9, "september": 9,
            "oct": 10, "october": 10, "nov": 11, "november": 11, "dec": 12, "december": 12,
        }
        m2 = re.search(
            r"\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|"
            r"jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)"
            r"[\s,./-]+((?:19|20)\d{2})\b",
            raw,
            re.I,
        )
        if not m2:
            return None
        month = month_names.get(m2.group(1).lower()[:3])
        year = int(m2.group(2))
    else:
        year = int(m.group(1))
        month = int(m.group(2)) if m.group(2) else (12 if is_end else 1)
    if year < 1950 or year > date.today().year + 1 or not month:
        return None
    return year * 12 + (month - 1)


def _spider_structured_employment_years(candidate):
    """Calculate non-overlapping career duration from JobAdder employment history."""
    roots = []
    if isinstance(candidate, dict):
        roots.append(candidate)
        detail = candidate.get("_spiderDetail")
        if isinstance(detail, dict):
            roots.append(detail)
    intervals = []
    seen_records = set()
    for root in roots:
        employment = root.get("employment") if isinstance(root.get("employment"), dict) else {}
        histories = []
        for key in ("history", "employmentHistory", "workHistory", "positions"):
            value = employment.get(key)
            if isinstance(value, list):
                histories.extend(value)
        for key in ("employmentHistory", "workHistory", "positions"):
            value = root.get(key)
            if isinstance(value, list):
                histories.extend(value)
        for record in histories[:200]:
            if not isinstance(record, dict):
                continue
            signature = repr(sorted((str(k), str(v)) for k, v in record.items() if k in {
                "start", "startDate", "from", "dateFrom", "end", "endDate", "to", "dateTo", "employer", "position"
            }))
            if signature in seen_records:
                continue
            seen_records.add(signature)
            start_raw = next((record.get(k) for k in ("start", "startDate", "from", "dateFrom", "dateStarted") if record.get(k)), None)
            end_raw = next((record.get(k) for k in ("end", "endDate", "to", "dateTo", "dateFinished") if record.get(k)), None)
            start_month = _spider_parse_employment_month(start_raw, is_end=False)
            end_month = _spider_parse_employment_month(end_raw or "Present", is_end=True)
            if start_month is None or end_month is None or end_month < start_month:
                continue
            intervals.append((start_month, end_month + 1))
    if not intervals:
        return None
    intervals.sort()
    merged = []
    for start_month, end_month in intervals:
        if not merged or start_month > merged[-1][1]:
            merged.append([start_month, end_month])
        else:
            merged[-1][1] = max(merged[-1][1], end_month)
    total_months = sum(max(0, end_month - start_month) for start_month, end_month in merged)
    return round(total_months / 12.0, 2) if total_months > 0 else None


def _spider_visible_years(candidate):
    """Return explicit or structured career experience without age/location guesses.

    Structured JobAdder employment history remains authoritative. Text fallback
    accepts common recruiter wording (``3 yrs exp``, ``18 months experience``,
    ``10 years overall experience``) but still requires an explicit experience
    marker in the same phrase. Generic elapsed time such as ``20 years in
    Malaysia`` or ``graduated 12 years ago`` therefore remains unknown.
    """
    structured = _spider_structured_employment_years(candidate)
    if structured is not None:
        return structured

    text = _spider_pick_field_text(
        candidate,
        ["totalexperience", "experienceyears", "yearsexperience", "experience", "profile", "summary"],
    )
    if not text:
        text = _spider_candidate_blob(candidate)
    text = re.sub(r"\s+", " ", str(text or ""))
    vals = []
    qualifier = (
        r"(?:overall\s+|total\s+|relevant\s+|professional\s+|hands[- ]on\s+|"
        r"industry\s+|working\s+|commercial\s+|technical\s+|practical\s+|"
        r"[A-Za-z][A-Za-z0-9+#./-]{1,24}\s+){0,3}"
    )
    year_patterns = [
        # 3 years overall experience / 3+ yrs AWS experience / 3 yrs exp
        rf"(?<!\d)(\d{{1,2}}(?:\.\d+)?)(?:\+)?\s*(?:years?|yrs?)\s+(?:of\s+)?{qualifier}(?:experience|exp)\b",
        # overall experience: 3 years / AWS experience of 3 yrs
        rf"\b{qualifier}(?:experience|exp)\s*(?:of\s*)?[:=-]?\s*(\d{{1,2}}(?:\.\d+)?)(?:\+)?\s*(?:years?|yrs?)\b",
        # over/nearly 3 years of relevant experience
        rf"\b(?:over|more\s+than|around|approximately|approx\.?|nearly)\s+(\d{{1,2}}(?:\.\d+)?)\s*(?:years?|yrs?)\s+(?:of\s+)?{qualifier}(?:experience|exp)\b",
    ]
    month_patterns = [
        rf"(?<!\d)(\d{{1,3}}(?:\.\d+)?)(?:\+)?\s*(?:months?|mths?|mos?)\s+(?:of\s+)?{qualifier}(?:experience|exp)\b",
        rf"\b{qualifier}(?:experience|exp)\s*(?:of\s*)?[:=-]?\s*(\d{{1,3}}(?:\.\d+)?)(?:\+)?\s*(?:months?|mths?|mos?)\b",
    ]
    for pattern in year_patterns:
        for m in re.finditer(pattern, text, re.I):
            try:
                value = float(m.group(1))
            except Exception:
                continue
            if 0 <= value <= 60:
                vals.append(value)
    for pattern in month_patterns:
        for m in re.finditer(pattern, text, re.I):
            try:
                months = float(m.group(1))
            except Exception:
                continue
            if 0 <= months <= 720:
                vals.append(round(months / 12.0, 2))
    return max(vals) if vals else None

def _spider_flatten(value, depth=0):
    if depth > 5 or value is None:
        return []
    if isinstance(value, str):
        return [value]
    if isinstance(value, (int, float, bool)):
        return [str(value)]
    if isinstance(value, list):
        out = []
        for x in value[:80]:
            out.extend(_spider_flatten(x, depth + 1))
        return out
    if isinstance(value, dict):
        out = []
        for k, v in list(value.items())[:120]:
            # Internal discovery/scoring metadata must never become candidate evidence.
            if str(k).startswith("_spider"):
                continue
            out.append(str(k))
            out.extend(_spider_flatten(v, depth + 1))
        return out
    return [str(value)]


def _spider_candidate_blob(candidate):
    """Build candidate evidence with the latest resume first.

    Candidate detail objects can be large.  Resume text used to be appended after
    the detail JSON and then lost to the 20,000-character evidence ceiling, which
    could leave every result on the same 10% discovery floor.  Reserve the front of
    the blob for the latest extracted CV and fill the remaining space with profile
    fields, excluding the duplicate ``resumeText`` key from the second pass.
    """
    resume_text = ""
    profile_value = candidate
    if isinstance(candidate, dict):
        resume_text = re.sub(r"\s+", " ", str(candidate.get("resumeText") or "")).strip()[:14000]
        if "resumeText" in candidate:
            profile_value = {k: v for k, v in candidate.items() if k != "resumeText"}
    profile_text = re.sub(r"\s+", " ", " ".join(_spider_flatten(profile_value))).strip()
    if resume_text:
        remaining = max(0, 20000 - len(resume_text) - 1)
        return (resume_text + " " + profile_text[:remaining]).strip()
    return profile_text[:20000]


def _spider_pick_field_text(candidate, key_patterns):
    """Extract text from likely matching fields without assuming one JobAdder schema."""
    pats = [p.lower() for p in key_patterns]
    found = []

    def walk(obj, depth=0):
        if depth > 5 or obj is None:
            return
        if isinstance(obj, dict):
            for k, v in obj.items():
                lk = str(k).lower()
                if any(p in lk for p in pats):
                    found.extend(_spider_flatten(v, depth + 1))
                walk(v, depth + 1)
        elif isinstance(obj, list):
            for x in obj[:80]:
                walk(x, depth + 1)

    walk(candidate)
    return re.sub(r"\s+", " ", " ".join(found)).strip()[:6000]


