def _spider_candidate_attachment_records(token, candidate_id):
    """Return latest Resume/FormattedResume attachment records using the official API."""
    if not token or not candidate_id:
        return []
    cid = urllib.parse.quote(str(candidate_id), safe="")
    params = urllib.parse.urlencode([
        ("Type", "Resume"),
        ("Type", "FormattedResume"),
        ("Latest", "true"),
        ("Limit", "4"),
    ])
    try:
        raw, _ctype, _dispo = _spider_get_ja_raw(
            token,
            "candidates/{}/attachments?{}".format(cid, params),
            timeout=10,
            accept_json=True,
        )
        payload = safe_json(raw, {})
        items = payload.get("items") if isinstance(payload, dict) else []
        items = items if isinstance(items, list) else []
        records = [x for x in items if isinstance(x, dict)]
        # Stable two-stage sort: newest within each attachment type, with the
        # original Resume type ahead of FormattedResume.
        records.sort(key=lambda item: str(item.get("createdAt") or ""), reverse=True)
        records.sort(key=lambda item: 0 if str(item.get("type") or "").lower() == "resume" else 1 if str(item.get("type") or "").lower() == "formattedresume" else 2)
        return records[:4]
    except _SpiderJobAdderReconnectRequired:
        raise
    except Exception:
        return []


def _spider_fetch_candidate_resume_text(token, candidate_id):
    """Fetch and extract the latest JobAdder resume for match-fit scoring.

    The Keywords endpoint searches the latest resume, while candidate detail JSON
    often omits that resume text.  This helper closes that evidence gap without
    exposing the full extracted CV in the candidate-card response.
    """
    cached = _spider_resume_text_cache_get(token, candidate_id)
    if cached is not None:
        return cached.get("text") or "", cached.get("source") or "cached resume"
    cid = urllib.parse.quote(str(candidate_id), safe="")
    # One latest attachment keeps discovery request volume bounded. JobAdder's
    # Latest=true response is already ordered with Resume ahead of FormattedResume.
    for record in _spider_candidate_attachment_records(token, candidate_id)[:1]:
        attach_id = record.get("attachmentId") or record.get("id")
        if not attach_id:
            continue
        try:
            raw, ctype, dispo = _spider_get_ja_raw(
                token,
                "candidates/{}/attachments/{}".format(cid, urllib.parse.quote(str(attach_id), safe="")),
                timeout=12,
            )
            filename = record.get("fileName") or dispo or ""
            text, source = _spider_extract_text_from_download(raw, ctype, filename, ocr_page_limit=2, ocr_deadline_seconds=18)
            if text:
                _spider_resume_text_cache_put(token, candidate_id, text, source)
                return text, source
        except _SpiderJobAdderReconnectRequired:
            raise
        except Exception:
            continue
    return "", "resume text unavailable"


def _spider_fetch_candidate_bundle(token, candidate_id, include_resume=True):
    detail = _spider_fetch_candidate_detail(token, candidate_id)
    resume_text, resume_source = ("", "")
    if include_resume:
        resume_text, resume_source = _spider_fetch_candidate_resume_text(token, candidate_id)
    return {"detail": detail, "resume_text": resume_text, "resume_source": resume_source}


def _spider_number(value):
    try:
        number = float(value)
        return number if number == number else None
    except Exception:
        try:
            cleaned = re.sub(r"[^0-9.\-]", "", str(value or ""))
            return float(cleaned) if cleaned else None
        except Exception:
            return None


def _spider_salary_snapshot(salary, is_range=False):
    if not isinstance(salary, dict):
        return None
    currency = str(salary.get("currency") or salary.get("currencyCode") or "").strip().upper()
    rate_per = str(salary.get("ratePer") or salary.get("period") or "").strip()
    low = _spider_number(salary.get("rateLow") if is_range else salary.get("rate"))
    high = _spider_number(salary.get("rateHigh")) if is_range else low
    if low is None and is_range:
        low = _spider_number(salary.get("rate") or salary.get("amount") or salary.get("value"))
    if high is None:
        high = low
    if low is None and high is None:
        return None
    values = [x for x in (low, high) if x is not None]
    lo = min(values) if values else None
    hi = max(values) if values else None
    def fmt(n):
        if n is None:
            return ""
        rounded = round(n)
        return "{:,.0f}".format(rounded) if abs(n - rounded) < 0.005 else "{:,.2f}".format(n).rstrip("0").rstrip(".")
    display_value = fmt(lo)
    if hi is not None and lo is not None and abs(hi - lo) > 0.005:
        display_value += " to " + fmt(hi)
    display = ((currency + " ") if currency else "") + display_value
    if rate_per:
        display += " / " + rate_per
    factor = {"hour": 173.333, "day": 21.666, "week": 4.333, "month": 1.0, "year": 1.0 / 12.0}.get(rate_per.lower(), 1.0)
    representative = lo if lo is not None else hi
    monthly = representative * factor if representative is not None else None
    return {"display": display.strip(), "sort": monthly, "currency": currency, "ratePer": rate_per}


def _spider_custom_field_value(candidate, aliases):
    aliases = [re.sub(r"[^a-z0-9]", "", str(x or "").lower()) for x in aliases]
    custom = candidate.get("custom") if isinstance(candidate, dict) else None
    if not isinstance(custom, list):
        return None
    for item in custom:
        if not isinstance(item, dict):
            continue
        name = re.sub(r"[^a-z0-9]", "", str(item.get("name") or item.get("label") or "").lower())
        if any(alias and (alias == name or alias in name) for alias in aliases):
            return item.get("value")
    return None


def _spider_notice_snapshot(candidate):
    availability = candidate.get("availability") if isinstance(candidate, dict) else None
    if isinstance(availability, dict):
        if availability.get("immediate") is True:
            return {"display": "Immediate", "sort": 0}
        relative = availability.get("relative")
        if isinstance(relative, dict):
            period = _spider_number(relative.get("period"))
            unit = str(relative.get("unit") or "").strip()
            if period is not None and unit:
                n = int(period) if float(period).is_integer() else period
                label = unit.rstrip("s") + ("" if float(period) == 1 else "s")
                unit_low = unit.lower()
                day_factor = 1 if unit_low.startswith("day") else 7 if unit_low.startswith("week") else 30 if unit_low.startswith("month") else 365 if unit_low.startswith("year") else 30
                days = float(period) * day_factor
                return {"display": "{} {}".format(n, label), "sort": days}
        date_value = str(availability.get("date") or "").strip()
        if date_value:
            try:
                dt = datetime.fromisoformat(date_value[:10]).date()
                days = max(0, (dt - date.today()).days)
            except Exception:
                days = None
            return {"display": date_value[:10], "sort": days}
    raw = _spider_custom_field_value(candidate, ["notice period", "notice", "availability", "available from"])
    if raw not in (None, "", [], {}):
        text = re.sub(r"\s+", " ", " ".join(_spider_flatten(raw))).strip()
        if re.search(r"\b(immediate|immediately|asap|available now)\b", text, re.I):
            return {"display": "Immediate", "sort": 0}
        m = re.search(r"(\d+(?:\.\d+)?)\s*(day|week|month)s?", text, re.I)
        if m:
            number = float(m.group(1))
            unit = m.group(2).lower()
            days = number * ({"day": 1, "week": 7, "month": 30}[unit])
            return {"display": text[:120], "sort": days}
        return {"display": text[:120], "sort": None}
    return None


def _spider_card_fields(candidate):
    candidate = candidate if isinstance(candidate, dict) else {}
    employment = candidate.get("employment") if isinstance(candidate.get("employment"), dict) else {}
    current = employment.get("current") if isinstance(employment.get("current"), dict) else {}
    ideal = employment.get("ideal") if isinstance(employment.get("ideal"), dict) else {}
    current_salary = _spider_salary_snapshot(current.get("salary"), False)
    expected_salary = _spider_salary_snapshot(ideal.get("salary"), True)
    if not expected_salary:
        for other in ideal.get("other") or []:
            if isinstance(other, dict):
                expected_salary = _spider_salary_snapshot(other.get("salary"), True)
                if expected_salary:
                    break
    return {
        "currentSalary": current_salary,
        "expectedSalary": expected_salary,
        "notice": _spider_notice_snapshot(candidate),
    }


def _spider_normalized_record_label(item):
    if not isinstance(item, dict):
        return ""
    for key in ("name", "label", "fieldName", "customFieldName", "displayName", "title"):
        value = str(item.get(key) or "").strip().casefold()
        if value:
            return re.sub(r"[^a-z0-9]+", "", value)
    return ""


def _spider_custom_record_key(item):
    if not isinstance(item, dict):
        return ""
    for key in ("fieldId", "fieldID", "customFieldId", "customFieldID", "id"):
        value = item.get(key)
        if value not in (None, ""):
            return "id:" + str(value).strip().casefold()
    label = _spider_normalized_record_label(item)
    return "label:" + label if label else ""


def _spider_work_record_key(item):
    if not isinstance(item, dict):
        return ""
    for key in ("id", "workTypeId", "workTypeID", "typeId", "typeID"):
        value = item.get(key)
        if value not in (None, ""):
            return "id:" + str(value).strip().casefold()
    work_type = item.get("workType")
    if isinstance(work_type, dict):
        for key in ("id", "value", "name", "label"):
            value = work_type.get(key)
            if value not in (None, ""):
                return "work:" + re.sub(r"[^a-z0-9]+", "", str(value).casefold())
    elif work_type not in (None, ""):
        return "work:" + re.sub(r"[^a-z0-9]+", "", str(work_type).casefold())
    for key in ("type", "name", "label"):
        value = item.get(key)
        if value not in (None, ""):
            return "work:" + re.sub(r"[^a-z0-9]+", "", str(value).casefold())
    return ""


def _spider_merge_record_lists(primary, secondary, key_func):
    left = list(primary) if isinstance(primary, list) else []
    right = list(secondary) if isinstance(secondary, list) else []
    merged = [dict(item) if isinstance(item, dict) else item for item in left]
    positions = {}
    for index, item in enumerate(merged):
        key = key_func(item)
        if key and key not in positions:
            positions[key] = index
    for item in right:
        if not isinstance(item, dict):
            if item not in merged:
                merged.append(item)
            continue
        key = key_func(item)
        if key and key in positions and isinstance(merged[positions[key]], dict):
            merged[positions[key]] = _spider_merge_missing_json(merged[positions[key]], item, 1)
        else:
            if key:
                positions[key] = len(merged)
            merged.append(dict(item))
    return merged


def _spider_merge_missing_json(primary, secondary, depth=0):
    """Deep-fill missing JobAdder list fields from full candidate detail.

    Existing list-result values stay authoritative.  Dictionaries recurse, while
    ordinary lists append missing values.  Candidate custom fields and expected-
    salary work-type lists receive identity-aware merging in the wrapper below.
    """
    if depth > 10:
        return primary
    if isinstance(primary, dict) and isinstance(secondary, dict):
        merged = dict(primary)
        for key, value in secondary.items():
            if key not in merged or merged.get(key) in (None, "", [], {}):
                merged[key] = value
            elif isinstance(merged.get(key), dict) and isinstance(value, dict):
                merged[key] = _spider_merge_missing_json(merged.get(key), value, depth + 1)
            elif isinstance(merged.get(key), list) and isinstance(value, list):
                # Generic list fill is conservative.  Identity-aware business
                # lists are merged below so a detail salary/notice cannot vanish.
                out = list(merged.get(key) or [])
                for candidate in value:
                    if candidate not in out:
                        out.append(candidate)
                merged[key] = out
        return merged
    if isinstance(primary, list) and isinstance(secondary, list):
        out = list(primary)
        for value in secondary:
            if value not in out:
                out.append(value)
        return out
    if primary in (None, "", [], {}):
        return secondary
    return primary


def _spider_merge_candidate_summary_and_detail(summary, detail):
    if not isinstance(summary, dict):
        summary = {"value": summary}
    if not isinstance(detail, dict):
        return dict(summary)
    merged = _spider_merge_missing_json(summary, detail)

    custom = _spider_merge_record_lists(summary.get("custom"), detail.get("custom"), _spider_custom_record_key)
    if custom:
        merged["custom"] = custom

    summary_employment = summary.get("employment") if isinstance(summary.get("employment"), dict) else {}
    detail_employment = detail.get("employment") if isinstance(detail.get("employment"), dict) else {}
    merged_employment = merged.get("employment") if isinstance(merged.get("employment"), dict) else {}
    summary_ideal = summary_employment.get("ideal") if isinstance(summary_employment.get("ideal"), dict) else {}
    detail_ideal = detail_employment.get("ideal") if isinstance(detail_employment.get("ideal"), dict) else {}
    merged_ideal = merged_employment.get("ideal") if isinstance(merged_employment.get("ideal"), dict) else {}
    ideal_other = _spider_merge_record_lists(summary_ideal.get("other"), detail_ideal.get("other"), _spider_work_record_key)
    if ideal_other:
        merged_ideal = dict(merged_ideal)
        merged_ideal["other"] = ideal_other
        merged_employment = dict(merged_employment)
        merged_employment["ideal"] = merged_ideal
        merged["employment"] = merged_employment

    # Retain a private scoring copy only.  Response construction removes it.
    merged["_spiderDetail"] = detail
    return merged


def _spider_hit_terms(blob_low, terms):
    hits = []
    for term in terms or []:
        if _spider_term_matches(blob_low, term):
            hits.append(term)
    return hits


_SPIDER_JD_HEADING_PREFIX_RE = re.compile(
    r"^\s*(?:"
    r"\d{1,3}(?:\.\d{1,3})+|"        # 2.1 / 2.4.3
    r"\d{1,3}[.)]|"                   # 2. / 2)
    r"[A-Za-z][.)]|"                   # A. / b)
    r"[IVXLCDM]{1,8}[.)]"              # I. / IV)
    r")\s*",
    re.I,
)


def _spider_strip_jd_heading_prefix(value):
    """Remove common corporate outline numbering without touching content years."""
    return _SPIDER_JD_HEADING_PREFIX_RE.sub("", str(value or "")).strip()


def _spider_jd_heading_section(raw_line):
    """Classify a JD heading and return ``(section, remainder)``.

    ``section`` is one of ``core``, ``nice`` or ``noise``.  Corporate numbering
    such as ``2.2 Primary Responsibilities`` is removed before matching, while
    ordinary sentences remain untouched.  Exact heading matching prevents a
    sentence such as "experience with AWS" from changing the active section.
    """
    line = re.sub(r"^[\s#>*•\-–—]+", "", str(raw_line or "")).strip()
    line = _spider_strip_jd_heading_prefix(line)
    if not line:
        return None, ""

    def normalise(value):
        value = str(value or "").casefold().replace("&", " and ")
        value = value.replace("’", "'").replace("‘", "'").replace("`", "'")
        value = value.replace("'", "")
        value = re.sub(r"[^a-z0-9+]+", " ", value)
        return re.sub(r"\s+", " ", value).strip()

    core_headings = {
        "job purpose", "role purpose", "position purpose", "purpose of the role",
        "your role", "the role", "role summary", "job summary", "position summary",
        "your mission", "role mission", "the position", "position description",
        "what you will do", "what youll do", "what you do", "your responsibilities",
        "what you will be doing", "what youll be doing", "what you would do",
        "what you will be responsible for", "what youll be responsible for",
        "key responsibilities", "primary responsibilities", "main responsibilities",
        "responsibilities", "role responsibilities", "job responsibilities", "duties",
        "responsibilities and duties", "responsibilities and accountabilities",
        "responsibilities duties", "key responsibilities and duties",
        "key responsibilities and deliverables", "responsibilities and deliverables",
        "key duties", "job duties", "accountabilities", "key accountabilities",
        "scope of work", "job scope", "role scope", "day to day", "your impact", "key deliverables",
        "key tasks", "what you need to succeed", "what you need", "what we need",
        "what we are looking for", "what were looking for", "requirements",
        "job requirements", "role requirements", "candidate requirements",
        "key requirements", "core requirements", "minimum requirements",
        "must have", "must haves", "essential requirements", "essential skills",
        "essential criteria", "selection criteria", "required criteria",
        "required skills", "required experience", "skills and experience",
        "skills required", "experience required", "required qualifications",
        "minimum qualifications", "knowledge skills and abilities", "candidate specification",
        "person specification", "technical skills", "functional skills",
        "key skills and experience", "qualifications and skills", "qualifications skills",
        "experience and skills", "candidate profile", "who you are", "about you",
        "qualifications", "capabilities", "competencies", "core competencies",
        "details regarding the types of experience required", "types of experience required",
        "education certification and designation requirements",
        "technical requirements", "functional requirements",
        "tech stack", "technology stack", "tech stack tools", "technology stack tools",
        "tools", "technologies", "platforms", "systems", "tools and technologies",
        "technology and tools", "technical stack",
    }
    nice_headings = {
        "nice to have", "nice to haves", "good to have", "good to haves",
        "preferred", "preferred skills", "preferred experience", "preferred qualifications",
        "preferred qualifications and experience", "preferred experience and skills",
        "preferred desirable", "preferred and desirable", "desirable", "desirable skills",
        "desirable criteria", "desired skills", "desired qualifications", "desired experience",
        "bonus", "bonus points", "added advantage", "an advantage", "advantage", "advantageous", "additional skills",
        "nice if you have", "it would be a plus", "a plus", "plus",
        "optional", "optional requirements",
    }
    noise_headings = {
        "rbc job mandate", "job mandate", "mandate template", "job details", "reports to details",
        "job information", "job information for use by position evaluation team only",
        "time allocation", "time allocation percent", "level of responsibility and decision",
        "managerial scope", "financial impact", "key relationships", "key contact and purpose of relationship",
        "required in canada only for pay equity purposes", "working conditions", "physical effort", "mental effort",
        "about our client", "about the client", "about the company", "company overview",
        "about us", "who we are", "our client", "client overview", "company profile", "company background",
        "about the organisation", "about the organization", "about the role",
        "role overview", "job overview", "overview", "purpose", "mandate template",
        "location", "work arrangement", "working arrangement", "work mode", "work setup",
        "salary", "salary and benefits", "compensation", "remuneration", "benefits",
        "perks", "why join us", "why join", "what we offer", "culture", "our culture",
        "alternative job titles", "alternative titles", "equal opportunity",
        "diversity and inclusion", "how to apply", "application process", "contact",
        "company information", "confidential", "for candidate use only",
    }

    prefix = line
    remainder = ""
    m = re.match(r"^(.{1,100}?)(?:\s*[:：]\s*|\s+[\-–—]\s+)(.+)$", line)
    if m:
        prefix, remainder = m.group(1).strip(), m.group(2).strip()
    key = normalise(prefix)
    if key in core_headings:
        return "core", remainder
    if key in nice_headings:
        return "nice", remainder
    if key in noise_headings or re.fullmatch(r"page\s+\d+\s+of\s+\d+", key or ""):
        return "noise", ""

    key = normalise(line.rstrip(":：-–— "))
    if key in core_headings:
        return "core", ""
    if key in nice_headings:
        return "nice", ""
    if key in noise_headings or re.fullmatch(r"page\s+\d+\s+of\s+\d+", key or ""):
        return "noise", ""
    return None, line

def _spider_jd_scoring_lines(jd_text):
    """Return section-aware JD lines for fit scoring.

    When a JD contains recognised responsibility/requirement/tech-stack or
    nice-to-have headings, only those sections are scored.  Company marketing,
    location/work-mode metadata, benefits, culture, legal text and footers are
    ignored.  Unstructured JDs retain a conservative fallback so keyword-only
    or plain-paragraph job descriptions continue to work.
    """
    text = re.sub(r"[\x00-\x09\x0b\x0c\x0e-\x1f\x7f]", " ", str(jd_text or ""))
    core, nice, fallback = [], [], []
    current = None
    target_heading_seen = False
    metadata_line_re = re.compile(
        r"^(?:job\s+title|evaluated\s+position\s+level|position\s+level|platform|city\s*,?\s*country|transit|incumbent\s+name|signature|date|job\s+id|mandate\s+effective\s+date|location|work(?:ing)?\s*(?:mode|arrangement|setup)?|city|state|country|salary|compensation)\s*[:|=-]",
        re.I,
    )
    footer_re = re.compile(
        r"^(?:rbc\s+canada\s+only(?:\s+\w+\s+\d{4})?|hyppies\s*\||confidential(?:\s*\||$)|for candidate use only|page\s+\d+\s+of\s+\d+|\d{1,2}/\d{1,2}/\d{4})",
        re.I,
    )
    def looks_like_unknown_heading(value):
        value = re.sub(r"\s+", " ", str(value or "")).strip().rstrip(":：-–— ")
        if not value or len(value) > 90 or len(value.split()) > 10:
            return False
        letters = [ch for ch in value if ch.isalpha()]
        if not letters:
            return False
        upper_ratio = sum(ch.isupper() for ch in letters) / float(len(letters))
        titleish = value == value.title()
        return upper_ratio >= 0.75 or titleish

    for original in re.split(r"[\r\n]+", text):
        raw = re.sub(r"^[\s•*]+", "", original).strip()
        raw = _spider_strip_jd_heading_prefix(raw)
        if not raw:
            continue
        section, remainder = _spider_jd_heading_section(raw)
        if section is not None:
            current = section
            if section in {"core", "nice"}:
                target_heading_seen = True
                if remainder:
                    (core if section == "core" else nice).append(remainder)
            continue
        # A short unknown corporate heading must end an earlier About/Benefits
        # block. Otherwise a valid section such as "YOUR ROLE" remains trapped
        # inside noise and the entire unstructured fallback can disappear.
        if current == "noise" and looks_like_unknown_heading(raw):
            current = None
            continue
        if metadata_line_re.match(raw) or footer_re.match(raw):
            continue
        # Header strips such as "Kuala Lumpur | On-site | Fintech" are context,
        # not capability evidence.  Keep only fragments that are not pure
        # location/work-arrangement context for the unstructured fallback.
        fallback_line = raw
        if "|" in fallback_line:
            pieces = [part.strip() for part in fallback_line.split("|") if part.strip()]
            pieces = [part for part in pieces if not _spider_context_only_fit_term(part, {})]
            fallback_line = " | ".join(pieces).strip()
        if fallback_line and current != "noise":
            fallback.append(fallback_line)
        if current == "core":
            core.append(raw)
        elif current == "nice":
            nice.append(raw)
        # Content inside an explicitly noisy section is deliberately ignored.

    def dedupe(lines):
        seen, out = set(), []
        for line in lines:
            line = re.sub(r"\s+", " ", str(line or "")).strip()
            key = line.casefold()
            if line and key not in seen:
                seen.add(key)
                out.append(line)
        return out

    if target_heading_seen:
        return {"sectioned": True, "core": dedupe(core), "nice": dedupe(nice), "fallback": []}
    return {"sectioned": False, "core": dedupe(fallback), "nice": [], "fallback": dedupe(fallback)}


def _spider_jd_relevance_terms(jd_text, max_terms=34):
    """Extract balanced, section-focused JD terms for fit scoring.

    Terms are collected per responsibility/requirement line and selected in a
    balanced pass, so the first long bullet cannot consume the whole budget.
    Explicit tools, regulatory frameworks and professional certifications rank
    above generic noun phrases.  Language, degree and corporate-template noise
    remain excluded by policy.
    """
    groups = _spider_jd_scoring_lines(jd_text)
    if not groups.get("core") and not groups.get("nice"):
        return []

    language_line_re = re.compile(
        r"\b(language|languages|linguistic|fluent|fluency|spoken|written|bilingual|multilingual|"
        r"english|mandarin|chinese|cantonese|hokkien|hakka|teochew|malay|bahasa|japanese|korean|thai|"
        r"vietnamese|tagalog|filipino|indonesian)\b",
        re.I,
    )
    education_line_re = re.compile(
        r"\b(degree|diploma|bachelor|master|phd|doctorate|university|college|education|academic|"
        r"cgpa|gpa|spm|stpm)\b",
        re.I,
    )
    certification_re = re.compile(r"\b(?:ACA|CIMA|ACCA|CFA|CPA|FRM|PMP|CISSP|CISM|CISA)\b", re.I)
    ignored_exact = {
        "rbc", "gg", "tbd", "id", "it", "job id", "position level", "evaluated position level",
        "incumbent name", "signature date", "required", "preferred", "other", "details",
    }
    generic = {
        "responsibilities", "requirements", "experience", "years experience", "candidate", "role", "skills",
        "good communication", "strong communication", "team player", "stakeholders", "fast paced",
        "ability to", "responsible for", "knowledge of", "familiar with", "hands on", "hands-on",
        "finance qualification", "required", "preferred",
    }
    stop_tokens = {
        "and", "or", "the", "for", "with", "from", "into", "this", "that", "will", "must", "have", "has",
        "able", "work", "working", "team", "teams", "role", "candidate", "experience", "years", "year", "strong",
        "good", "excellent", "skills", "knowledge", "understanding", "responsible", "required", "requirement",
        "to", "of", "in", "via", "through", "as", "a", "an", "on", "such", "including", "includes",
        "provide", "provides", "provided", "using", "use", "used", "similar", "other", "applications", "rbc",
    }
    action_noise = {
        "architect", "implement", "sustain", "manage", "ensure", "enforce", "optimise", "optimize",
        "act", "offer", "offering", "partner", "align", "support", "supporting", "drive", "deliver",
        "maintain", "develop", "perform", "oversee", "lead", "collaborate", "coordinate", "conduct",
        "review", "validate", "prepare", "assign", "monitor", "supervise", "identify", "escalate",
        "proven", "solid", "regular", "internal", "cross-functional", "organisational", "organizational",
    }
    domain_cues = {
        "database", "databases", "security", "query", "performance", "cloud", "backup", "snapshot", "snapshots",
        "recovery", "access", "cost", "storage", "networking", "availability", "monitoring", "migration", "migrations",
        "architecture", "integration", "development", "implementation", "reporting", "regulatory", "risk", "compliance",
        "testing", "troubleshooting", "governance", "automation", "data", "analytics", "leadership", "stakeholder",
        "project", "product", "sales", "marketing", "finance", "financial", "accounting", "audit", "payroll",
        "recruitment", "operations", "strategy", "controls", "patching", "rightsizing", "encryption", "relational",
        "process", "processes", "standards", "administration", "tuning", "capital", "leverage", "exposures",
        "securities", "derivatives", "treasury", "reconciliation", "documentation", "workload", "coaching", "mentoring",
    }
    recognised_singletons = {
        "sap", "oracle", "netsuite", "salesforce", "python", "java", "sql", "azure", "aws", "gcp", "kubernetes",
        "docker", "linux", "powerbi", "tableau", "etl", "airflow", "spark", "hadoop", "workday", "servicenow",
        "jira", "swift", "iso20022", "reconciliation", "payroll", "treasury", "abap", "fico", "bpc", "bw", "hana",
        "devops", "recruitment", "collections", "mysql", "postgresql", "rds", "vpc", "subnets", "ec2", "encryption",
        "patching", "backup", "snapshots", "monitoring", "axiom", "ifr", "sft", "derivatives", "airb", "firb",
        "ifrs9", "rentas", "excel", "powerpoint", "word",
    }
    canonical_patterns = [
        (r"\bhighly\s+available\b|\bhigh\s+availability\b", "high availability"),
        (r"\bquery\s+tuning\b", "query tuning"),
        (r"\bperformance\s+tuning\b", "performance tuning"),
        (r"\bdatabase\s+security\b", "database security"),
        (r"\baccess\s+controls?\b", "access controls"),
        (r"\bcloud\s+monitoring\b", "cloud monitoring"),
        (r"\bbackup(?:\s*/\s*|\s+and\s+)snapshot(?:s)?(?:\s+management)?\b", "backup and snapshot management"),
        (r"\bsnapshot(?:s)?\s+management\b", "snapshot management"),
        (r"\bautomated\s+recovery\b", "automated recovery"),
        (r"\bdisaster\s+recovery\b", "disaster recovery"),
        (r"\bcloud\s+networking\b", "cloud networking"),
        (r"\bsecurity\s+groups?\b", "security groups"),
        (r"\bstorage\s+management\b", "storage management"),
        (r"\bright[- ]?sizing(?:\s+instances?)?\b", "rightsizing instances"),
        (r"\bcost[- ]saving\b|\bcost\s+optim(?:isation|ization)\b|\boptim(?:ise|ize)\s+cloud\s+expenditure\b", "cloud cost optimization"),
        (r"\brelational\s+databases?\b", "relational databases"),
        (r"\bdatabase\s+administration\b", "database administration"),
        (r"\bdatabase\s+guidance\b", "database guidance"),
        (r"\bdatabase\s+processes?\b", "database processes"),
        (r"\bec2\s*(?:-|to)\s*rds\s+migrations?\b", "EC2-to-RDS migration"),
        (r"\bp2v\s+migrations?\b", "P2V migration"),
        (r"\bregulatory\s+report(?:ing|s)\b", "regulatory reporting"),
        (r"\bcapital\s+markets?\b", "capital markets"),
        (r"\bfinancial\s+services?\b", "financial services"),
        (r"\blarge\s+exposures?\b", "large exposures"),
        (r"\bconcentration\s+risk\b", "concentration risk"),
        (r"\bcapital\s+and\s+leverage\b|\bcapital,?\s+leverage\b", "capital and leverage monitoring"),
        (r"\bcontrols?\s+and\s+procedures?\b", "controls and procedures"),
        (r"\baudit\s+documentation\b", "audit documentation"),
        (r"\bcoaching\s+and\s+mentoring\b", "coaching and mentoring"),
        (r"\bworkload\s+allocation\b", "workload allocation"),
        (r"\bmanagement\s+analytical\s+packages?\b", "management analytical packages"),
        (r"\bperformance\s+evaluations?\b", "performance evaluations"),
        (r"\baxiom\b", "Axiom"),
        (r"\bbasel\s+iii\b", "Basel III"),
        (r"\bcrd\s+v(?:\s*(?:and|&|/)\s*vi)?\b|\bcrd\s+vi\b", "CRD V/VI"),
        (r"\bsecurities\b", "securities"),
        (r"\bsft(?:['’]s|s)?\b", "SFT"),
        (r"\bderivatives?\b", "derivatives"),
        (r"\bmicrosoft\s+office\b", "Microsoft Office"),
        (r"\brisk\s+mitigation\b", "risk mitigation"),
        (r"\bprocess\s+improvement\b", "process improvement"),
        (r"\banalytical\s+thinking\b", "analytical thinking"),
    ]

    def clean_term(term):
        term = re.sub(r"^[\s\-•*:/]+", "", str(term or ""))
        term = re.sub(r"\s+", " ", term).strip().strip(".,:;()[]{}'\"")
        low = term.casefold()
        if len(term) < 2 or len(term) > 70 or low in generic or low in ignored_exact:
            return ""
        if re.fullmatch(r"gg\d{1,3}", low) or re.fullmatch(r"[ivxlcdm]+", low):
            return ""
        if _spider_ignored_fit_term(term):
            return ""
        return term

    def line_candidates(raw):
        raw = re.sub(r"^[\s\-•*]+", "", str(raw or "")).strip()
        raw = _spider_strip_jd_heading_prefix(raw)
        if not raw:
            return []
        found = []
        seen = set()

        def add(term, priority):
            term = clean_term(term)
            key = term.casefold() if term else ""
            if not term or key in seen:
                return
            seen.add(key)
            found.append((int(priority), len(found), term))

        # Mixed education/certification rows keep professional designations only.
        # Academic subjects (Finance, Accounting, Computer Science, etc.) are
        # not job-fit evidence merely because they share a row with ACCA/CFA.
        certs = certification_re.findall(raw)
        if education_line_re.search(raw):
            for cert in certs:
                add(cert.upper(), 100)
            # Corporate table extraction can place an education clause and a
            # separate technical requirement on one physical line. Remove the
            # education-bearing clauses but retain distinct semicolon, pipe or
            # sentence-delimited technical clauses instead of dropping the
            # whole row.
            clauses = [part.strip() for part in re.split(r"[;|]|(?<=[.!?])\s+", raw) if part.strip()]
            technical_clauses = [part for part in clauses if not education_line_re.search(part)]
            if not technical_clauses:
                return sorted(found, key=lambda x: (-x[0], x[1]))
            raw = " ".join(technical_clauses)
            certs = certification_re.findall(raw)
            for cert in certs:
                add(cert.upper(), 100)
        if language_line_re.search(raw):
            for cert in certs:
                add(cert.upper(), 100)
            stripped = language_line_re.sub(" ", raw)
            stripped = re.sub(
                r"\b(?:speak|speaks|spoken|written|fluent|fluency|in|and|or|with)\b", " ", stripped, flags=re.I,
            )
            raw = re.sub(r"\s+", " ", stripped).strip()
            if not raw:
                return sorted(found, key=lambda x: (-x[0], x[1]))
        else:
            for cert in certs:
                add(cert.upper(), 100)

        low_raw = raw.casefold()
        for pattern, canonical in canonical_patterns:
            if re.search(pattern, low_raw, re.I):
                add(canonical, 110)

        parts = re.split(r"[,;/|()]|\s+-\s+", raw)
        for part in parts:
            part = re.sub(r"\b(?:minimum|min\.?|at least|more than|less than)\b", "", part, flags=re.I)
            part = re.sub(r"\b\d+\+?\s*(?:years?|yrs?)\b", "", part, flags=re.I)
            words = re.findall(r"[A-Za-z][A-Za-z0-9+#.:-]*", part)
            meaningful = [
                word for word in words
                if word.casefold() not in stop_tokens and word.casefold() not in action_noise
            ]
            if not meaningful:
                continue

            for word in meaningful:
                low = word.casefold().replace(" ", "")
                if low in recognised_singletons:
                    add(word, 90)

            for size in (3, 2):
                for i in range(len(meaningful) - size + 1):
                    window = meaningful[i:i + size]
                    lows = {word.casefold() for word in window}
                    if lows & domain_cues:
                        add(" ".join(window), 60 + size)

            if 2 <= len(meaningful) <= 5 and any(
                word.casefold() in domain_cues or word.casefold().replace(" ", "") in recognised_singletons
                for word in meaningful
            ):
                add(" ".join(meaningful), 55)

        return sorted(found, key=lambda x: (-x[0], x[1]))[:8]

    def balanced_select(lines, limit):
        per_line = [line_candidates(line) for line in lines]
        per_line = [items for items in per_line if items]
        selected = []
        selected_keys = set()

        def take(term):
            key = term.casefold()
            if key not in selected_keys and len(selected) < limit:
                selected_keys.add(key)
                selected.append(term)

        # First retain one best concept from every meaningful line.
        for items in per_line:
            if len(selected) >= limit:
                break
            take(items[0][2])

        # Then fill remaining capacity by evidence priority across all lines.
        rest = []
        for line_index, items in enumerate(per_line):
            for item_index, (priority, _order, term) in enumerate(items[1:], start=1):
                rest.append((-priority, line_index, item_index, term))
        for _neg_priority, _line_index, _item_index, term in sorted(rest):
            if len(selected) >= limit:
                break
            take(term)
        return selected

    max_terms = max(1, int(max_terms or 1))
    nice_budget = min(8, max(2, max_terms // 7)) if groups.get("nice") else 0
    core_limit = max_terms - nice_budget
    output = balanced_select(groups.get("core") or [], core_limit)
    if groups.get("nice") and len(output) < max_terms:
        nice_terms = balanced_select(groups.get("nice") or [], min(nice_budget, max_terms - len(output)))
        seen = {term.casefold() for term in output}
        for term in nice_terms:
            if term.casefold() not in seen and len(output) < max_terms:
                seen.add(term.casefold())
                output.append(term)
    return output[:max_terms]

def _spider_ignored_fit_term(term):
    """True for language/education criteria that must never affect match-fit %."""
    text = str(term or "").strip().lower()
    if not text:
        return True
    return re.search(
        r"\b(language|languages|linguistic|fluent|fluency|spoken|written|bilingual|multilingual|"
        r"english|mandarin|chinese|cantonese|hokkien|hakka|teochew|malay|bahasa|japanese|korean|thai|"
        r"vietnamese|tagalog|filipino|indonesian|degree|diploma|bachelor|master|masters|phd|doctorate|"
        r"university|college|education|academic|cgpa|gpa|spm|stpm)\b",
        text,
        re.I,
    ) is not None


def _spider_strip_context_fit_term(term, filters=None):
    """Remove pure location/work-mode metadata without damaging technical phrases.

    Standalone values such as ``Kuala Lumpur`` or ``On-site`` are not fit
    evidence.  Embedded technical concepts such as ``Hybrid Cloud``, ``Remote
    Desktop Services`` and ``remote sensing`` must remain intact.
    """
    text = re.sub(r"\s+", " ", str(term or "")).strip()
    if not text:
        return ""
    filters = filters if isinstance(filters, dict) else {}
    location_terms = set()
    for definition in _SPIDER_COUNTRY_DEFINITIONS.values():
        for value in list(definition.get("names") or []) + list(definition.get("places") or []):
            value = re.sub(r"\s+", " ", str(value or "")).strip().lower()
            if value:
                location_terms.add(value)
    for value in (filters.get("country"), filters.get("city_state"), filters.get("location")):
        value = re.sub(r"\s+", " ", str(value or "")).strip().lower()
        if value and value != "any":
            location_terms.add(value)

    cleaned = text
    cleaned = re.sub(
        r"\b(?:location|located|city|state|country|postcode|postal code)\s*[:=-]?\s*",
        " ", cleaned, flags=re.I,
    )
    cleaned = re.sub(r"\b(?:based|located)\s+in\b", " ", cleaned, flags=re.I)

    # Preserve well-known technical uses of hybrid/remote before stripping work
    # arrangements.  The placeholders contain only ASCII word characters and
    # are restored after location cleanup.
    protected = []
    tech_pattern = re.compile(
        r"\b(?:hybrid\s+(?:cloud|infrastructure|architecture|network|environment|database|systems?|integration|deployment)|"
        r"remote\s+(?:desktop(?:\s+services?)?|sensing|access|monitoring|management|administration|support|operations|backup|database|servers?|systems?))\b",
        re.I,
    )
    def protect(match):
        protected.append(match.group(0))
        return "TECHWORKMODETOKEN{}".format(len(protected) - 1)
    cleaned = tech_pattern.sub(protect, cleaned)
    cleaned = re.sub(
        r"\b(?:on[ -]?site|onsite|office[ -]?based|work(?:ing)? from (?:the )?office|"
        r"remote|work from home|wfh|hybrid|flexible work(?:ing)?|work arrangement|work mode)\b",
        " ", cleaned, flags=re.I,
    )
    for i, original in enumerate(protected):
        cleaned = cleaned.replace("TECHWORKMODETOKEN{}".format(i), original)

    for location in sorted(location_terms, key=len, reverse=True):
        cleaned = re.sub(r"(?<!\w)" + re.escape(location) + r"(?!\w)", " ", cleaned, flags=re.I)
    cleaned = re.sub(r"[|,/;:()\[\]{}]+", " ", cleaned)
    cleaned = re.sub(r"(?:^|\s)[-–—]+(?:\s|$)", " ", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" -–—|,;/:")
    if cleaned.lower() in {
        "location", "work", "working", "arrangement", "mode", "setup",
        "on site", "onsite", "remote", "hybrid", "wfh", "office based",
    }:
        return ""
    return cleaned

def _spider_context_only_fit_term(term, filters=None):
    """True when a fit term contains only location/work-arrangement context."""
    return not bool(_spider_strip_context_fit_term(term, filters))



def _spider_boolean_tokens(rule_text):
    """Tokenize recruiter Boolean syntax for both text and JobAdder set evaluation."""
    raw = str(rule_text or "").replace("“", '"').replace("”", '"').replace("‘", "'").replace("’", "'")
    raw = re.sub(r"[,;\n\r|]+", " OR ", raw)
    token_re = re.compile(r'"([^\"]+)"|\'([^\']+)\'|(\()|(\))|\b(AND|OR|NOT)\b|([^\s()]+)', re.I)
    tokens = []
    for m in token_re.finditer(raw):
        quoted_double, quoted_single, lp, rp, op, bare = m.groups()
        if quoted_double is not None or quoted_single is not None:
            term = (quoted_double if quoted_double is not None else quoted_single).strip()
            if term:
                tokens.append(("TERM", term))
        elif lp:
            tokens.append(("LP", lp))
        elif rp:
            tokens.append(("RP", rp))
        elif op:
            tokens.append((op.upper(), op.upper()))
        elif bare:
            term = bare.strip().strip('"\'')
            if term:
                tokens.append(("TERM", term))
    if not tokens:
        return []

    # Adjacent atoms keep the earlier recall-oriented OR behaviour.
    expanded = []
    prev_type = None
    for tok in tokens:
        typ = tok[0]
        if prev_type in {"TERM", "RP"} and typ in {"TERM", "LP", "NOT"}:
            expanded.append(("OR", "OR"))
        expanded.append(tok)
        prev_type = typ
    return expanded


def _spider_boolean_terms(rule_text, max_terms=16):
    """Return unique Boolean atoms in recruiter order, excluding operators."""
    out, seen = [], set()
    for typ, val in _spider_boolean_tokens(rule_text):
        if typ != "TERM":
            continue
        term = re.sub(r"\s+", " ", str(val or "")).strip()
        if len(term) < 2 or len(term) > 100:
            continue
        key = term.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(term)
        if len(out) >= max_terms:
            break
    return out


def _spider_boolean_expression_match(blob_low, rule_text, proven_terms=None):
    """Evaluate recruiter Boolean syntax against profile text plus JobAdder-proven terms.

    ``proven_terms`` are terms JobAdder itself confirmed through separate latest-resume
    keyword searches. This is essential because the candidate detail endpoint often does
    not expose the full resume text that the Keywords endpoint searched.
    """
    tokens = _spider_boolean_tokens(rule_text)
    if not tokens:
        return True, [], []

    proven = {re.sub(r"\s+", " ", str(x or "")).strip().lower() for x in (proven_terms or []) if str(x or "").strip()}
    precedence = {"OR": 1, "AND": 2, "NOT": 3}
    output = []
    ops = []
    for tok in tokens:
        typ = tok[0]
        if typ == "TERM":
            output.append(tok)
        elif typ in precedence:
            while ops and ops[-1][0] in precedence and (
                precedence[ops[-1][0]] > precedence[typ]
                or (typ != "NOT" and precedence[ops[-1][0]] == precedence[typ])
            ):
                output.append(ops.pop())
            ops.append(tok)
        elif typ == "LP":
            ops.append(tok)
        elif typ == "RP":
            while ops and ops[-1][0] != "LP":
                output.append(ops.pop())
            if ops and ops[-1][0] == "LP":
                ops.pop()
    while ops:
        op = ops.pop()
        if op[0] not in {"LP", "RP"}:
            output.append(op)

    stack = []
    hits = []
    missing = []
    for typ, val in output:
        if typ == "TERM":
            key = re.sub(r"\s+", " ", str(val or "")).strip().lower()
            found = key in proven or bool(_spider_hit_terms(blob_low, [val]))
            stack.append(found)
            if found:
                hits.append(val)
            else:
                missing.append(val)
        elif typ == "NOT":
            stack.append(not stack.pop() if stack else True)
        elif typ in {"AND", "OR"}:
            right = stack.pop() if stack else False
            left = stack.pop() if stack else False
            stack.append((left and right) if typ == "AND" else (left or right))
    return (bool(stack[-1]) if stack else False), hits, missing


def _spider_discovery_keyword_match(blob_low, rule_text, strict=False, proven_terms=None):
    """Return (matched, evidence, missing) for keyword discovery.

    JobAdder performs latest-resume keyword discovery. CV Studio verifies recruiter
    Boolean logic using both visible candidate/profile text and the exact atomic terms
    proven by the JobAdder Keywords searches.
    """
    raw = str(rule_text or "").strip()
    if not raw:
        return True, [], []
    proven_terms = list(proven_terms or [])
    negatives = _spider_boolean_not_terms(raw, 18)
    negative_hits = _spider_hit_terms(blob_low, negatives)
    proven_low = {re.sub(r"\s+", " ", str(x or "")).strip().lower() for x in proven_terms}
    negative_hits.extend([t for t in negatives if str(t).strip().lower() in proven_low and t not in negative_hits])
    if negative_hits:
        return False, [], ["excluded keyword: " + ", ".join(negative_hits[:5])]

    has_boolean = re.search(r"\b(AND|OR|NOT)\b|[()\"']", raw, re.I) is not None
    if has_boolean:
        matched, hits, missing = _spider_boolean_expression_match(blob_low, raw, proven_terms=proven_terms)
        if not matched:
            return False, hits, ["Boolean rule not satisfied" + ((": " + ", ".join(missing[:6])) if missing else "")]
        return True, hits, []

    positives = _spider_terms(raw, 36)
    hits = _spider_hit_terms(blob_low, positives)
    for t in positives:
        if str(t).strip().lower() in proven_low and t not in hits:
            hits.append(t)
    if not positives:
        return True, [], []
    if strict:
        missing = [t for t in positives if t not in hits]
        if missing:
            return False, hits, ["missing keyword: " + ", ".join(missing[:6])]
    elif not hits:
        return False, [], ["no Boolean/keyword evidence visible"]
    return True, hits, []


def _spider_term_coverage(blob_low, term):
    """Return 0..1 evidence coverage for one phrase without substring noise."""
    if _spider_term_matches(blob_low, term):
        return 1.0
    words = [w for w in re.findall(r"[A-Za-z0-9+#.]+", str(term or "")) if len(w) > 1]
    if len(words) < 2:
        return 0.0
    matched = 0
    for word in words:
        variants = [word]
        if len(word) > 4 and word.lower().endswith("s"):
            variants.append(word[:-1])
        if any(_spider_term_matches(blob_low, v) for v in variants):
            matched += 1
    coverage = matched / float(len(words))
    # A failed two-word phrase must never receive credit from one generic token
    # (for example AWS alone must not satisfy "AWS RDS"). If both words are
    # visible but non-adjacent, retain conservative partial credit.
    if len(words) == 2:
        return 0.75 if matched == 2 else 0.0
    # One generic token from a longer phrase is too weak to count as evidence.
    if matched < 2:
        return 0.0
    return coverage if coverage >= 0.5 else 0.0


def _spider_weighted_coverage(blob_low, terms):
    """Return weighted coverage, summary hits, clean terms and per-term evidence."""
    clean = []
    seen = set()
    for term in terms or []:
        t = re.sub(r"\s+", " ", str(term or "")).strip()
        if not t or _spider_ignored_fit_term(t):
            continue
        key = t.lower()
        if key in seen:
            continue
        seen.add(key)
        clean.append(t)
    if not clean:
        return None, [], [], []
    hits = []
    details = []
    total = 0.0
    earned = 0.0
    for term in clean:
        words = re.findall(r"[A-Za-z0-9+#.]+", term)
        weight = 2.0 if len(words) >= 2 else (1.6 if re.match(r"^[A-Z0-9+#.]{2,}$", term) else 1.0)
        coverage = _spider_term_coverage(blob_low, term)
        total += weight
        earned += coverage * weight
        status = "exact" if coverage >= 0.999 else ("partial" if coverage >= 0.5 else "missing")
        details.append({
            "term": term,
            "coverage": round(float(coverage), 4),
            "weight": round(float(weight), 2),
            "status": status,
        })
        if coverage >= 0.5:
            hits.append(term if coverage >= 0.999 else term + " (partial)")
    return (earned / total if total else 0.0), hits, clean, details

def _spider_match_fit_percent(candidate, filters, blob_low, discovery_hits):
    """Calculate a normalized 0-100 job-fit percentage with an auditable breakdown."""
    components = []
    evidence = []
    unknown = []

    jd_terms = []
    for term in _spider_jd_relevance_terms(filters.get("jd") or filters.get("job_description"), 56):
        cleaned_term = _spider_strip_context_fit_term(term, filters)
        if cleaned_term:
            jd_terms.append(cleaned_term)
    jd_cov, jd_hits, _jd_clean, jd_details = _spider_weighted_coverage(blob_low, jd_terms)

    must_raw = filters.get("must") or filters.get("boolean") or ""
    must_terms = []
    for term in _spider_boolean_positive_terms(must_raw, 28):
        cleaned_term = _spider_strip_context_fit_term(term, filters)
        if cleaned_term and not _spider_ignored_fit_term(cleaned_term):
            must_terms.append(cleaned_term)
    if not must_terms and must_raw:
        for term in _spider_terms(must_raw, 28):
            cleaned_term = _spider_strip_context_fit_term(term, filters)
            if cleaned_term and not _spider_ignored_fit_term(cleaned_term):
                must_terms.append(cleaned_term)
    must_cov, must_hits, _must_clean, must_details = _spider_weighted_coverage(blob_low, must_terms)
    native_confirmed = bool(candidate.get("_spiderNativeBooleanMatched")) if isinstance(candidate, dict) else False
    native_floor_applied = False
    if must_cov is not None and native_confirmed and must_cov < 0.60:
        must_cov = 0.60
        native_floor_applied = True

    role_terms = []
    for term in _spider_terms(filters.get("role"), 10):
        cleaned_term = _spider_strip_context_fit_term(term, filters)
        if cleaned_term and not _spider_ignored_fit_term(cleaned_term):
            role_terms.append(cleaned_term)
    role_cov, role_hits, _role_clean, role_details = _spider_weighted_coverage(blob_low, role_terms)

    nice_terms = []
    for term in _spider_terms(filters.get("nice"), 18):
        cleaned_term = _spider_strip_context_fit_term(term, filters)
        if cleaned_term and not _spider_ignored_fit_term(cleaned_term):
            nice_terms.append(cleaned_term)
    nice_cov, nice_hits, _nice_clean, nice_details = _spider_weighted_coverage(blob_low, nice_terms)

    def add_component(key, label, coverage, base_weight, hits, term_details, missing_message):
        if coverage is None:
            return
        components.append({
            "key": key,
            "label": label,
            "coverage": float(coverage),
            "base_weight": float(base_weight),
            "hits": list(hits or []),
            "terms": list(term_details or []),
        })
        if hits:
            evidence_label = {
                "jd": "Job scope/requirements",
                "must": "Must-have/Boolean",
                "role": "Role alignment",
                "nice": "Additional requirements",
            }.get(key, label)
            evidence.append(evidence_label + ": " + ", ".join(list(hits)[:8]))
        elif key == "must" and native_confirmed:
            evidence.append("JobAdder confirmed the recruiter Boolean against the latest resume")
        else:
            unknown.append(missing_message)

    add_component("jd", "JD requirements", jd_cov, 55.0, jd_hits, jd_details, "JD scope/requirements not visible")
    add_component("must", "Boolean / must-have", must_cov, 25.0 if jd_cov is not None else 50.0, must_hits, must_details, "must-have evidence not visible")
    add_component("role", "Target-role alignment", role_cov, 10.0 if jd_cov is not None else 30.0, role_hits, role_details, "target role not visible")
    add_component("nice", "Nice-to-have", nice_cov, 10.0 if jd_cov is not None else 20.0, nice_hits, nice_details, "additional requirements not visible")

    total_weight = sum(item["base_weight"] for item in components)
    raw_percent = int(round(sum(item["coverage"] * item["base_weight"] for item in components) / total_weight * 100.0)) if total_weight else 0
    percent = raw_percent
    discovery_floor_applied = False
    if components:
        if discovery_hits and percent < 10:
            percent = 10
            discovery_floor_applied = True
            evidence.append("Keyword discovery: " + ", ".join(discovery_hits[:8]))
            unknown.append("JobAdder confirmed discovery, but visible job-fit evidence is limited")
    elif discovery_hits:
        percent = 10
        discovery_floor_applied = True
        evidence.append("Keyword discovery: " + ", ".join(discovery_hits[:8]))
        unknown.append("No JD/role/must-have scope supplied; showing minimum discovery fit")
    else:
        percent = 0
        unknown.append("No usable job-scope criteria supplied")

    component_rows = []
    for item in components:
        max_points = (item["base_weight"] / total_weight * 100.0) if total_weight else 0.0
        points = item["coverage"] * max_points
        terms = item.get("terms") or []
        component_rows.append({
            "key": item["key"],
            "label": item["label"],
            "coverage_percent": int(round(item["coverage"] * 100.0)),
            "points": round(points, 1),
            "max_points": round(max_points, 1),
            "matched": [x.get("term") for x in terms if x.get("status") == "exact"][:12],
            "partial": [x.get("term") for x in terms if x.get("status") == "partial"][:12],
            "missing": [x.get("term") for x in terms if x.get("status") == "missing"][:12],
            "native_boolean_floor": bool(item["key"] == "must" and native_floor_applied),
        })

    breakdown = {
        "method": "normalized_weighted_coverage_v2",
        "components": component_rows,
        "raw_percent": max(0, min(100, raw_percent)),
        "final_percent": max(0, min(100, percent)),
        "discovery_floor_applied": discovery_floor_applied,
        "native_boolean_floor_applied": native_floor_applied,
        "excluded_from_score": ["location", "work arrangement", "language", "education", "salary", "industry", "target companies"],
    }
    return max(0, min(100, percent)), evidence[:10], unknown[:8], breakdown

def _spider_item_score(candidate, filters, enriched=False):
    """Return (keep, fit_percent, fit evidence, unknown, excluded, hard_passed, discovery evidence).

    Stage 1 discovers candidates by Boolean Rules / Keywords (when supplied),
    plus explicit hard filters. The JD is not used to decide discovery eligibility.
    Stage 2 scores the remaining candidate 0-100 against job scope/requirements,
    omitting language and education, and keeps candidates from 10% upward.
    """
    filters = filters if isinstance(filters, dict) else {}
    blob = _spider_candidate_blob(candidate)
    blob_low = blob.lower()
    unknown, excluded, hard_passed = [], [], []

    # Only the separate Exclude/Avoid field is rechecked locally.
    # Native JobAdder Boolean rules (including NOT) are trusted as returned and are
    # never re-evaluated against the incomplete candidate-detail JSON.
    exclude_terms = _spider_terms(filters.get("exclude") or filters.get("avoid"), 24)
    hit_excludes = _spider_hit_terms(blob_low, exclude_terms)
    if hit_excludes:
        return False, 0, [], unknown, ["exclude: " + ", ".join(hit_excludes[:5])], hard_passed, []

    # A Boolean fallback searches positive atoms only. If a NOT operand is visibly
    # present in the available profile data, exclude it conservatively; absence is
    # kept as unknown because JobAdder detail JSON may omit resume text.
    fallback_negative_terms = list(candidate.get("_spiderBooleanNegativeTerms") or []) if isinstance(candidate, dict) else []
    if candidate.get("_spiderBooleanFallback") if isinstance(candidate, dict) else False:
        fallback_negative_hits = _spider_hit_terms(blob_low, fallback_negative_terms)
        if fallback_negative_hits:
            return False, 0, [], unknown, ["Boolean NOT match: " + ", ".join(fallback_negative_hits[:5])], hard_passed, []
        if fallback_negative_terms:
            unknown.append("Boolean NOT terms not fully visible in available profile data")

    def hard_filter_terms(label, value, max_terms=24, require_all=False):
        terms = _spider_terms(value, max_terms)
        if not terms:
            return []
        hits = _spider_hit_terms(blob_low, terms)
        missing = [t for t in terms if t not in hits]
        if require_all and missing:
            raise ValueError("missing hard filter {}: {}".format(label, ", ".join(missing[:5])))
        if not hits:
            if not enriched and not bool(filters.get("strict")):
                unknown.append("{} not visible in list result".format(label))
                return []
            raise ValueError("missing hard filter {}".format(label))
        hard_passed.append(label + ": " + ", ".join(hits[:5]))
        return hits

    # Existing explicit hard filters remain eligibility gates, not fit-score points.
    try:
        hard_filter_terms("IT skills", filters.get("it_skills") or filters.get("skills"), 24, bool(filters.get("strict")))
        hard_filter_terms("qualifications", filters.get("qualifications"), 18, False)
    except ValueError as e:
        return False, 0, [], unknown, [str(e)], hard_passed, []

    country = str(filters.get("country") or "").strip()
    if country and country.lower() != "any":
        country_result, country_evidence = _spider_country_match(candidate, country)
        if country_result == "match":
            hard_passed.append("country: " + country)
        elif country_result == "mismatch":
            return False, 0, [], unknown, ["country mismatch: " + (country_evidence or country)[:100]], hard_passed, []
        elif not enriched and not bool(filters.get("strict")):
            unknown.append("country not visible in list result")
        else:
            return False, 0, [], unknown, ["country not visible"], hard_passed, []

    residential = str(filters.get("residential") or "Any").strip()
    if residential and residential.lower() != "any":
        res_text = _spider_residential_status_text(candidate)
        target_status = _spider_status_target(residential)
        visible_statuses = _spider_residential_classes(res_text)
        if target_status and target_status in visible_statuses:
            hard_passed.append("residential: " + residential)
        elif visible_statuses:
            return False, 0, [], unknown, ["residential mismatch: " + res_text[:100]], hard_passed, []
        elif not enriched and not bool(filters.get("strict")):
            unknown.append("residential status not visible in list result")
        else:
            return False, 0, [], unknown, ["residential status not visible"], hard_passed, []

    min_years, max_years = _spider_years_bounds(filters)
    if min_years > 0 or max_years is not None:
        visible_years = _spider_visible_years(candidate)
        if visible_years is None:
            unknown.append("years experience not visible")
        else:
            visible_label = ("{:.1f}".format(float(visible_years))).rstrip("0").rstrip(".")
            if float(visible_years) < float(min_years):
                return False, 0, [], unknown, ["years experience below minimum {}: {}".format(min_years, visible_label)], hard_passed, []
            if max_years is not None and float(visible_years) > float(max_years):
                return False, 0, [], unknown, ["years experience above maximum {}: {}".format(max_years, visible_label)], hard_passed, []
            if max_years is None:
                hard_passed.append("experience: {} years visible (minimum {}+)".format(visible_label, min_years))
            elif min_years > 0:
                hard_passed.append("experience: {} years visible (range {}-{})".format(visible_label, min_years, max_years))
            else:
                hard_passed.append("experience: {} years visible (maximum {})".format(visible_label, max_years))

    native_boolean_match = bool(candidate.get("_spiderNativeBooleanMatched")) if isinstance(candidate, dict) else False
    plain_fallback_match = bool(candidate.get("_spiderBooleanFallback")) if isinstance(candidate, dict) else False
    native_boolean_rule = str(candidate.get("_spiderBooleanRule") or filters.get("must") or filters.get("boolean") or "").strip() if isinstance(candidate, dict) else str(filters.get("must") or filters.get("boolean") or "").strip()
    if native_boolean_match:
        # JobAdder's candidate Keywords search is the discovery authority. The detail
        # endpoint may omit the latest-resume text, so do not re-test the rule locally.
        discovery_ok = True
        discovery_hits = [native_boolean_rule] if native_boolean_rule else ["JobAdder native Boolean match"]
        discovery_missing = []
    elif plain_fallback_match:
        # The original Boolean returned zero rows. These rows came from the explicit,
        # labelled plain-keyword fallback, so do not re-evaluate the Boolean (especially
        # NOT terms) against incomplete candidate JSON or synthetic proven-term lists.
        discovery_ok = True
        discovery_hits = list(candidate.get("_spiderSearchTerms") or []) if isinstance(candidate, dict) else []
        if not discovery_hits:
            discovery_hits = ["JobAdder plain-keyword fallback match"]
        discovery_missing = []
    else:
        proven_terms = candidate.get("_spiderSearchTerms", []) if isinstance(candidate, dict) else []
        discovery_ok, discovery_hits, discovery_missing = _spider_discovery_keyword_match(
            blob_low,
            filters.get("must") or filters.get("boolean") or "",
            bool(filters.get("strict")),
            proven_terms=proven_terms,
        )
    if not discovery_ok:
        return False, 0, [], unknown, discovery_missing, hard_passed, discovery_hits

    fit_percent, fit_evidence, fit_unknown, fit_breakdown = _spider_match_fit_percent(candidate, filters, blob_low, discovery_hits)
    unknown.extend(fit_unknown)
    if filters.get("salary"):
        unknown.append("salary not used in fit score")
    if filters.get("industry"):
        unknown.append("industry not used in fit score")
    if filters.get("targets"):
        unknown.append("target companies not used in fit score")

    if fit_percent < 10:
        return False, fit_percent, fit_evidence, unknown[:8], ["match fit below 10%"], hard_passed[:8], discovery_hits[:10], fit_breakdown
    return True, fit_percent, fit_evidence[:10], unknown[:8], excluded, hard_passed[:8], discovery_hits[:10], fit_breakdown

def _spider_option_fallbacks(name):
    key = str(name or "").strip().lower()
    if key in {"industry", "industries"}:
        return ["Banking", "Financial Services", "Fintech", "Shared Services", "Technology", "Telecommunications", "Manufacturing", "FMCG", "Healthcare", "Retail", "E-commerce", "Consulting"]
    if key in {"it_skills", "it skills", "skill", "skills", "technical_skills"}:
        return ["SAP", "SAP ABAP", "SAP FICO", "SAP BW", "SAP BPC", "Oracle", "NetSuite", "Salesforce", "Python", "Java", "AWS", "Azure", "GCP", "Kubernetes", "Docker", "SQL", "Power BI", "Tableau"]
    if key in {"qualifications", "qualification", "certifications"}:
        return ["ACCA", "CPA", "CIMA", "MIA", "ICAEW", "CFA", "CIA", "PMP", "PRINCE2", "ITIL", "CKA", "AWS Certified", "Azure Certified", "SAP Certified"]
    return []


def _spider_extract_option_values(payload):
    values = []
    seen = set()
    def add(v):
        if isinstance(v, dict):
            for k in ["name", "label", "value", "title", "text", "displayName"]:
                if v.get(k):
                    return add(v.get(k))
            return
        txt = re.sub(r"\s+", " ", str(v or "")).strip()
        if not txt or len(txt) > 120:
            return
        k = txt.lower()
        if k not in seen:
            seen.add(k); values.append(txt)
    def walk(x, depth=0):
        if depth > 4 or x is None:
            return
        if isinstance(x, list):
            for item in x[:300]:
                walk(item, depth+1)
        elif isinstance(x, dict):
            for key in ["items", "values", "valueList", "data", "list", "records", "options"]:
                if isinstance(x.get(key), list):
                    walk(x.get(key), depth+1)
            if any(k in x for k in ["name", "label", "value", "title", "text", "displayName"]):
                add(x)
        else:
            add(x)
    walk(payload)
    return values[:250]



_AI_CRAWLER_LOCK_CODE = "1571"

def _ai_crawler_lock_allowed(body=None):
    """Casual local lock guard for AI Crawler routes.

    This mirrors the Lead Finder local access gate. It is not enterprise
    authentication, but prevents accidental/casual use through the UI and
    direct local route calls.
    """
    try:
        body = body if isinstance(body, dict) else {}
        supplied = (
            request.headers.get("X-AI-Crawler-Code")
            or body.get("crawler_lock_code")
            or request.args.get("crawler_lock_code")
            or ""
        )
        return str(supplied).strip() == _AI_CRAWLER_LOCK_CODE
    except Exception:
        return False


def _ai_crawler_locked_response():
    return _cvstudio_error_payload("AI_CRAWLER_LOCKED", "AI Crawler is locked. Unlock the AI Crawler tab with the 4-digit code first.", 423, action="unlock_feature")

@app.route("/jobadder/spider_options", methods=["GET"])
def jobadder_spider_options():
    """Best-effort JobAdder dropdown/options lookup for AI Crawler filters, with safe fallbacks."""
    if not _ai_crawler_lock_allowed():
        return _ai_crawler_locked_response()
    name = str(request.args.get("name") or "").strip().lower()
    fallback = _spider_option_fallbacks(name)
    token = _ja_refresh_access_token(force=False)
    if not token:
        return jsonify({"items": fallback, "fallback": True})
    candidate_lists = {
        "industry": ["industry", "industries", "candidateIndustry", "candidateIndustries"],
        "industries": ["industry", "industries", "candidateIndustry", "candidateIndustries"],
        "it_skills": ["skills", "skill", "candidateSkills", "candidateSkill", "itSkills", "it_skills", "technologySkills"],
        "skills": ["skills", "skill", "candidateSkills", "candidateSkill", "itSkills", "technologySkills"],
        "qualifications": ["qualifications", "qualification", "candidateQualifications", "candidateQualification", "certifications"],
        "qualification": ["qualifications", "qualification", "candidateQualifications", "candidateQualification", "certifications"],
    }.get(name, [name])
    errors = []
    for list_name in candidate_lists:
        try:
            _status, payload = _JOBADDER_CLIENT.request_json(
                "lists/" + urllib.parse.quote(list_name, safe=""),
                token=token,
                timeout=8,
                fallback={},
            )
            vals = _spider_extract_option_values(payload)
            if vals:
                return jsonify({"items": vals, "source": list_name, "fallback": False})
        except urllib.error.HTTPError as e:
            errors.append("{}:{}".format(list_name, e.code))
        except Exception as e:
            errors.append("{}:{}".format(list_name, str(e)[:80]))
    return jsonify({"items": fallback, "fallback": True, "tried": candidate_lists, "errors": errors[:6]})



def _spider_preview_name(candidate_id, detail=None):
    if isinstance(detail, dict):
        for key in ["name", "fullName", "displayName"]:
            if detail.get(key):
                return str(detail.get(key))[:160]
        first = str(detail.get("firstName") or "").strip()
        last = str(detail.get("lastName") or "").strip()
        if first or last:
            return (first + " " + last).strip()[:160]
    return "Candidate " + str(candidate_id or "")[:40]


def _spider_preview_text_from_detail(detail):
    """Build a readable side preview from a JobAdder candidate record if no raw resume is available."""
    if not isinstance(detail, dict):
        return ""
    sections = []
    name = _spider_preview_name("", detail)
    title = detail.get("currentPosition") or detail.get("position") or detail.get("jobTitle") or ""
    company = detail.get("currentCompany") or detail.get("employer") or ""
    location = detail.get("location") or detail.get("city") or detail.get("country") or ""
    header = []
    if name and name != "Candidate ":
        header.append("Name: " + str(name))
    if title or company:
        header.append("Current: " + " @ ".join([str(x) for x in [title, company] if x]))
    if location:
        header.append("Location: " + str(location))
    if header:
        sections.append("\n".join(header))

    preferred = [
        ("Summary", ["summary", "profile", "candidateSummary", "objective"]),
        ("Skills", ["skills", "skill", "itSkills", "technologySkills"]),
        ("Qualifications", ["qualifications", "qualification", "certifications", "certification"]),
        ("Employment", ["employment", "workExperience", "experience", "positions", "history"]),
        ("Education", ["education", "educations"]),
        ("Resume / CV", ["resume", "cv", "curriculumVitae"]),
        ("Notes", ["notes", "comments"]),
    ]

    def compact(v):
        if v is None or v == "" or v == [] or v == {}:
            return ""
        if isinstance(v, str):
            out = v
        else:
            try:
                out = json.dumps(v, ensure_ascii=False, indent=2)
            except Exception:
                out = str(v)
        out = re.sub(r"\n{3,}", "\n\n", out)
        return out.strip()[:5000]

    used = set()
    lower_map = {str(k).lower(): k for k in detail.keys()}
    for title_label, keys in preferred:
        vals = []
        for key in keys:
            for lk, real in lower_map.items():
                if key.lower() in lk and real not in used:
                    txt = compact(detail.get(real))
                    if txt:
                        vals.append(txt)
                        used.add(real)
        if vals:
            sections.append(title_label + "\n" + "\n\n".join(vals)[:6500])
    if not sections:
        blob = _spider_candidate_blob(detail)
        return blob[:9000]
    return "\n\n".join(sections)[:12000]



def _spider_is_legacy_word_doc_bytes(raw):
    """Detect legacy binary Word .doc downloads even when JobAdder labels them octet-stream.

    Browser preview cannot embed .doc directly, so Spider must first recognise old
    OLE Word files, then convert or fall back to extracted text.
    """
    raw = raw or b""
    if not raw.startswith(b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1"):
        return False
    try:
        import olefile as _olefile
        ole = _olefile.OleFileIO(io.BytesIO(raw))
        try:
            return ole.exists('WordDocument')
        finally:
            ole.close()
    except Exception:
        # Still let LibreOffice/antiword try it; JobAdder often serves legacy .doc
        # as generic application/octet-stream without a usable filename.
        return True


def _spider_clean_doc_text_for_preview(text):
    text = str(text or '')
    text = text.replace('\r', '\n').replace('\x07', ' | ')
    text = re.sub(r'[\x00-\x06\x08\x0b\x0c\x0e-\x1f\x7f-\x9f]+', ' ', text)
    text = re.sub(r'[ \t]{2,}', ' ', text)
    text = re.sub(r' *\| *\| *', ' | ', text)
    text = re.sub(r'\n[ \t]+', '\n', text)
    text = re.sub(r'\n{3,}', '\n\n', text)
    return text.strip()


def _spider_doc_text_quality_ok(text):
    text = _spider_clean_doc_text_for_preview(text)
    if len(text) < 80:
        return False
    sample = text[:6000]
    visible = sum(1 for c in sample if not c.isspace()) or 1
    bad = sum(1 for c in sample if (ord(c) > 0xFFFF) or (ord(c) >= 0x3000 and not ('\u4e00' <= c <= '\u9fff')))
    signals = len(re.findall(r'(?i)\b(name|email|e-mail|phone|mobile|experience|education|skills|work|project|position|summary|profile)\b|@', sample))
    return (bad / visible) < 0.25 and signals >= 1


def _spider_extract_legacy_doc_text_for_preview(raw):
    """Best-effort text fallback for legacy .doc Spider previews.

    Used only for JobAdder side preview when visual .doc-to-PDF conversion is not
    possible. It mirrors the safer extraction order used by the normal upload
    path: antiword, LibreOffice text, native WordDocument piece table, then raw scans.
    """
    raw = raw or b''
    if not raw:
        return ''

    # 1) antiword, if bundled/installed.
    try:
        import tempfile as _tmp, subprocess as _sp, os as _os
        for antiword in _iter_antiword_binaries():
            with _tmp.TemporaryDirectory() as td:
                doc_path = _os.path.join(td, 'input.doc')
                with open(doc_path, 'wb') as fh:
                    fh.write(raw)
                aw_folder = _os.path.dirname(_os.path.abspath(antiword))
                res = _sp.run([antiword, doc_path], capture_output=True, timeout=20, cwd=aw_folder or None, env=_antiword_env_for_binary(antiword))
                if res.returncode == 0:
                    for enc in ('utf-8', 'cp1252', 'latin-1'):
                        txt = _spider_clean_doc_text_for_preview(res.stdout.decode(enc, errors='ignore'))
                        if _spider_doc_text_quality_ok(txt):
                            return txt[:12000]
    except Exception:
        pass

    # 2) LibreOffice to text, if available.
    try:
        import tempfile as _tmp, subprocess as _sp, os as _os
        soffice = _find_soffice_binary()
        if soffice:
            with _tmp.TemporaryDirectory() as td:
                doc_path = _os.path.join(td, 'input.doc')
                with open(doc_path, 'wb') as fh:
                    fh.write(raw)
                _sp.run([soffice, '--headless', '--convert-to', 'txt:Text', '--outdir', td, doc_path], capture_output=True, timeout=45)
                txt_path = _os.path.join(td, 'input.txt')
                if _os.path.exists(txt_path):
                    data = open(txt_path, 'rb').read()
                    for enc in ('utf-8', 'utf-16', 'cp1252', 'latin-1'):
                        txt = _spider_clean_doc_text_for_preview(data.decode(enc, errors='ignore'))
                        if _spider_doc_text_quality_ok(txt):
                            return txt[:12000]
    except Exception:
        pass

    # 3) Native OLE WordDocument piece table.
    try:
        import struct as _struct
        import olefile as _olefile
        ole = _olefile.OleFileIO(io.BytesIO(raw))
        try:
            if ole.exists('WordDocument'):
                word = ole.openstream('WordDocument').read()
                flags = _struct.unpack_from('<H', word, 0x0A)[0]
                table_name = '1Table' if (flags & 0x0200) else '0Table'
                if ole.exists(table_name) and len(word) >= 0x01AA:
                    table = ole.openstream(table_name).read()
                    fc_clx = _struct.unpack_from('<I', word, 0x01A2)[0]
                    lcb_clx = _struct.unpack_from('<I', word, 0x01A6)[0]
                    clx = table[fc_clx:fc_clx + lcb_clx] if lcb_clx and fc_clx < len(table) else b''
                    pos = 0
                    pieces = []
                    while pos < len(clx):
                        b = clx[pos]
                        if b == 0x01 and pos + 3 <= len(clx):
                            cb = _struct.unpack_from('<H', clx, pos + 1)[0]
                            pos += 3 + cb
                            continue
                        if b != 0x02 or pos + 5 > len(clx):
                            pos += 1
                            continue
                        lcb = _struct.unpack_from('<I', clx, pos + 1)[0]
                        pcdt = clx[pos + 5:pos + 5 + lcb]
                        if len(pcdt) < 16:
                            break
                        n = (len(pcdt) - 4) // 12
                        if n <= 0:
                            break
                        cps = [_struct.unpack_from('<I', pcdt, i * 4)[0] for i in range(n + 1)]
                        base = 4 * (n + 1)
                        for i in range(n):
                            cp0, cp1 = cps[i], cps[i + 1]
                            if cp1 <= cp0:
                                continue
                            off = base + (i * 8)
                            if off + 6 > len(pcdt):
                                continue
                            fc_comp = _struct.unpack_from('<I', pcdt, off + 2)[0]
                            compressed = bool(fc_comp & 0x40000000)
                            fc = fc_comp & 0x3FFFFFFF
                            chars = cp1 - cp0
                            if compressed:
                                piece = word[fc // 2:(fc // 2) + chars].decode('cp1252', errors='ignore')
                            else:
                                piece = word[fc:fc + (chars * 2)].decode('utf-16-le', errors='ignore')
                            if piece:
                                pieces.append(piece)
                        break
                    txt = _spider_clean_doc_text_for_preview(''.join(pieces))
                    if _spider_doc_text_quality_ok(txt):
                        return txt[:12000]
        finally:
            ole.close()
    except Exception:
        pass

    # 4) Last resort raw scans.
    for enc in ('utf-16-le', 'cp1252', 'latin-1'):
        try:
            txt = _spider_clean_doc_text_for_preview(raw[:300000].decode(enc, errors='ignore'))
            if _spider_doc_text_quality_ok(txt):
                return txt[:12000]
        except Exception:
            pass
    return ''

def _spider_tesseract_path():
    import shutil
    script_dir = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        os.path.join(script_dir, "tesseract", "tesseract.exe"),
        r"C:\Program Files\Tesseract-OCR\tesseract.exe",
        r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
        os.path.join(os.environ.get("LOCALAPPDATA", ""), "Programs", "Tesseract-OCR", "tesseract.exe"),
        "/usr/local/bin/tesseract", "/opt/homebrew/bin/tesseract", "/usr/bin/tesseract",
    ]
    for candidate in candidates:
        if candidate and os.path.isfile(candidate):
            return candidate
    return shutil.which("tesseract") or ""


def _spider_poppler_path():
    script_dir = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        os.path.join(script_dir, "poppler", "Library", "bin"),
        os.path.join(script_dir, "poppler", "bin"),
        os.path.join(os.environ.get("PROGRAMFILES", r"C:\Program Files"), "poppler", "Library", "bin"),
        os.path.join(os.environ.get("PROGRAMFILES", r"C:\Program Files"), "poppler", "bin"),
        os.path.join(os.environ.get("PROGRAMFILES(X86)", r"C:\Program Files (x86)"), "poppler", "Library", "bin"),
        os.path.join(os.environ.get("PROGRAMFILES(X86)", r"C:\Program Files (x86)"), "poppler", "bin"),
    ]
    for candidate in candidates:
        if candidate and os.path.isdir(candidate) and (
            os.path.isfile(os.path.join(candidate, "pdfinfo.exe"))
            or os.path.isfile(os.path.join(candidate, "pdftoppm.exe"))
            or os.path.isfile(os.path.join(candidate, "pdfinfo"))
            or os.path.isfile(os.path.join(candidate, "pdftoppm"))
        ):
            return candidate
    return None


def _spider_is_image_download(raw, content_type="", filename=""):
    ctype = str(content_type or "").lower()
    name = str(filename or "").lower()
    return bool(
        ctype.startswith("image/")
        or name.endswith((".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp", ".webp"))
        or raw.startswith(b"\x89PNG\r\n\x1a\n")
        or raw.startswith(b"\xff\xd8\xff")
        or raw.startswith((b"II*\x00", b"MM\x00*", b"BM", b"RIFF"))
    )


def _spider_ocr_image_download(raw, timeout=25):
    try:
        import pytesseract
        tess = _spider_tesseract_path()
        if not tess:
            return "", "image resume found but Tesseract OCR is unavailable"
        pytesseract.pytesseract.tesseract_cmd = tess
        image = _safe_image_open(raw)
        try:
            text = _ocr_image_text(pytesseract, image, lang="eng", timeout=max(5, min(35, int(timeout or 25))))
        finally:
            try:
                image.close()
            except Exception:
                pass
        text = _spider_clean_doc_text_for_preview(text)
        if text:
            return text[:30000], "OCR text from image resume"
        return "", "image resume OCR returned no readable text"
    except Exception as exc:
        return "", "image resume OCR unavailable: " + str(exc)[:120]


def _spider_ocr_pdf_download(raw, page_limit=5, deadline_seconds=35):
    try:
        import pytesseract
        tess = _spider_tesseract_path()
        if not tess:
            return "", "scanned PDF found but Tesseract OCR is unavailable"
        pytesseract.pytesseract.tesseract_cmd = tess
        count = _pdf_page_count(raw)
        pages = min(count, max(1, min(_MAX_OCR_PAGES, int(page_limit or 5))))
        if not _OCR_SEMAPHORE.acquire(timeout=2):
            return "", "scanned PDF OCR is busy; preview remains visual only"
        started = time.monotonic()
        parts = []
        try:
            for page_number in range(1, pages + 1):
                remaining = float(deadline_seconds or 35) - (time.monotonic() - started)
                if remaining <= 2:
                    break
                images = _render_pdf_page_images(
                    raw,
                    dpi=150,
                    poppler_path=_spider_poppler_path(),
                    first_page=page_number,
                    last_page=page_number,
                    timeout=max(5, min(20, int(remaining))),
                )
                if not images:
                    continue
                image = images[0]
                try:
                    width, height = image.size
                    if width * height > _MAX_IMAGE_PIXELS:
                        continue
                    parts.append(pytesseract.image_to_string(image, lang="eng", timeout=max(5, min(18, int(remaining)))))
                finally:
                    try:
                        image.close()
                    except Exception:
                        pass
                if sum(len(x) for x in parts) >= 30000:
                    break
        finally:
            _OCR_SEMAPHORE.release()
        text = _spider_clean_doc_text_for_preview("\n".join(parts))
        if text:
            suffix = "" if pages >= count else " (first {} pages)".format(pages)
            return text[:30000], "OCR text from scanned PDF" + suffix
        return "", "scanned PDF OCR returned no readable text"
    except Exception as exc:
        return "", "scanned PDF OCR unavailable: " + str(exc)[:120]


def _spider_extract_text_from_download(raw, content_type="", filename="", ocr_page_limit=5, ocr_deadline_seconds=35, cancel_check=None):
    """Extract searchable resume text without decoding binary files as prose."""
    raw = raw or b""
    if callable(cancel_check):
        cancel_check()
    content_type = str(content_type or "").lower()
    filename = str(filename or "").lower()
    if not raw:
        return "", "empty response"

    parsed = None
    stripped = raw.lstrip()[:1]
    if "json" in content_type or stripped in (b"{", b"["):
        try:
            parsed = json.loads(raw.decode("utf-8", errors="replace"))
        except Exception:
            parsed = None
    if isinstance(parsed, (dict, list)):
        if isinstance(parsed, dict):
            for key in ["text", "plainText", "resumeText", "cvText", "content", "body", "description"]:
                if parsed.get(key) and isinstance(parsed.get(key), str):
                    return re.sub(r"\s+", " ", parsed.get(key)).strip()[:30000], "JobAdder JSON text"
            return _spider_preview_text_from_detail(parsed)[:30000], "JobAdder JSON profile"
        return re.sub(r"\s+", " ", " ".join(_spider_flatten(parsed))).strip()[:30000], "JobAdder JSON list"

    if "text" in content_type or filename.endswith((".txt", ".html", ".htm", ".csv", ".rtf")):
        try:
            text = raw.decode("utf-8", errors="replace")
        except Exception:
            text = raw.decode(errors="replace")
        text = re.sub(r"<[^>]+>", " ", text)
        text = _spider_clean_doc_text_for_preview(text)
        if text:
            return text[:30000], "downloaded text/html"
        return "", "downloaded text contained no readable content"

    is_pdf = raw.startswith(b"%PDF") or "pdf" in content_type or filename.endswith(".pdf")
    if is_pdf:
        try:
            import pdfplumber
            parts = []
            started = time.monotonic()
            with pdfplumber.open(io.BytesIO(raw)) as pdf:
                if len(pdf.pages) > _MAX_PDF_PAGES:
                    return "", "PDF exceeds the safe page limit"
                for page in pdf.pages:
                    if callable(cancel_check):
                        cancel_check()
                    if time.monotonic() - started > 25:
                        break
                    page_text = page.extract_text() or ""
                    if page_text:
                        parts.append(page_text)
                    if sum(len(x) for x in parts) >= 30000:
                        break
            text = _spider_clean_doc_text_for_preview("\n".join(parts))
            if text:
                return text[:30000], "downloaded PDF resume"
        except Exception:
            pass
        if callable(cancel_check):
            cancel_check()
        result = _spider_ocr_pdf_download(raw, page_limit=ocr_page_limit, deadline_seconds=ocr_deadline_seconds)
        if callable(cancel_check):
            cancel_check()
        return result

    if _spider_is_image_download(raw, content_type, filename):
        if callable(cancel_check):
            cancel_check()
        result = _spider_ocr_image_download(raw, timeout=min(35, int(ocr_deadline_seconds or 25)))
        if callable(cancel_check):
            cancel_check()
        return result

    if raw[:2] == b"PK" or "word" in content_type or filename.endswith(".docx"):
        try:
            if callable(cancel_check):
                cancel_check()
            text = _extract_docx_text_preserve_tables(raw)
            if callable(cancel_check):
                cancel_check()
            text = _spider_clean_doc_text_for_preview(text)
            if text:
                return text[:30000], "downloaded DOCX resume"
        except Exception:
            pass
        # A ZIP/Office payload is binary.  Never fall through to raw decoding.
        if raw[:2] == b"PK" or filename.endswith(".docx"):
            return "", "DOCX resume found but text extraction failed"

    if _spider_is_legacy_word_doc_bytes(raw) or "msword" in content_type or filename.endswith(".doc"):
        if callable(cancel_check):
            cancel_check()
        text = _spider_extract_legacy_doc_text_for_preview(raw)
        if callable(cancel_check):
            cancel_check()
        if text:
            return text[:30000], "downloaded legacy DOC resume"
        return "", "legacy DOC resume found but preview extraction failed"

    # Unknown octet-streams may genuinely be plain text, but accept them only if
    # they pass the resume-text quality check.  Known binary formats have already
    # returned above and can never be labelled as resume-scored gibberish.
    try:
        text = raw[:60000].decode("utf-8", errors="ignore")
        text = _spider_clean_doc_text_for_preview(text)
        if _spider_doc_text_quality_ok(text):
            return text[:30000], "downloaded plain-text fallback"
    except Exception:
        pass
    return "", "downloaded file is visual/binary and not text-searchable"



def _spider_filename_from_disposition(content_disposition, fallback=""):
    """Extract a filename-ish value from Content-Disposition or an attachment name."""
    txt = str(content_disposition or "")
    # RFC 5987 filename*=UTF-8''file.pdf or plain filename="file.pdf".
    m = re.search(r"filename\*\s*=\s*(?:UTF-8''|)([^;]+)", txt, re.I)
    if not m:
        m = re.search(r"filename\s*=\s*\"?([^\";]+)\"?", txt, re.I)
    if m:
        try:
            return urllib.parse.unquote(m.group(1).strip().strip('"'))[:180]
        except Exception:
            return m.group(1).strip().strip('"')[:180]
    return str(fallback or "")[:180]


def _spider_pdf_text_layer_from_pdfium(textpage, page_width, page_height, max_items=2200):
    """Build a compact selectable text layer using normalized PDF coordinates.

    The browser lays these word boxes over the rendered page image.  Coordinates
    are normalized so the layer remains aligned when the responsive preview scales.
    This is intentionally bounded to keep JobAdder preview responses predictable.
    """
    try:
        text = str(textpage.get_text_range() or "")[:50000]
    except Exception:
        return None
    if not text.strip() or page_width <= 0 or page_height <= 0:
        return None

    items = []
    word_start = None
    left = bottom = right = top = None

    def flush(end_index):
        nonlocal word_start, left, bottom, right, top
        if word_start is None:
            return
        token = text[word_start:end_index]
        if token and token.strip() and None not in (left, bottom, right, top) and len(items) < max_items:
            x = max(0.0, min(1.0, float(left) / float(page_width)))
            y = max(0.0, min(1.0, (float(page_height) - float(top)) / float(page_height)))
            w = max(0.0001, min(1.0 - x, (float(right) - float(left)) / float(page_width)))
            h = max(0.0025, min(1.0 - y, (float(top) - float(bottom)) / float(page_height)))
            items.append({
                "t": token[:160],
                "s": int(word_start),
                "e": int(end_index),
                "x": round(x, 6),
                "y": round(y, 6),
                "w": round(w, 6),
                "h": round(h, 6),
            })
        word_start = None
        left = bottom = right = top = None

    for index, char in enumerate(text):
        if char.isspace():
            flush(index)
            continue
        try:
            box = textpage.get_charbox(index)
            c_left, c_bottom, c_right, c_top = [float(v) for v in box]
        except Exception:
            flush(index)
            continue
        if not all(map(lambda v: abs(v) < 1000000, (c_left, c_bottom, c_right, c_top))):
            flush(index)
            continue
        if word_start is None:
            word_start = index
            left, bottom, right, top = c_left, c_bottom, c_right, c_top
        else:
            left = min(left, c_left)
            bottom = min(bottom, c_bottom)
            right = max(right, c_right)
            top = max(top, c_top)
    flush(len(text))
    if not items:
        return None
    return {"text": text, "items": items, "truncated": len(items) >= max_items}


def _spider_pdfium_preview_pages(raw, first_page=1, last_page=None, dpi=118, cancel_check=None):
    """Render PDF pages and their selectable coordinate text layers in one pass."""
    import pypdfium2 as pdfium
    document = pdfium.PdfDocument(raw)
    pages = []
    document_text_parts = []
    try:
        page_count = len(document)
        if page_count > _MAX_PDF_PAGES:
            raise ValueError("PDF has {} pages; the safe limit is {}".format(page_count, _MAX_PDF_PAGES))
        first_page = max(1, int(first_page or 1))
        if first_page > page_count:
            return page_count, [], ""
        if last_page is None:
            last_page = page_count
        last_page = min(page_count, max(first_page, int(last_page)))
        scale = max(1.0, min(2.2, float(dpi or 118) / 72.0))
        remaining_text_items = 16000
        for page_index in range(first_page - 1, last_page):
            if callable(cancel_check):
                cancel_check()
            page = document[page_index]
            bitmap = None
            textpage = None
            try:
                page_width = float(page.get_width() or 0)
                page_height = float(page.get_height() or 0)
                rotation = int(page.get_rotation() or 0)
                bitmap = page.render(scale=scale)
                if callable(cancel_check):
                    cancel_check()
                image = bitmap.to_pil().copy()
                text_layer = None
                # Extract page text once for all-page Ctrl+F coverage. Rotated
                # pages keep searchable text but intentionally omit coordinate
                # overlays because producer-specific rotations can misalign boxes.
                try:
                    textpage = page.get_textpage()
                    page_text = str(textpage.get_text_range() or "")[:50000]
                    if page_text:
                        document_text_parts.append(page_text)
                    if rotation % 360 == 0 and remaining_text_items > 0:
                        text_layer = _spider_pdf_text_layer_from_pdfium(
                            textpage,
                            page_width,
                            page_height,
                            max_items=min(2200, remaining_text_items),
                        )
                        if text_layer:
                            remaining_text_items -= len(text_layer.get("items") or [])
                except Exception:
                    text_layer = None
                pages.append({"image": image, "text_layer": text_layer, "rotation": rotation})
            finally:
                try:
                    if textpage is not None:
                        textpage.close()
                except Exception:
                    pass
                try:
                    if bitmap is not None:
                        bitmap.close()
                except Exception:
                    pass
                try:
                    page.close()
                except Exception:
                    pass
        # Preserve the old all-page Ctrl+F/Text coverage without running a
        # second pdfplumber pass. Remaining pages are text-only and therefore
        # cheap compared with rendering/encoding them.
        if sum(len(x) for x in document_text_parts) < 30000 and last_page < page_count:
            for page_index in range(last_page, page_count):
                if callable(cancel_check):
                    cancel_check()
                page = document[page_index]
                textpage = None
                try:
                    textpage = page.get_textpage()
                    text = str(textpage.get_text_range() or "")
                    if text:
                        document_text_parts.append(text)
                    if sum(len(x) for x in document_text_parts) >= 30000:
                        break
                except Exception:
                    pass
                finally:
                    try:
                        if textpage is not None:
                            textpage.close()
                    except Exception:
                        pass
                    try:
                        page.close()
                    except Exception:
                        pass
        return page_count, pages, "\n".join(document_text_parts)[:30000]
    finally:
        try:
            document.close()
        except Exception:
            pass


def _spider_pdf_pages_preview_payload(raw, source, note="", max_pages=12, dpi=118, cancel_check=None):
    """Render PDF pages into fast preview images plus a selectable visual text layer.

    The original PDF bytes are never sent to the browser, so native PDF download
    controls remain absent.  PDFium rendering and text extraction happen in one
    pass.  Fast WebP encoding materially reduces the first-preview delay compared
    with the older high-effort encoder.
    """
    raw = raw or b""
    if not raw:
        return None
    page_count = 0
    rendered = []
    visual_search_text = ""
    try:
        page_count, rendered, visual_search_text = _spider_pdfium_preview_pages(
            raw,
            first_page=1,
            last_page=max(1, int(max_pages or 12)),
            dpi=max(96, min(150, int(dpi or 118))),
            cancel_check=cancel_check,
        )
    except _SpiderPreviewCancelled:
        raise
    except Exception:
        # Owner/source fallback for environments without the bundled PDFium wheel.
        try:
            page_count = _pdf_page_count(raw)
            shown_target = min(max(1, int(max_pages or 12)), page_count)
            images = _render_pdf_page_images(
                raw,
                first_page=1,
                last_page=shown_target,
                dpi=max(96, min(150, int(dpi or 118))),
                timeout=45,
            )
            rendered = [{"image": image, "text_layer": None, "rotation": 0} for image in images]
            visual_search_text = ""
        except Exception:
            return None
    if not rendered:
        return None

    page_images = []
    visual_text_layers = []
    try:
        from PIL import Image as _PILImage
        for page_data in rendered:
            if callable(cancel_check):
                cancel_check()
            image = page_data.get("image")
            work = image
            try:
                # A 118-DPI A4 page is already about 975 px wide.  This remains
                # readable while avoiding the much heavier 135-DPI/method-4 path.
                if max(work.size or (0, 0)) > 1450:
                    work.thumbnail((1450, 2200), _PILImage.Resampling.LANCZOS)
                if work.mode not in ("RGB", "L"):
                    if "A" in work.getbands():
                        flattened = _PILImage.new("RGB", work.size, "white")
                        flattened.paste(work, mask=work.getchannel("A"))
                        work = flattened
                    else:
                        work = work.convert("RGB")
                elif work.mode == "L":
                    work = work.convert("RGB")
                out = io.BytesIO()
                mime = "image/webp"
                try:
                    # method=0 is deliberately chosen for interactive preview
                    # latency; it was about 3x faster than method=4 in QA.
                    work.save(out, format="WEBP", quality=78, method=0)
                except Exception:
                    out = io.BytesIO()
                    mime = "image/jpeg"
                    work.save(out, format="JPEG", quality=80)
                page_images.append("data:{};base64,{}".format(mime, base64.b64encode(out.getvalue()).decode("ascii")))
                visual_text_layers.append(page_data.get("text_layer"))
            finally:
                try:
                    if work is not image:
                        work.close()
                except Exception:
                    pass
                try:
                    image.close()
                except Exception:
                    pass
    finally:
        for page_data in rendered[len(page_images):]:
            try:
                page_data.get("image").close()
            except Exception:
                pass

    if not page_images:
        return None
    notes = [str(note or "").strip()]
    if page_count > len(page_images):
        notes.append("Showing the first {} of {} pages in protected preview mode.".format(len(page_images), page_count))
    if any(layer and layer.get("items") for layer in visual_text_layers):
        notes.append("Visual text selection and keyword overlays are available.")
    else:
        notes.append("This file has no coordinate text layer; use Select text for extracted/OCR text.")
    notes.append("Preview download controls are disabled.")
    return {
        "visual_mode": "pdf_pages",
        "page_images": page_images,
        "visual_text_layers": visual_text_layers,
        "visual_search_text": str(visual_search_text or "")[:30000],
        "page_count": page_count,
        "shown_pages": len(page_images),
        "source": str(source or "actual JobAdder PDF resume"),
        "note": " ".join(x for x in notes if x),
        "download_disabled": True,
    }


def _spider_visual_preview_payload(raw, content_type="", filename="", max_pages=12, dpi=118, cancel_check=None):
    """Return actual visual CV preview payload when JobAdder exposes a resume file.

    PDF resumes are rendered into bounded preview-only page images so the browser's
    native PDF download toolbar is never exposed. Image resumes remain image previews.
    Office files are converted to PDF via LibreOffice and then rendered the same way,
    with DOCX HTML fallback. Text/JSON payloads intentionally return None so the caller
    can fall back to extracted/profile text.
    """
    raw = raw or b""
    if not raw or len(raw) > 12 * 1024 * 1024:
        return None
    import base64 as _base64, os as _os
    ctype = str(content_type or "").lower()
    fname = _spider_filename_from_disposition(filename, filename).lower()
    ext = _os.path.splitext(fname)[1].lower()
    stripped = raw.lstrip()[:1]
    if "json" in ctype or stripped in (b"{", b"["):
        return None
    if raw.startswith(b"%PDF") or "pdf" in ctype or ext == ".pdf":
        return _spider_pdf_pages_preview_payload(raw, "actual JobAdder PDF resume", max_pages=max_pages, dpi=dpi, cancel_check=cancel_check)
    if raw[:8].startswith(b"\x89PNG") or raw[:3] == b"\xff\xd8\xff" or "image/" in ctype or ext in (".png", ".jpg", ".jpeg"):
        if callable(cancel_check):
            cancel_check()
        mime = "image/png" if (raw[:8].startswith(b"\x89PNG") or ext == ".png" or "png" in ctype) else "image/jpeg"
        data = _base64.b64encode(raw).decode("ascii")
        return {"visual_mode": "image", "data_url": "data:" + mime + ";base64," + data, "source": "actual JobAdder image resume", "download_disabled": True, "note": "Preview download controls are disabled."}
    legacy_doc = _spider_is_legacy_word_doc_bytes(raw)
    looks_office = raw[:2] == b"PK" or legacy_doc or "word" in ctype or "msword" in ctype or "officedocument" in ctype or ext in (".docx", ".doc", ".rtf", ".odt")
    if looks_office:
        conv_ext = ext or (".docx" if raw[:2] == b"PK" else ".doc" if legacy_doc or "msword" in ctype else ".doc")
        try:
            pdf_bytes, note = _office_bytes_to_pdf_preview(raw, conv_ext, cancel_check=cancel_check)
            if pdf_bytes:
                return _spider_pdf_pages_preview_payload(
                    pdf_bytes,
                    "actual JobAdder resume converted to PDF",
                    note=note,
                    max_pages=max_pages,
                    dpi=dpi,
                    cancel_check=cancel_check,
                )
        except _SpiderPreviewCancelled:
            raise
        except Exception:
            pass
        if conv_ext == ".docx" or raw[:2] == b"PK":
            try:
                return {"visual_mode": "html", "html": _docx_bytes_to_preview_html(raw), "source": "actual JobAdder DOCX resume layout preview", "note": "LibreOffice visual conversion unavailable; showing DOCX layout fallback. Preview download controls are disabled.", "download_disabled": True}
            except Exception:
                return None
    return None

def _spider_search_text_from_visual_payload(visual):
    """Reuse PDFium text and avoid a second PDF parser pass."""
    if isinstance(visual, dict):
        full_text = _spider_clean_doc_text_for_preview(str(visual.get("visual_search_text") or ""))[:30000]
        if full_text:
            return full_text, "PDFium visual/search text layer"
    layers = (visual or {}).get("visual_text_layers") if isinstance(visual, dict) else None
    if not isinstance(layers, list):
        return "", ""
    parts = []
    for layer in layers:
        if not isinstance(layer, dict):
            continue
        text = str(layer.get("text") or "").strip()
        if text:
            parts.append(text)
        if sum(len(part) for part in parts) >= 30000:
            break
    text = _spider_clean_doc_text_for_preview("\n".join(parts))[:30000]
    if text:
        return text, "PDFium visual text layer"
    return "", ""


def _spider_apply_visual_search_state(visual, search_text, search_source):
    payload = dict(visual or {})
    payload.pop("visual_search_text", None)
    payload["search_text"] = str(search_text or "")[:30000]
    if not payload["search_text"]:
        payload["search_note"] = str(search_source or "Visual CV loaded, but no searchable text could be extracted.")[:200]
    return payload


class _SpiderJobAdderReconnectRequired(RuntimeError):
    pass


def _spider_mark_jobadder_reconnect_required():
    # Backward-compatible crawler alias for the shared JobAdder connection state.
    _ja_mark_reconnect_required()


def _spider_get_ja_raw(token, path, timeout=10, *, accept_json=False):
    """GET one JobAdder resource and retry once after a forced OAuth refresh."""
    try:
        headers = {"Accept": "application/json"} if accept_json else None
        response = _JOBADDER_CLIENT.request_raw(
            path,
            method="GET",
            token=token,
            timeout=timeout,
            headers=headers,
        )
        return (
            response.body,
            response.headers.get("Content-Type", ""),
            response.headers.get("Content-Disposition", ""),
        )
    except urllib.error.HTTPError as exc:
        if exc.code == 401:
            _spider_mark_jobadder_reconnect_required()
            try:
                exc.close()
            except Exception:
                pass
            raise _SpiderJobAdderReconnectRequired("JobAdder rejected the refreshed OAuth token")
        raise


def _spider_attachment_candidates(payload):
    """Return likely resume attachment ids from a JobAdder attachments/documents payload."""
    out = []
    def walk(x, depth=0):
        if depth > 5 or x is None:
            return
        if isinstance(x, list):
            for item in x[:80]:
                walk(item, depth + 1)
        elif isinstance(x, dict):
            flat = " ".join(str(v) for v in _spider_flatten(x)[:80]).lower()
            looks_resume = any(t in flat for t in ["resume", "cv", "curriculum", "formattedresume", "formatted resume"])
            if looks_resume:
                ids = []
                for key in ["id", "attachmentId", "attachmentID", "documentId", "documentID", "fileId", "fileID", "entityId"]:
                    if x.get(key):
                        ids.append(str(x.get(key)))
                name = str(x.get("fileName") or x.get("filename") or x.get("name") or x.get("title") or "")
                out.append({"ids": ids, "name": name})
            for v in x.values():
                walk(v, depth + 1)
    walk(payload)
    return out[:8]


@app.route("/jobadder/spider_preview_cancel_prefetch", methods=["POST"])
def jobadder_spider_preview_cancel_prefetch():
    # Cancellation exposes no candidate data and remains protected by the local
    # Host/Origin guards. Allow it even after the crawler has just been locked so
    # an already-running background PDFium/LibreOffice job can still be stopped.
    _spider_preview_cancel_persistent_work()
    return "", 204


@app.route("/jobadder/spider_candidate_preview", methods=["GET"])
def jobadder_spider_candidate_preview():
    """Side-panel preview with bounded full/partial caches and cancellation."""
    if not _ai_crawler_lock_allowed():
        return _ai_crawler_locked_response()
    token = _ja_refresh_access_token(force=False)
    candidate_id = str(request.args.get("candidate_id") or "").strip()
    if not token:
        return jsonify({"error": "Connect to JobAdder first", "needs_reconnect": True}), 401
    if not candidate_id:
        return jsonify({"error": "Missing candidate_id"}), 400

    prefetch_mode = str(request.args.get("prefetch") or "").strip().lower() in ("1", "true", "yes", "on")
    validate_only = str(request.args.get("validate") or "").strip().lower() in ("1", "true", "yes", "on")
    background_generation = _spider_preview_background_generation()
    prefetch_job_id = ""
    prefetch_job_store = None
    if prefetch_mode:
        opaque_cache_key = _spider_resume_cache_key(token, candidate_id)
        if not opaque_cache_key:
            opaque_cache_key = hashlib.sha256(
                candidate_id.encode("utf-8", errors="surrogatepass")
            ).hexdigest()
        prefetch_job_id = deterministic_job_id(
            _SPIDER_PREVIEW_PREFETCH_JOB_KIND,
            opaque_cache_key,
        )
        prefetch_job_store = _CVSTUDIO_JOBS
        prefetch_job_store.begin(
            prefetch_job_id,
            kind=_SPIDER_PREVIEW_PREFETCH_JOB_KIND,
            safety="safe_idempotent_read",
            request_id=_cvstudio_current_request_id(),
            stage="attachment_metadata",
        )

        @after_this_request
        def finalize_persistent_prefetch(response):
            try:
                payload = response.get_json(silent=True)
                if (
                    response.status_code == 409
                    and isinstance(payload, dict)
                    and payload.get("prefetch_cancelled")
                ):
                    prefetch_job_store.mark_cancelled(prefetch_job_id)
                elif 200 <= int(response.status_code or 0) < 300:
                    prefetch_job_store.complete(prefetch_job_id)
                else:
                    status = int(response.status_code or 500)
                    retryable = status >= 500 or status == 429
                    prefetch_job_store.fail(
                        prefetch_job_id,
                        error_code="PREFETCH_HTTP_{}".format(status),
                        error_summary=(
                            "Preview prefetch returned HTTP status {}."
                        ).format(status),
                        retryable=retryable,
                        recovery_action=(
                            "retry_same_request" if retryable else ""
                        ),
                    )
            except PersistentJobError as error:
                return app.make_response(
                    _cvstudio_persistent_job_error(error)
                )
            return response

    if not prefetch_mode and not validate_only:
        # Foreground opens cancel any old background render before they start
        # their own expensive PDFium/OCR/LibreOffice work.
        _spider_preview_cancel_persistent_work()

    def job_progress(stage, current):
        if prefetch_job_store is not None:
            prefetch_job_store.progress(
                prefetch_job_id,
                stage=stage,
                current=current,
            )

    def cancel_check():
        if prefetch_mode:
            _spider_preview_cancel_check(background_generation)

    candidate_id_safe = urllib.parse.quote(candidate_id, safe="")
    tried = []
    cancel_check()
    attachment_records = _spider_candidate_attachment_records(token, candidate_id)
    cancel_check()
    job_progress("attachment_metadata", 15)
    attachment_fingerprint = _spider_attachment_fingerprint(attachment_records) if attachment_records else ""

    if validate_only:
        return jsonify({
            "ok": True,
            "candidate_id": candidate_id,
            "attachment_fingerprint": attachment_fingerprint[:24],
            "has_attachment_metadata": bool(attachment_records),
        })

    # Background requests may reuse a complete foreground cache entry. Partial
    # prefetch entries are kept under a separate variant and never satisfy a
    # later full foreground request.
    if prefetch_mode:
        cached_payload = _spider_preview_payload_cache_get(token, candidate_id, attachment_fingerprint, "full")
        if cached_payload is None:
            cached_payload = _spider_preview_payload_cache_get(token, candidate_id, attachment_fingerprint, "prefetch")
    else:
        cached_payload = _spider_preview_payload_cache_get(token, candidate_id, attachment_fingerprint, "full")
    if cached_payload is not None:
        return jsonify(cached_payload)
    job_progress("cache_lookup", 25)

    preview_max_pages = 2 if prefetch_mode else 12
    preview_dpi = 104 if prefetch_mode else 118

    def get_raw(path, timeout, *, accept_json=False):
        cancel_check()
        result = _spider_get_ja_raw(
            token,
            path,
            timeout=timeout,
            accept_json=accept_json,
        )
        cancel_check()
        return result

    def render_visual(raw, ctype, filename):
        cancel_check()
        with _SPIDER_PREVIEW_RENDER_LOCK:
            cancel_check()
            return _spider_visual_preview_payload(
                raw,
                ctype,
                filename,
                max_pages=preview_max_pages,
                dpi=preview_dpi,
                cancel_check=cancel_check if prefetch_mode else None,
            )

    def extract_text(raw, ctype, filename):
        cancel_check()
        with _SPIDER_PREVIEW_RENDER_LOCK:
            cancel_check()
            result = _spider_extract_text_from_download(raw, ctype, filename, cancel_check=cancel_check if prefetch_mode else None)
            cancel_check()
            return result

    def visual_search_text(raw, ctype, filename, visual):
        """Reuse visual text and keep background prefetch genuinely lightweight.

        PDF/image OCR can occupy Tesseract for many seconds and cannot be stopped
        safely in the middle of one page. A background preload therefore renders
        only the first two visual pages and reuses any PDFium text layer already
        available. Scanned/image-only OCR is deferred until the recruiter actually
        opens the candidate, when the full foreground request has priority.
        Cheap text/DOCX extraction remains allowed during prefetch.
        """
        search_text, search_source = _spider_search_text_from_visual_payload(visual)
        if search_text:
            return search_text, search_source
        raw_head = (raw or b"")[:8]
        ctype_l = str(ctype or "").lower()
        filename_l = str(filename or "").lower()
        is_pdf_or_image = (
            raw_head.startswith(b"%PDF")
            or raw_head.startswith(b"\x89PNG")
            or raw_head[:3] == b"\xff\xd8\xff"
            or "pdf" in ctype_l
            or "image/" in ctype_l
            or filename_l.endswith((".pdf", ".png", ".jpg", ".jpeg"))
        )
        if prefetch_mode and is_pdf_or_image:
            return "", "Searchable OCR text will be prepared when this candidate is opened."
        return extract_text(raw, ctype, filename)

    cancel_check()
    detail = _spider_fetch_candidate_detail(token, candidate_id)
    cancel_check()
    job_progress("candidate_profile", 40)

    def respond(payload, status=200, cacheable=True):
        if isinstance(payload, dict):
            payload = dict(payload)
            page_count = int(payload.get("page_count") or 0)
            shown_pages = int(payload.get("shown_pages") or 0)
            is_partial = bool(prefetch_mode and page_count and shown_pages and shown_pages < page_count)
            store_variant = "prefetch" if is_partial else "full"
            payload["attachment_fingerprint"] = attachment_fingerprint[:24]
            payload["preview_cache_hit"] = False
            payload["preview_partial"] = is_partial
            payload["preview_variant"] = store_variant
            if status == 200 and cacheable and payload.get("ok"):
                _spider_preview_payload_cache_put(token, candidate_id, attachment_fingerprint, payload, store_variant)
        return jsonify(payload), status

    # Official JobAdder candidate-attachment API first.
    job_progress("official_attachment", 50)
    for record in attachment_records:
        cancel_check()
        attach_id = record.get("attachmentId") or record.get("id")
        if not attach_id:
            continue
        path = "candidates/{}/attachments/{}".format(candidate_id_safe, urllib.parse.quote(str(attach_id), safe=""))
        try:
            raw, ctype, dispo = get_raw(path, timeout=12)
            tried.append(path)
            filename = record.get("fileName") or dispo or ""
            visual = render_visual(raw, ctype, filename)
            search_text, search_source = visual_search_text(raw, ctype, filename, visual)
            if search_text:
                _spider_resume_text_cache_put(token, candidate_id, search_text, search_source)
            if visual:
                visual = _spider_apply_visual_search_state(visual, search_text, search_source)
                visual.update({
                    "ok": True,
                    "candidate_id": candidate_id,
                    "name": _spider_preview_name(candidate_id, detail),
                    "mode": "resume_attachment_file",
                    "note": filename or "latest resume attachment",
                    "tried": tried,
                })
                return respond(visual)
            if search_text:
                return respond({
                    "ok": True,
                    "candidate_id": candidate_id,
                    "name": _spider_preview_name(candidate_id, detail),
                    "mode": "resume_attachment_text",
                    "source": search_source,
                    "note": filename or "latest resume attachment",
                    "preview_text": search_text,
                    "search_text": search_text,
                    "tried": tried,
                })
        except _SpiderPreviewCancelled:
            raise
        except urllib.error.HTTPError as exc:
            tried.append(path + ":" + str(exc.code))
        except Exception as exc:
            tried.append(path + ":" + str(exc)[:80])

    # Direct resume/document endpoints used by legacy tenant integrations.
    job_progress("direct_resume", 65)
    direct_paths = [
        "candidates/{}/resume".format(candidate_id_safe),
        "candidates/{}/attachments/Resume".format(candidate_id_safe),
        "candidates/{}/attachments/FormattedResume".format(candidate_id_safe),
    ]
    for path in direct_paths:
        cancel_check()
        try:
            raw, ctype, dispo = get_raw(path, timeout=10)
            tried.append(path)
            visual = render_visual(raw, ctype, dispo)
            if visual:
                search_text, search_source = visual_search_text(raw, ctype, dispo, visual)
                if search_text:
                    _spider_resume_text_cache_put(token, candidate_id, search_text, search_source)
                visual = _spider_apply_visual_search_state(visual, search_text, search_source)
                visual.update({
                    "ok": True,
                    "candidate_id": candidate_id,
                    "name": _spider_preview_name(candidate_id, detail),
                    "mode": "resume_file",
                    "tried": tried,
                })
                return respond(visual)
            txt, src = extract_text(raw, ctype, dispo)
            if txt:
                _spider_resume_text_cache_put(token, candidate_id, txt, src)
                return respond({
                    "ok": True,
                    "candidate_id": candidate_id,
                    "name": _spider_preview_name(candidate_id, detail),
                    "mode": "resume_text",
                    "source": src,
                    "preview_text": txt,
                    "search_text": txt,
                    "tried": tried,
                })
        except _SpiderPreviewCancelled:
            raise
        except urllib.error.HTTPError as exc:
            tried.append(path + ":" + str(exc.code))
        except Exception as exc:
            tried.append(path + ":" + str(exc)[:80])

    # Attachments/documents listing, then likely resume IDs.
    job_progress("attachment_discovery", 80)
    for list_path, kind in [
        ("candidates/{}/attachments".format(candidate_id_safe), "attachments"),
        ("candidates/{}/documents".format(candidate_id_safe), "documents"),
    ]:
        cancel_check()
        try:
            raw, _ctype, _dispo = get_raw(
                list_path,
                timeout=10,
                accept_json=True,
            )
            tried.append(list_path)
            listing = safe_json(raw, {})
            for att in _spider_attachment_candidates(listing):
                cancel_check()
                for att_id in att.get("ids") or []:
                    att_safe = urllib.parse.quote(str(att_id), safe="")
                    for suffix in ["", "/download", "/file"]:
                        cancel_check()
                        path = "candidates/{}/{}/{}{}".format(candidate_id_safe, kind, att_safe, suffix)
                        try:
                            raw2, ctype2, dispo2 = get_raw(path, timeout=12)
                            tried.append(path)
                            filename = att.get("name") or dispo2
                            visual = render_visual(raw2, ctype2, filename)
                            if visual:
                                search_text, search_source = visual_search_text(raw2, ctype2, filename, visual)
                                if search_text:
                                    _spider_resume_text_cache_put(token, candidate_id, search_text, search_source)
                                visual = _spider_apply_visual_search_state(visual, search_text, search_source)
                                visual.update({
                                    "ok": True,
                                    "candidate_id": candidate_id,
                                    "name": _spider_preview_name(candidate_id, detail),
                                    "mode": "resume_attachment_file",
                                    "note": att.get("name") or visual.get("note") or "resume attachment",
                                    "tried": tried[:12],
                                })
                                return respond(visual)
                            txt, src = extract_text(raw2, ctype2, filename)
                            if txt:
                                _spider_resume_text_cache_put(token, candidate_id, txt, src)
                                return respond({
                                    "ok": True,
                                    "candidate_id": candidate_id,
                                    "name": _spider_preview_name(candidate_id, detail),
                                    "mode": "resume_attachment_text",
                                    "source": src,
                                    "note": att.get("name") or "resume attachment",
                                    "preview_text": txt,
                                    "search_text": txt,
                                    "tried": tried[:12],
                                })
                        except _SpiderPreviewCancelled:
                            raise
                        except urllib.error.HTTPError as exc:
                            tried.append(path + ":" + str(exc.code))
                        except Exception as exc:
                            tried.append(path + ":" + str(exc)[:80])
        except _SpiderPreviewCancelled:
            raise
        except urllib.error.HTTPError as exc:
            tried.append(list_path + ":" + str(exc.code))
        except Exception as exc:
            tried.append(list_path + ":" + str(exc)[:80])

    cancel_check()
    job_progress("profile_fallback", 90)
    if isinstance(detail, dict) and detail:
        preview_text = _spider_preview_text_from_detail(detail)
        return respond({
            "ok": True,
            "candidate_id": candidate_id,
            "name": _spider_preview_name(candidate_id, detail),
            "mode": "profile",
            "source": "JobAdder profile fields",
            "note": "Resume file not exposed by JobAdder API; showing profile fields instead.",
            "preview_text": preview_text,
            "search_text": preview_text,
            "tried": tried[:12],
        })
    return respond({
        "ok": False,
        "candidate_id": candidate_id,
        "error": "Candidate preview unavailable",
        "note": "JobAdder did not return a resume/profile preview for this candidate.",
        "tried": tried[:12],
    }, 404, cacheable=False)


def _spider_candidate_search_key(candidate):
    """Stable key for set algebra and de-duplication across JobAdder keyword probes."""
    cid = _spider_candidate_id(candidate)
    if cid:
        return "id:" + str(cid)
    if isinstance(candidate, dict):
        email = str(candidate.get("email") or candidate.get("emailAddress") or "").strip().lower()
        if email:
            return "email:" + email
        name = str(candidate.get("name") or candidate.get("fullName") or "").strip().lower()
        if name:
            return "name:" + name
    return "raw:" + hashlib.sha1(json.dumps(candidate, sort_keys=True, default=str).encode("utf-8", errors="ignore")).hexdigest()


def _spider_parse_candidate_items(payload):
    if isinstance(payload, dict):
        data_obj = payload.get("data")
        items = payload.get("items") or payload.get("candidates") or (data_obj.get("items") if isinstance(data_obj, dict) else None) or []
        total = None
        # Preserve an explicit totalCount=0 instead of losing it through truthiness.
        for key in ("totalCount", "total", "count"):
            if key in payload and payload.get(key) is not None:
                total = payload.get(key)
                break
        if total is None and isinstance(data_obj, dict):
            for key in ("totalCount", "total", "count"):
                if key in data_obj and data_obj.get(key) is not None:
                    total = data_obj.get(key)
                    break
    elif isinstance(payload, list):
        items, total = payload, len(payload)
    else:
        items, total = [], 0
    return (items if isinstance(items, list) else []), total


def _spider_boolean_fallback_atoms(rule_text, max_positive=8, max_negative=24):
    """Return ordered positive and NOT-scoped atoms from recruiter Boolean text.

    The lightweight recursive walk understands NOT applied to one atom or a
    parenthesized group. Quoted phrases (single or double) and unquoted Unicode
    terms are preserved. It intentionally does not attempt local Boolean result
    validation; it only creates a safe zero-result discovery fallback.
    """
    raw = re.sub(r"[\x00-\x1f\x7f]", " ", str(rule_text or ""))
    token_re = re.compile(
        r"""\s*(?:
            (?P<dq>"(?:\\.|[^"\\])*")|
            (?P<sq>'(?:\\.|[^'\\])*')|
            (?P<lp>\()|(?P<rp>\))|
            (?P<op>\bAND\b|\bOR\b|\bNOT\b)|
            (?P<word>[^\s()]+)
        )""",
        re.I | re.X | re.UNICODE,
    )
    tokens = []
    for match in token_re.finditer(raw):
        kind = match.lastgroup
        value = match.group(kind) if kind else ""
        if kind in ("dq", "sq"):
            value = value[1:-1]
            value = re.sub(r"\\([\\\"'])", r"\1", value)
            tokens.append(("atom", value))
        elif kind == "op":
            tokens.append((value.upper(), value.upper()))
        elif kind == "lp":
            tokens.append(("(", value))
        elif kind == "rp":
            tokens.append((")", value))
        elif kind == "word":
            value = value.strip(" \t\r\n,;:")
            if value:
                tokens.append(("atom", value))

    positives, negatives = [], []

    def walk(index, inherited_negative=False):
        pending_not = False
        while index < len(tokens):
            kind, value = tokens[index]
            if kind == ")":
                return index + 1
            if kind == "NOT":
                pending_not = not pending_not
                index += 1
                continue
            if kind in ("AND", "OR"):
                pending_not = False
                index += 1
                continue
            effective_negative = bool(inherited_negative) ^ bool(pending_not)
            pending_not = False
            if kind == "(":
                index = walk(index + 1, effective_negative)
                continue
            if kind == "atom":
                term = re.sub(r"\s+", " ", str(value or "")).strip(" \t\r\n,;:")[:100]
                if term and term.upper() not in {"AND", "OR", "NOT"}:
                    (negatives if effective_negative else positives).append(term)
            index += 1
        return index

    walk(0, False)

    def dedupe(values, limit):
        out, seen = [], set()
        for value in values:
            key = value.casefold()
            if key in seen:
                continue
            seen.add(key)
            out.append(value)
            if len(out) >= max(1, int(limit or 1)):
                break
        return out

    return dedupe(positives, max_positive), dedupe(negatives, max_negative)


def _spider_boolean_fallback_terms(rule_text, max_terms=8):
    positives, _negatives = _spider_boolean_fallback_atoms(rule_text, max_terms, 24)
    return positives


def _spider_jobadder_keyword_items(token, keyword, max_items=3000, page_size=1000, location="", embed=True):
    """Search JobAdder latest resumes with complete, defensive pagination.

    ``Location`` is city/state in JobAdder. Country is deliberately never sent
    here and remains a local eligibility filter. Short pages do not end a search
    while JobAdder's ``totalCount`` says more rows exist.
    """
    keyword = re.sub(r"[\x00-\x1f\x7f]", " ", str(keyword or ""))
    keyword = re.sub(r"\s+", " ", keyword).strip()[:1500]
    city_state = re.sub(r"\s+", " ", str(location or "")).strip()[:120]
    if not keyword:
        return [], {"keyword": keyword, "scanned": 0, "reported_total": 0, "pages": 0, "embed_applied": False}
    max_items = max(1, min(5000, int(max_items or 3000)))
    page_size = max(1, min(1000, int(page_size or 1000)))
    state = {"embed_active": bool(embed), "embed_rejected": False}
    base_params = [("Keywords", keyword)]
    if city_state and city_state.lower() != "any":
        base_params.append(("Location", city_state))
    if state["embed_active"]:
        base_params.extend([("Embed", "skills"), ("Embed", "notes")])

    def fetch_page(page_params):
        query = urllib.parse.urlencode(page_params, doseq=True)
        raw, _ctype, _dispo = _spider_get_ja_raw(
            token,
            "candidates?" + query,
            timeout=25,
            accept_json=True,
        )
        return safe_json(raw, {"items": []})

    def reject_unsupported_embed(error, active_params, _offset, _pages):
        if state["embed_active"] and int(getattr(error, "code", 0) or 0) in (400, 403, 422):
            state["embed_active"] = False
            state["embed_rejected"] = True
            return [(key, value) for key, value in active_params if str(key).lower() != "embed"]
        return None

    def page_signature(_items, keys):
        unique = sorted(set(keys))
        return hashlib.sha1("\n".join(unique).encode("utf-8", errors="ignore")).hexdigest() if unique else "empty"

    out, page_state = _JOBADDER_CLIENT.paginate_offset(
        "candidates",
        params=base_params,
        token=token,
        max_items=max_items,
        page_size=page_size,
        timeout=25,
        parse_page=_spider_parse_candidate_items,
        item_key=_spider_candidate_search_key,
        page_signature=page_signature,
        total_mode="replace",
        deduplicate=True,
        on_http_error=reject_unsupported_embed,
        fetch_page=fetch_page,
    )
    warning_map = {
        "repeated_page": "JobAdder repeated a candidate page before totalCount was reached",
        "no_new_unique": "JobAdder pagination returned no new unique candidates",
        "empty_before_total": "JobAdder returned an empty page before totalCount was reached",
        "no_progress": "JobAdder pagination made no forward progress",
        "missing_at_total": "JobAdder pagination reached totalCount with duplicate or missing candidate rows",
        "cap_reached": "Candidate search reached the {}-candidate safety cap".format(max_items),
    }
    warnings = [warning_map[code] for code in page_state.get("codes") or [] if code in warning_map]
    return out, {
        "keyword": keyword,
        "location": city_state,
        "scanned": len(out),
        "reported_total": page_state.get("reported_total"),
        "pages": page_state.get("pages"),
        "truncated": bool(page_state.get("truncated")),
        "incomplete": bool(page_state.get("incomplete")),
        "warnings": warnings[:5],
        "embed_applied": bool(embed and not state["embed_rejected"]),
        "embed_rejected": bool(state["embed_rejected"]),
    }


def _spider_mark_plain_keyword_candidates(items, query_text, fallback_rule="", fallback_negative_terms=None):
    query_terms = _spider_terms_for_fit(query_text, 24)
    negative_terms = list(fallback_negative_terms or [])
    marked = []
    for item in items or []:
        out = dict(item) if isinstance(item, dict) else {"value": item}
        out["_spiderSearchTerms"] = list(query_terms)
        if fallback_rule:
            out["_spiderBooleanFallback"] = True
            out["_spiderOriginalBooleanRule"] = str(fallback_rule)[:1500]
            out["_spiderBooleanNegativeTerms"] = negative_terms[:24]
        marked.append(out)
    return marked, query_terms


def _spider_plain_keyword_jobadder_candidates(token, query_text, result_pool_limit=1200, location="", fallback_rule="", fallback_negative_terms=None):
    query_text = re.sub(r"[\x00-\x1f\x7f]", " ", str(query_text or ""))
    query_text = re.sub(r"\s+", " ", query_text).strip()[:1500]
    max_items = max(100, min(3000, int(result_pool_limit or 1200)))
    items, search_meta = _spider_jobadder_keyword_items(
        token,
        query_text,
        max_items=max_items,
        page_size=min(1000, max_items),
        location=location,
    )
    marked, query_terms = _spider_mark_plain_keyword_candidates(
        items,
        query_text,
        fallback_rule=fallback_rule,
        fallback_negative_terms=fallback_negative_terms,
    )
    mode = "native_boolean→fallback" if fallback_rule else "plain"
    meta = {
        "mode": mode,
        "query": query_text,
        "returned": len(marked),
        "search": search_meta,
    }
    if fallback_rule:
        meta.update({
            "fallback": "plain_keywords",
            "fallback_terms": query_terms,
            "negative_terms": list(fallback_negative_terms or [])[:24],
            "original_boolean": str(fallback_rule)[:1500],
            "notice": "JobAdder returned zero rows for the complete Boolean expression; positive plain-keyword fallback results are shown. Visible NOT matches are excluded locally.",
        })
    return marked, meta


def _spider_native_boolean_jobadder_candidates(token, rule_text, result_pool_limit=1200, location=""):
    """Attempt the recruiter's complete Boolean expression once in Keywords.

    JobAdder's public specification describes latest-resume keyword search but
    does not guarantee Boolean parsing for every tenant. Returned membership is
    still discovery proof and is never revalidated against partial detail JSON.
    """
    rule = re.sub(r"[\x00-\x1f\x7f]", " ", str(rule_text or ""))
    rule = re.sub(r"\s+", " ", rule).strip()[:1500]
    if not rule:
        return [], {"mode": "native_boolean", "query": "", "returned": 0, "search": {}}
    max_items = max(100, min(3000, int(result_pool_limit or 1200)))
    items, meta = _spider_jobadder_keyword_items(
        token,
        rule,
        max_items=max_items,
        page_size=min(1000, max_items),
        location=location,
    )
    marked = []
    for item in items:
        out = dict(item) if isinstance(item, dict) else {"value": item}
        out["_spiderNativeBooleanMatched"] = True
        out["_spiderBooleanRule"] = rule
        out["_spiderSearchTerms"] = [rule]
        marked.append(out)
    return marked, {
        "mode": "native_boolean",
        "query": rule,
        "returned": len(marked),
        "search": meta,
    }


@app.route("/jobadder/spider_search", methods=["POST"])
def jobadder_spider_search():
    """JobAdder candidate discovery followed by local eligibility and fit scoring."""
    data = request.get_json(silent=True) or {}
    if not _ai_crawler_lock_allowed(data):
        return _ai_crawler_locked_response()
    token = _ja_refresh_access_token(force=False)
    if not token:
        info = _ja_public_info()
        if info.get("needs_reconnect"):
            return jsonify({
                "error": "JobAdder connection expired. Reconnect JobAdder in Settings, then run AI Crawler again.",
                "needs_reconnect": True,
            }), 401
        return jsonify({"error": "Connect to JobAdder first"}), 401
    query = str(data.get("query") or "").strip()
    if not query:
        return jsonify({"error": "Missing query"}), 400
    limit = data.get("limit", 200)
    try:
        limit = max(1, min(250, int(limit)))
    except Exception:
        limit = 200
    filters = data.get("filters") if isinstance(data.get("filters"), dict) else {}
    safe_filters = {
        "role": str(filters.get("role") or "")[:120],
        "country": str(filters.get("country") or "")[:80],
        "city_state": str(filters.get("city_state") or filters.get("location") or "")[:120],
        "residential": str(filters.get("residential") or "Any")[:80],
        "industry": str(filters.get("industry") or "")[:300],
        "it_skills": str(filters.get("it_skills") or filters.get("skills") or "")[:1500],
        "qualifications": str(filters.get("qualifications") or "")[:1200],
        "salary": str(filters.get("salary") or "")[:120],
        "years": _spider_min_years_value(filters.get("years_min") if filters.get("years_min") is not None else (filters.get("years") or filters.get("experience_years"))),
        "years_min": _spider_min_years_value(filters.get("years_min") if filters.get("years_min") is not None else (filters.get("years") or filters.get("experience_years"))),
        "years_max": _spider_max_years_value(filters.get("years_max") if filters.get("years_max") is not None else filters.get("experience_years_max")),
        "must": str(filters.get("must") or filters.get("boolean") or "")[:1500],
        "nice": str(filters.get("nice") or "")[:1200],
        "exclude": str(filters.get("exclude") or "")[:1200],
        "targets": str(filters.get("targets") or "")[:1200],
        "jd": str(filters.get("jd") or filters.get("job_description") or "")[:12000],
        "strict": bool(filters.get("strict")),
        "adjacent": bool(filters.get("adjacent")),
    }
    query = re.sub(r"[\x00-\x1f\x7f]", " ", query)
    query = re.sub(r"\s+", " ", query).strip()[:260]
    # Prefer the recruiter-authored rule. Generated plain-keyword OR/AND queries are
    # used when the original field did not itself contain Boolean syntax.
    rule_for_search = safe_filters.get("must") or query
    if not re.search(r"\b(AND|OR|NOT)\b|[()\"']", rule_for_search, re.I) and re.search(r"\b(AND|OR|NOT)\b|[()\"']", query, re.I):
        rule_for_search = query
    use_native_boolean = re.search(r"\b(AND|OR|NOT)\b|[()\"']", rule_for_search, re.I) is not None

    try:
        boolean_meta = None
        parsed = {"items": []}
        search_mode = "native_boolean" if use_native_boolean else "plain"
        city_state = safe_filters.get("city_state") or ""
        if use_native_boolean:
            raw_items, boolean_meta = _spider_native_boolean_jobadder_candidates(
                token,
                rule_for_search,
                result_pool_limit=max(1200, limit * 5),
                location=city_state,
            )
            if not raw_items:
                fallback_terms, fallback_negative_terms = _spider_boolean_fallback_atoms(rule_for_search, 8, 24)
                fallback_query = " ".join(fallback_terms).strip()
                if fallback_query:
                    raw_items, fallback_meta = _spider_plain_keyword_jobadder_candidates(
                        token,
                        fallback_query,
                        result_pool_limit=max(1200, limit * 5),
                        location=city_state,
                        fallback_rule=rule_for_search,
                        fallback_negative_terms=fallback_negative_terms,
                    )
                    fallback_meta["native_attempt"] = boolean_meta
                    boolean_meta = fallback_meta
                    search_mode = "native_boolean→fallback"
                else:
                    boolean_meta = {
                        "mode": "native_boolean_no_fallback",
                        "query": rule_for_search,
                        "returned": 0,
                        "fallback": "skipped_negative_only",
                        "negative_terms": fallback_negative_terms,
                        "notice": "The Boolean expression contains no positive discovery terms. CV Studio did not invert a negative-only query into a plain-keyword search.",
                        "native_attempt": boolean_meta,
                        "search": (boolean_meta or {}).get("search", {}) if isinstance(boolean_meta, dict) else {},
                    }
                    search_mode = "native_boolean_no_fallback"
            parsed = {"items": raw_items}
        else:
            raw_items, boolean_meta = _spider_plain_keyword_jobadder_candidates(
                token,
                query,
                result_pool_limit=max(1200, limit * 5),
                location=city_state,
            )
            search_mode = "plain"
            parsed = {"items": raw_items}

        if not isinstance(raw_items, list):
            raw_items = []

        excluded_count = 0
        detail_excluded_count = 0
        unknown_count = 0
        enriched_count = 0
        resume_scored_count = 0

        def build_scored_candidate(base_item, discovery_index, detail=None, resume_text="", resume_source=""):
            scoring_item = base_item
            if isinstance(detail, dict) and detail:
                scoring_item = _spider_merge_candidate_summary_and_detail(base_item, detail)
                if isinstance(base_item, dict) and base_item.get("_spiderSearchTerms"):
                    scoring_item["_spiderSearchTerms"] = list(base_item.get("_spiderSearchTerms") or [])
            scoring_for_fit = scoring_item
            if resume_text:
                scoring_for_fit = dict(scoring_item) if isinstance(scoring_item, dict) else {"value": scoring_item}
                scoring_for_fit["resumeText"] = str(resume_text)[:30000]
            scoring_result = _spider_item_score(
                scoring_for_fit, safe_filters, enriched=bool(detail or resume_text)
            )
            fit_breakdown = {}
            if len(scoring_result) >= 8:
                keep, score, matched, unknown, excluded, hard_passed, discovery_evidence, fit_breakdown = scoring_result[:8]
            elif len(scoring_result) >= 7:
                keep, score, matched, unknown, excluded, hard_passed, discovery_evidence = scoring_result[:7]
            elif len(scoring_result) == 6:
                keep, score, matched, unknown, excluded, hard_passed = scoring_result
                discovery_evidence = []
            else:
                keep, score, matched, unknown, excluded = scoring_result
                hard_passed = []
                discovery_evidence = []
            if not keep:
                return None
            if isinstance(scoring_item, dict):
                out_item = dict(scoring_item)
                out_item.pop("_spiderDetail", None)
            else:
                out_item = {"value": scoring_item}
            out_item["_spiderScore"] = score
            out_item["_spiderFitPercent"] = score
            out_item["_spiderFitBreakdown"] = fit_breakdown if isinstance(fit_breakdown, dict) else {}
            out_item["_spiderMatchedFilters"] = matched
            out_item["_spiderDiscoveryEvidence"] = discovery_evidence
            out_item["_spiderHardFilters"] = hard_passed
            out_item["_spiderUnknownFilters"] = unknown
            out_item["_spiderEnriched"] = bool(detail)
            out_item["_spiderResumeScored"] = bool(resume_text)
            out_item["_spiderFitSource"] = (resume_source or "latest resume") if resume_text else ("JobAdder profile fields" if detail else "JobAdder list result")
            out_item["_spiderCardFields"] = _spider_card_fields(out_item)
            out_item["_spiderDiscoveryIndex"] = int(discovery_index)
            return out_item

        # Stage 1: score every discovered list row before any per-candidate API
        # calls.  This removes the old hard-coded first-120/first-200 position
        # bias and applies explicit local exclusions across the entire pool.
        preliminary = []
        base_by_id = {}
        for discovery_index, item in enumerate(raw_items):
            scored = build_scored_candidate(item, discovery_index)
            if scored is None:
                excluded_count += 1
                continue
            cid = _spider_candidate_id(item)
            preliminary.append({
                "base": item,
                "id": cid,
                "index": discovery_index,
                "score": int(scored.get("_spiderScore") or 0),
                "scored": scored,
            })
            if cid and cid not in base_by_id:
                base_by_id[cid] = item

        # Stage 2: latest-resume scoring uses a strict request budget selected
        # from the whole discovery pool, not merely the first JobAdder page. Half
        # is merit-ranked; half is evenly spread from first to last so later rows
        # can compete when list data is sparse or tied.
        resume_budget = min(len(preliminary), max(20, min(40, max(20, limit // 5))))
        ranked_preliminary = sorted(
            preliminary,
            key=lambda row: (-int(row.get("score") or 0), int(row.get("index") or 0)),
        )
        resume_ids = []
        resume_seen = set()

        def add_resume_row(row):
            cid = str((row or {}).get("id") or "").strip()
            if cid and cid not in resume_seen and len(resume_ids) < resume_budget:
                resume_seen.add(cid)
                resume_ids.append(cid)

        merit_count = min(len(ranked_preliminary), max(1, resume_budget // 2))
        for row in ranked_preliminary[:merit_count]:
            add_resume_row(row)
        spread_count = max(0, resume_budget - len(resume_ids))
        if spread_count and preliminary:
            if spread_count == 1:
                positions = [len(preliminary) - 1]
            else:
                positions = [round(i * (len(preliminary) - 1) / float(spread_count - 1)) for i in range(spread_count)]
            for position in positions:
                add_resume_row(preliminary[max(0, min(len(preliminary) - 1, int(position)))])
        if len(resume_ids) < resume_budget:
            for row in ranked_preliminary:
                add_resume_row(row)

        resume_map = {}
        if resume_ids:
            try:
                from concurrent.futures import ThreadPoolExecutor, as_completed
                with ThreadPoolExecutor(max_workers=min(5, len(resume_ids))) as pool:
                    future_map = {
                        pool.submit(_spider_fetch_candidate_resume_text, token, cid): cid
                        for cid in resume_ids
                    }
                    for future in as_completed(future_map):
                        cid = future_map[future]
                        try:
                            text, source = future.result()
                            resume_map[cid] = {"text": str(text or ""), "source": str(source or "")}
                        except _SpiderJobAdderReconnectRequired:
                            raise
                        except Exception:
                            resume_map[cid] = {"text": "", "source": "resume text unavailable"}
            except _SpiderJobAdderReconnectRequired:
                raise
            except Exception:
                for cid in resume_ids:
                    try:
                        text, source = _spider_fetch_candidate_resume_text(token, cid)
                        resume_map[cid] = {"text": str(text or ""), "source": str(source or "")}
                    except _SpiderJobAdderReconnectRequired:
                        raise
                    except Exception:
                        resume_map[cid] = {"text": "", "source": "resume text unavailable"}

        stage_two = []
        for row in preliminary:
            resume = resume_map.get(row.get("id")) or {}
            rescored = build_scored_candidate(
                row.get("base"), row.get("index"),
                resume_text=resume.get("text") or "",
                resume_source=resume.get("source") or "",
            )
            if rescored is not None:
                stage_two.append({
                    "base": row.get("base"),
                    "id": row.get("id"),
                    "index": row.get("index"),
                    "resume_text": resume.get("text") or "",
                    "resume_source": resume.get("source") or "",
                    "score": int(rescored.get("_spiderScore") or 0),
                    "scored": rescored,
                })

        stage_two.sort(key=lambda row: (-int(row.get("score") or 0), int(row.get("index") or 0)))
        total_kept_before_limit = len(stage_two)

        # Stage 3: fetch full candidate details for the competitive return
        # pool.  With no upper experience cap, a modest ranking buffer is enough.
        # With a maximum selected, scan deeper in bounded batches until the
        # requested shortlist plus a ranking buffer is eligible, or the pool is
        # exhausted.  This prevents senior candidates near the top from hiding
        # eligible junior candidates below a fixed 12-row margin.
        _min_years, _max_years = _spider_years_bounds(safe_filters)
        experience_upper_active = _max_years is not None
        ranking_buffer = min(24, max(0, len(stage_two) - limit))
        desired_eligible = min(len(stage_two), limit + ranking_buffer)
        fixed_detail_ceiling = min(len(stage_two), desired_eligible)
        detail_scan_ceiling = len(stage_two) if experience_upper_active else fixed_detail_ceiling
        detail_batch_size = 40 if experience_upper_active else max(1, fixed_detail_ceiling)
        detail_map = {}
        filtered = []
        detail_attempted = 0
        detail_batches = 0
        cursor = 0

        while cursor < detail_scan_ceiling:
            batch_end = min(detail_scan_ceiling, cursor + detail_batch_size)
            detail_targets = stage_two[cursor:batch_end]
            cursor = batch_end
            detail_batches += 1
            detail_attempted += len(detail_targets)

            detail_ids = []
            for row in detail_targets:
                cid = str(row.get("id") or "").strip()
                if cid and cid not in detail_ids and cid not in detail_map:
                    detail_ids.append(cid)
            if detail_ids:
                try:
                    from concurrent.futures import ThreadPoolExecutor, as_completed
                    with ThreadPoolExecutor(max_workers=min(6, len(detail_ids))) as pool:
                        future_map = {pool.submit(_spider_fetch_candidate_detail, token, cid): cid for cid in detail_ids}
                        for future in as_completed(future_map):
                            cid = future_map[future]
                            try:
                                detail = future.result()
                                detail_map[cid] = detail if isinstance(detail, dict) else None
                            except _SpiderJobAdderReconnectRequired:
                                raise
                            except Exception:
                                detail_map[cid] = None
                except _SpiderJobAdderReconnectRequired:
                    raise
                except Exception:
                    for cid in detail_ids:
                        try:
                            detail_map[cid] = _spider_fetch_candidate_detail(token, cid)
                        except _SpiderJobAdderReconnectRequired:
                            raise
                        except Exception:
                            detail_map[cid] = None

            for row in detail_targets:
                detail = detail_map.get(row.get("id"))
                final_item = build_scored_candidate(
                    row.get("base"), row.get("index"),
                    detail=detail,
                    resume_text=row.get("resume_text") or "",
                    resume_source=row.get("resume_source") or "",
                )
                if final_item is None:
                    detail_excluded_count += 1
                    continue
                if detail:
                    enriched_count += 1
                if row.get("resume_text"):
                    resume_scored_count += 1
                if final_item.get("_spiderUnknownFilters"):
                    unknown_count += 1
                filtered.append(final_item)

            if len(filtered) >= desired_eligible:
                break
            if not experience_upper_active:
                break

        detail_budget = detail_attempted
        experience_backfill_exhausted = bool(
            experience_upper_active and len(filtered) < min(limit, len(stage_two)) and cursor >= len(stage_two)
        )

        filtered.sort(key=lambda item: (-int(item.get("_spiderScore") or 0), int(item.get("_spiderDiscoveryIndex") or 0)))
        filtered = filtered[:limit]
        for item in filtered:
            item.pop("_spiderDiscoveryIndex", None)
        excluded_count += detail_excluded_count
        search_meta = boolean_meta.get("search", {}) if isinstance(boolean_meta, dict) else {}
        try:
            reported_total = int(search_meta.get("reported_total"))
        except Exception:
            reported_total = len(raw_items)
        summary = {
            "query": query,
            "reported_total": reported_total,
            "scanned": len(raw_items),
            "enriched_count": enriched_count,
            "excluded_count": excluded_count,
            "kept": len(filtered),
            "eligible_before_limit": total_kept_before_limit,
            "mode": search_mode,
            # Backward-compatible fields retained for existing renderers/exports.
            "returned_before_filter": len(raw_items),
            "returned_after_filter": len(filtered),
            "total_kept_before_limit": total_kept_before_limit,
            "result_limit": limit,
            "excluded": excluded_count,
            "kept_with_unknown_fields": unknown_count,
            "enriched_candidate_profiles": enriched_count,
            "resume_scored_candidates": resume_scored_count,
            "resume_scoring_budget": resume_budget,
            "detail_enrichment_budget": detail_budget,
            "detail_enrichment_batches": detail_batches,
            "experience_upper_bound_active": experience_upper_active,
            "experience_range_backfill_exhausted": experience_backfill_exhausted,
            "detail_only_excluded": detail_excluded_count,
            "ranking_pool": len(preliminary),
            "estimated_candidate_api_request_ceiling": (resume_budget * 2) + detail_budget,
            "filters_applied": safe_filters,
            "minimum_fit_percent": 10,
            "fit_scoring": "JD + recruiter Boolean/must-haves + role + nice-to-haves; latest resume text where available",
            "workflow": "JobAdder latest-resume keyword discovery, then local eligibility and 0-100 job-scope fit",
            "note": "Country is filtered locally and is never sent as JobAdder Location. The complete recruiter Boolean is attempted once; when it returns zero rows, CV Studio labels and runs a positive-term plain-keyword fallback. NOT operands are never used for discovery and visible NOT matches are excluded conservatively. Fallback membership is not treated as proof that the complete Boolean matched. Resume scoring is request-bounded (one latest attachment per selected candidate) and selected across the full discovery pool using merit plus first-to-last spread, rather than the old first-page cutoff. Full detail is then loaded for the competitive return pool so salary and notice fields can populate the cards; when a maximum experience bound is active, CV Studio scans deeper in batches until the requested eligible shortlist is filled or the discovery pool is exhausted. Missing hard-filter fields on non-enriched candidates remain visible as unknown unless Strict is enabled; explicit mismatches still exclude.",
            "pagination_incomplete": bool(search_meta.get("incomplete")),
            "pagination_warnings": list(search_meta.get("warnings") or [])[:5],
            "pages": search_meta.get("pages"),
        }

        if boolean_meta:
            summary["boolean_search"] = boolean_meta
        response_obj = parsed if isinstance(parsed, dict) else {}
        response_obj["query"] = query
        response_obj["items"] = filtered
        response_obj["filter_summary"] = summary
        return jsonify(response_obj)
    except _SpiderJobAdderReconnectRequired:
        return jsonify({
            "error": "JobAdder connection expired. Reconnect JobAdder in Settings, then run AI Crawler again.",
            "needs_reconnect": True,
            "query": query,
        }), 401
    except urllib.error.HTTPError as e:
        body = e.read().decode(errors="replace")
        if e.code == 401:
            _spider_mark_jobadder_reconnect_required()
            return jsonify({
                "error": "JobAdder connection expired. Reconnect JobAdder in Settings, then run AI Crawler again.",
                "needs_reconnect": True,
                "query": query,
            }), 401
        return jsonify({"error": "JobAdder candidate search failed: {}".format(e.code), "detail": body[:600], "query": query}), e.code
    except Exception as e:
        return jsonify({"error": str(e), "query": query}), 500

@app.route("/jobadder/create_candidate", methods=["POST"])

def jobadder_create_candidate():
    """Server-side proxy: create a new candidate."""
    token = _ja_refresh_access_token(force=False)
    if not token:
        return jsonify({"error": "Not authenticated"}), 401
    data = request.get_json(silent=True) or {}
    if not data:
        return jsonify({"error": "Invalid or empty JSON body"}), 400
    try:
        # Ensure email is flat string not array (JobAdder API requirement)
        if "email" in data and isinstance(data["email"], list):
            data["email"] = data["email"][0].get("address", "") if data["email"] else ""
        # Build payload — keep non-empty values (dicts/lists are kept if non-empty)
        payload = {}
        for k, v in data.items():
            if v is None or v == "" or v == [] or v == {}: continue
            # For nested dicts, also strip if all values are empty
            if isinstance(v, dict) and all(not vv for vv in v.values()): continue
            payload[k] = v
        body = json.dumps(payload).encode()
        import sys; print(f"[JA Create] payload keys: {list(payload.keys())}", file=sys.stderr)
        _status, result = _JOBADDER_CLIENT.request_json(
            "candidates",
            method="POST",
            body=body,
            headers={"Content-Type": "application/json"},
            token=token,
            timeout=15,
            fallback={},
            safe_to_retry=False,
            retries=0,
        )
        return jsonify(result)
    except urllib.error.HTTPError as e:
        body = e.read().decode()
        return jsonify({"error": f"JobAdder error: {e.code}", "detail": body}), e.code
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/jobadder/update_candidate", methods=["POST"])
def jobadder_update_candidate():
    """Update existing candidate profile fields via PUT /candidates/{id}."""
    token = _ja_refresh_access_token(force=False)
    if not token:
        return jsonify({"error": "Not authenticated"}), 401
    data = request.get_json(silent=True) or {}
    if not data:
        return jsonify({"error": "Invalid or empty JSON body"}), 400
    candidate_id = data.pop("candidateId", "")
    if not candidate_id:
        return jsonify({"error": "Missing candidateId"}), 400
    try:
        payload = {k: v for k, v in data.items() if v not in (None, "", [], {})}
        body = json.dumps(payload).encode()
        _status, result = _JOBADDER_CLIENT.request_json(
            "candidates/{}".format(candidate_id),
            method="PUT",
            body=body,
            headers={"Content-Type": "application/json"},
            token=token,
            timeout=15,
            fallback={},
            safe_to_retry=False,
            retries=0,
        )
        return jsonify(result)
    except urllib.error.HTTPError as e:
        body_err = e.read().decode()
        return jsonify({"error": "JobAdder error: {}".format(e.code), "detail": body_err}), e.code
    except Exception as e:
        return jsonify({"error": str(e)}), 500

def _safe_jobadder_attachment_filename(value, fallback):
    """Keep uploaded names inside one multipart header line."""
    name = os.path.basename(str(value or "").replace("\r", " ").replace("\n", " ")).strip()
    name = re.sub(r'["\\/:*?<>|]+', "_", name)
    name = re.sub(r"\s+", " ", name).strip(" .")
    if not name:
        name = fallback
    return name[:180]


@app.route("/jobadder/upload_original_cv", methods=["POST"])
def jobadder_upload_original_cv():
    """Upload original (unformatted) CV as Resume attachment.
    Endpoint: POST /candidates/{id}/attachments/Resume
    Field: fileData (binary)
    """
    token = _ja_refresh_access_token(force=False)
    if not token:
        return jsonify({"error": "Not authenticated"}), 401
    candidate_id = request.form.get("candidate_id", "")
    file = request.files.get("file")
    if not candidate_id or not file:
        return jsonify({"error": "Missing candidate_id or file"}), 400
    try:
        file_data = file.read()
        filename  = _safe_jobadder_attachment_filename(file.filename, "Original_CV.pdf")
        boundary  = "----CVStudioBoundary7MA4YWxkTrZu0gW"
        bnd       = boundary.encode()
        crlf      = b"\x0d\x0a"
        body  = b"--" + bnd + crlf
        body += b'Content-Disposition: form-data; name="fileData"; filename="' + filename.encode("utf-8", errors="replace") + b'"' + crlf
        body += b"Content-Type: application/octet-stream" + crlf + crlf
        body += file_data + crlf
        body += b"--" + bnd + b"--" + crlf
        response = _JOBADDER_CLIENT.request_raw(
            "candidates/{}/attachments/Resume".format(candidate_id),
            method="POST",
            body=body,
            token=token,
            headers={
                "Accept": "application/json",
                "Content-Type": "multipart/form-data; boundary=" + boundary
            },
            timeout=30,
            safe_to_retry=False,
            retries=0,
        )
        return jsonify({"ok": True, "response": response.body.decode() if response.body else ""})
    except urllib.error.HTTPError as e:
        err_body = e.read().decode()
        return jsonify({"error": "JobAdder error: {}".format(e.code), "detail": err_body}), e.code
    except Exception as e:
        return jsonify({"error": str(e)}), 500

