_LEAD_EMAIL_BLOCKED_PERSONAL_DOMAINS = {
    "gmail.com", "googlemail.com", "yahoo.com", "yahoo.com.my", "yahoo.com.sg", "ymail.com", "rocketmail.com",
    "hotmail.com", "hotmail.com.my", "hotmail.co.uk", "outlook.com", "outlook.my", "live.com", "live.com.my", "msn.com",
    "icloud.com", "me.com", "mac.com", "proton.me", "protonmail.com", "pm.me",
    "aol.com", "mail.com", "email.com", "gmx.com", "gmx.net", "fastmail.com", "hey.com",
    "tuta.com", "tutanota.com", "zoho.com", "yandex.com", "yandex.ru", "qq.com", "163.com", "126.com",
    "rediffmail.com", "mail.ru", "inbox.com", "hushmail.com", "lavabit.com"
}
_LEAD_EMAIL_BLOCKED_DOMAIN_SUFFIXES = (
    ".gmail.com", ".googlemail.com", ".yahoo.com", ".hotmail.com", ".outlook.com", ".live.com",
    ".icloud.com", ".protonmail.com", ".proton.me", ".mail.com", ".gmx.com", ".yandex.com"
)
_LEAD_EMAIL_RE = re.compile(r"^[A-Z0-9._%+\-']+@([A-Z0-9.\-]+\.[A-Z]{2,})$", re.I)


def _lead_email_domain(email):
    """Return the normalized domain for a syntactically plausible email."""
    email = str(email or "").strip().strip("<>()[]{}.,;:'\" ")
    m = _LEAD_EMAIL_RE.match(email)
    if not m:
        return ""
    domain = m.group(1).lower().strip(".")
    return domain


def _lead_is_company_domain_email(email, company=""):
    """Accept only non-personal, non-free-mail business-domain emails.

    This intentionally does not guess or pattern-match company domains. It only
    removes obvious personal/free-mail domains and malformed addresses, because
    legitimate public business emails can appear on parent-company, agency,
    conference, or directory domains that do not text-match the company name.
    """
    domain = _lead_email_domain(email)
    if not domain:
        return False
    if domain in _LEAD_EMAIL_BLOCKED_PERSONAL_DOMAINS:
        return False
    if any(domain.endswith(suffix) for suffix in _LEAD_EMAIL_BLOCKED_DOMAIN_SUFFIXES):
        return False
    # Common placeholders/test domains should never be treated as real contacts.
    if domain in {"example.com", "example.org", "example.net", "test.com", "localhost"}:
        return False
    return True


def _lead_sanitize_public_business_emails(people):
    """Clear personal/free-mail or malformed emails before returning/caching.

    The Lead Finder email step is for public business/company-domain review only.
    LinkedIn/profile URLs can be identity context; email values themselves must
    come from a non-personal business domain.
    """
    if not isinstance(people, list):
        return []
    cleaned = []
    for p in people:
        if not isinstance(p, dict):
            continue
        item = dict(p)
        email = str(item.get("email") or "").strip()
        if email and not _lead_is_company_domain_email(email, item.get("company") or ""):
            item["email"] = ""
            item["email_confidence"] = ""
            item["email_source"] = ""
            item["verification_status"] = "Not found"
            note = str(item.get("notes") or "").strip()
            block_note = "Removed personal/free-mail or invalid email; public business-domain email required."
            item["notes"] = (note + " " + block_note).strip() if note and block_note not in note else (note or block_note)
        elif not email and not str(item.get("verification_status") or "").strip():
            item["verification_status"] = "Not found"
        cleaned.append(item)
    return cleaned


def _lead_normalize_linkedin_url(url):
    """Strip scheme/www/tracking-param/fragment differences so the same profile
    always yields the same cache key, regardless of how the URL happened to be
    written (http vs https, with/without www, with/without trailing slash, with
    tracking query params attached).
    """
    url = str(url or "").strip()
    if not url:
        return ""
    if re.match(r"^(?:www\.)?linkedin\.com/", url, flags=re.I):
        url = "https://" + url
    try:
        u = urllib.parse.urlparse(url)
        host = (u.netloc or "").lower()
        if "linkedin.com" not in host:
            return ""
        host = re.sub(r"^www\.", "", host)
        path = u.path.rstrip("/")
        return f"https://{host}{path}".lower()
    except Exception:
        return ""


def _lead_contact_cache_key(person):
    """A LinkedIn profile URL is the most reliable identity anchor when present
    (two different people are essentially never the same profile URL). Falling
    back to name+company is a reasonable second choice, but is more prone to
    collisions (common names, similarly-named companies) so is only used when
    no profile URL is available at all.
    """
    person = person or {}
    li = _lead_normalize_linkedin_url(person.get("profile_url") or person.get("linkedin_url"))
    if li:
        return "li:" + li
    name = re.sub(r"\s+", " ", str(person.get("name") or "").strip().lower())
    company = re.sub(r"\s+", " ", str(person.get("company") or "").strip().lower())
    if name and company:
        return "nc:" + name + "|" + company
    return ""


def _lead_contact_cache_find(person):
    key = _lead_contact_cache_key(person)
    if not key:
        return None
    data = _lead_contact_cache_load()
    cached = data.get("entries", {}).get(key)
    if not isinstance(cached, dict):
        return None
    # Do not let previous misses become permanent. A cached "Not found" with
    # no email is retry-eligible, so Apollo/AI can try again on a later run.
    if not str(cached.get("email") or "").strip() and str(cached.get("verification_status") or "").strip().lower() == "not found":
        return None
    return cached


def _lead_contact_cache_store(person, email_data):
    key = _lead_contact_cache_key(person)
    if not key:
        return
    email_data = dict(email_data or {})
    email = str(email_data.get("email") or "").strip()
    if not email or not _lead_is_company_domain_email(email, (person or {}).get("company") or email_data.get("company") or ""):
        # Failed/Not-found/personal-email results should not poison the cache.
        # If an older version cached a miss, remove it so the person can be retried.
        data = _lead_contact_cache_load()
        entries = data.get("entries", {})
        if key in entries:
            entries.pop(key, None)
            data["entries"] = entries
            _lead_contact_cache_save(data)
        return
    data = _lead_contact_cache_load()
    entries = data.get("entries", {})
    existing = entries.get(key) or {}
    entries[key] = {
        "email": email,
        "email_confidence": email_data.get("email_confidence", ""),
        "email_source": email_data.get("email_source", ""),
        "verification_status": email_data.get("verification_status", ""),
        "cached_at": datetime.utcnow().isoformat(),
        "hits": int(existing.get("hits") or 0),
    }
    if len(entries) > _LEAD_CONTACT_CACHE_MAX_ENTRIES:
        # Drop the least-reused entries first, matching the merge tool's logic.
        ordered = sorted(entries.items(), key=lambda kv: int(kv[1].get("hits") or 0))
        for k, _ in ordered[: len(entries) - _LEAD_CONTACT_CACHE_MAX_ENTRIES]:
            entries.pop(k, None)
    data["entries"] = entries
    _lead_contact_cache_save(data)


def _lead_contact_cache_touch(person):
    try:
        key = _lead_contact_cache_key(person)
        if not key:
            return
        data = _lead_contact_cache_load()
        entries = data.get("entries", {})
        if key in entries:
            entries[key]["hits"] = int(entries[key].get("hits") or 0) + 1
            _lead_contact_cache_save(data)
    except Exception:
        pass


class _LeadApolloRateLimited(Exception):
    """Raised when Apollo returns 429, so a batch enrichment run can stop
    immediately instead of continuing to burn through remaining quota-limited
    calls that would just fail the same way."""
    pass


class _LeadApolloAuthError(Exception):
    """Raised on 401/403 so the person can be told to check their API key,
    rather than every person in the batch silently coming back 'Not found'."""
    pass


def _lead_apollo_enrich_person(api_key, person, timeout=15):
    """Look up one person via Apollo's People Match endpoint.

    Uses name + organization_name + linkedin_url (when available) rather than
    Apollo's internal person IDs, since we never have those — this is the
    documented, reliably-working input shape for this endpoint. Only the
    business email is requested (reveal_personal_emails/reveal_phone_number
    are left False) to stay consistent with this tool's existing
    business-email-only stance.
    """
    name = re.sub(r"\s+", " ", str(person.get("name") or "").strip())
    company = re.sub(r"\s+", " ", str(person.get("company") or "").strip())
    linkedin_url = _lead_normalize_linkedin_url(person.get("profile_url") or person.get("linkedin_url"))
    if not name and not linkedin_url:
        return {"email": "", "email_confidence": "", "email_source": "", "verification_status": "Not found"}

    name_parts = name.split(" ", 1)
    body = {
        "reveal_personal_emails": False,
        "reveal_phone_number": False,
    }
    if name_parts:
        body["first_name"] = name_parts[0]
    if len(name_parts) > 1:
        body["last_name"] = name_parts[1]
    if name:
        body["name"] = name
    if company:
        body["organization_name"] = company
    if linkedin_url:
        body["linkedin_url"] = linkedin_url

    params = urllib.parse.urlencode(
        {k: (str(v).lower() if isinstance(v, bool) else v) for k, v in body.items()},
        doseq=True,
    )
    req_url = "https://api.apollo.io/api/v1/people/match" + ("?" + params if params else "")
    req = urllib.request.Request(req_url, data=b"", method="POST", headers={
        "accept": "application/json",
        "x-api-key": str(api_key or "").strip(),
    })
    context = _lead_ssl_context()
    try:
        if context is not None:
            resp_cm = urllib.request.urlopen(req, timeout=timeout, context=context)
        else:
            resp_cm = urllib.request.urlopen(req, timeout=timeout)
        with resp_cm as resp:
            data = json.loads(resp.read().decode("utf-8", errors="replace"))
    except urllib.error.HTTPError as e:
        if e.code == 429:
            raise _LeadApolloRateLimited("Apollo API rate limit hit (429).")
        if e.code in (401, 403):
            raise _LeadApolloAuthError(f"Apollo API authentication failed ({e.code}). Check the Apollo API key.")
        try:
            body_txt = e.read().decode("utf-8", errors="replace")[:300]
        except Exception:
            body_txt = ""
        raise RuntimeError(f"Apollo API error {e.code}: {body_txt or str(e)}")

    p = data.get("person") if isinstance(data, dict) else None
    if not isinstance(p, dict) or not p.get("email"):
        return {"email": "", "email_confidence": "", "email_source": "", "verification_status": "Not found"}

    email = str(p.get("email") or "").strip()
    if not _lead_is_company_domain_email(email, company):
        return {"email": "", "email_confidence": "", "email_source": "", "verification_status": "Not found"}

    email_status = str(p.get("email_status") or "").strip().lower()
    confidence = "High" if email_status == "verified" else ("Medium" if email_status else "Low")
    return {
        "email": email,
        "email_confidence": confidence,
        "email_source": "Apollo People Match API",
        "verification_status": "Verified business email" if email_status == "verified" else "Public business email",
    }


def _lead_title_cache_touch(matched_entry):
    """Best-effort hit counter. Not critical if a concurrent write races it."""
    try:
        data = _lead_title_cache_load()
        for e in data.get("entries", []):
            if e.get("family") == matched_entry.get("family") and e.get("evidence") == matched_entry.get("evidence"):
                e["hits"] = int(e.get("hits") or 0) + 1
                break
        _lead_title_cache_save(data)
    except Exception:
        pass


def _lead_ai_expand_title_angles(api_key, model, target_role, cv_excerpt, candidate_context, industries, primary_families=None, max_titles=18, timeout=20, llm_provider="anthropic"):
    """Ask Claude to generate recruiter title-search angles directly from the CV.

    This SUPPLEMENTS the static family-based title bank rather than replacing
    it. The static bank is free, fast, and deterministic but only covers
    verticals someone has explicitly coded a pattern for (which is why DBA,
    SAP Basis, payroll, etc. kept slipping through). This call is a small,
    cheap, text-only request (no web search tool) that reads the actual CV and
    proposes title angles for whatever role the candidate actually has, so
    unusual/niche titles get reasonable coverage without a code change.
    """
    prompt = f"""
You are helping a recruiter build a list of alternative job-title search angles
for ONE candidate, based only on their actual CV and stated target role.

STRICT RULES
- Stay within the candidate's own job function/department. Do NOT branch into
  an unrelated function (e.g. do not suggest HR titles for a Finance candidate,
  or Sales titles for an Engineering candidate).
- Include the exact target role/title itself, plus realistic seniority variants
  (junior/senior/lead/head/manager as appropriate for that function) and
  equivalent titles used by different companies/countries for the same role.
- Do not invent a title with no basis in the CV or target role.
- Return 10-18 titles, ranked most relevant first.

TARGET ROLE
{target_role or "Infer from the CV"}

INDUSTRY FOCUS
{industries or "Infer from the CV"}

RECRUITER CONTEXT
{candidate_context[:800] or "None provided."}

CANDIDATE CV EXCERPT
{cv_excerpt[:4000]}

RETURN ONLY VALID JSON. No markdown. Shape exactly:
{{"titles": ["title 1", "title 2"]}}
""".strip()
    payload = {
        "model": model,
        "max_tokens": 600,
        "messages": [{"role": "user", "content": prompt}],
        "_timeout_seconds": timeout,
    }
    try:
        data = call_llm(llm_provider, api_key, payload)
    except Exception:
        return [], {}, "AI title expansion call failed; continuing with the built-in title bank only."
    raw_text = "".join(b.get("text", "") for b in data.get("content", []) if b.get("type") == "text" or "text" in b)
    usage = data.get("usage", {}) or {}
    try:
        parsed = _lead_extract_json(raw_text)
    except Exception:
        return [], usage, "AI title expansion returned malformed output; continuing with the built-in title bank only."
    titles = parsed.get("titles") if isinstance(parsed, dict) else None
    if not isinstance(titles, list):
        return [], usage, "AI title expansion returned no usable titles; continuing with the built-in title bank only."
    clean = []
    seen = set()
    for t in titles:
        t = re.sub(r"\s+", " ", str(t or "")).strip()
        if not t or len(t) > 80:
            continue
        k = t.lower()
        if k in seen:
            continue
        seen.add(k)
        clean.append(t)
    # If we already confidently know the candidate's primary role family, drop
    # any AI-suggested title that clearly maps to a *different* known family.
    # Titles with no detectable family (novel/niche roles) are kept as-is,
    # since the static bank has no opinion on them either.
    if primary_families:
        filtered = []
        for t in clean:
            t_fams = _lead_families_from_text(t, max_families=2)
            if not t_fams or set(t_fams).intersection(primary_families):
                filtered.append(t)
        clean = filtered
    return clean[:max_titles], usage, ""


